CREATE OR ALTER PROCEDURE dbo.sp_trans_crear
  @SUC_ENT NVARCHAR(20),
  @SUC_SAL NVARCHAR(20),
  @MTV NVARCHAR(20),
  @PRIO NVARCHAR(20),
  @TXT NVARCHAR(255) = NULL,
  @USER NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  BEGIN TRY
    BEGIN TRANSACTION;

    SET @SUC_ENT = UPPER(LTRIM(RTRIM(ISNULL(@SUC_ENT, ''))));
    SET @SUC_SAL = UPPER(LTRIM(RTRIM(ISNULL(@SUC_SAL, ''))));
    SET @MTV = UPPER(LTRIM(RTRIM(ISNULL(@MTV, ''))));
    SET @PRIO = UPPER(LTRIM(RTRIM(ISNULL(@PRIO, 'NORMAL'))));

    IF @SUC_ENT = '' OR @SUC_SAL = ''
      THROW 59100, 'Sucursal solicitante y origen son requeridas.', 1;
    IF @SUC_ENT = @SUC_SAL
      THROW 59101, 'Sucursal solicitante y origen no pueden ser iguales.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.DAT_SUC WHERE UPPER(LTRIM(RTRIM(SUC))) = @SUC_ENT)
      THROW 59102, 'Sucursal solicitante no existe.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.DAT_SUC WHERE UPPER(LTRIM(RTRIM(SUC))) = @SUC_SAL)
      THROW 59103, 'Sucursal origen no existe.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.MOV_TRAN WHERE CLAVE = @MTV)
      THROW 59104, 'Motivo de transferencia invalido.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.PRIO_TRAN WHERE [DESC] = @PRIO)
      THROW 59105, 'Prioridad invalida.', 1;

    DECLARE @next BIGINT;
    SELECT @next = ISNULL(MAX(TRY_CONVERT(BIGINT, DOC)), 1000) + 1
    FROM dbo.TRAN_CTR_DOCPRE WITH (UPDLOCK, HOLDLOCK);

    DECLARE @DOC NVARCHAR(255) = CONVERT(NVARCHAR(255), @next);
    INSERT INTO dbo.TRAN_CTR_DOCPRE
      (DOC, FCND, FCNC, CTD, IMP, ESTATUS, TXT, ALM_SAL, ALM_ENT, USR, SUC_ENT, SUC_SAL, MTV, PRIO)
    VALUES
      (@DOC, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())), NULL, 0, 0, 'BORRADOR', @TXT, '001', '001', @USER, @SUC_ENT, @SUC_SAL, @MTV, @PRIO);

    COMMIT TRANSACTION;

    SELECT @DOC AS DOC;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_trans_enviar
  @DOC NVARCHAR(255),
  @USER NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @estatus NVARCHAR(30);
    SELECT @estatus = UPPER(LTRIM(RTRIM(ISNULL(ESTATUS, ''))))
    FROM dbo.TRAN_CTR_DOCPRE WITH (UPDLOCK, HOLDLOCK)
    WHERE DOC = @DOC;

    IF @estatus IS NULL THROW 59110, 'Documento no existe.', 1;
    IF @estatus <> 'BORRADOR' THROW 59111, 'Solo se puede enviar desde BORRADOR.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.TRAN_DET_ART WHERE DOC = @DOC AND ISNULL(BLOQ, 0) <> -1)
      THROW 59112, 'Documento sin articulos activos.', 1;
    IF EXISTS (
      SELECT 1 FROM dbo.TRAN_DET_ART
      WHERE DOC = @DOC AND ISNULL(BLOQ, 0) <> -1 AND ISNULL(TRY_CONVERT(FLOAT, CTD), 0) <= 0
    )
      THROW 59113, 'Todos los articulos deben tener cantidad solicitada mayor a cero.', 1;

    EXEC dbo.sp_trans_recalcular @DOC = @DOC;

    UPDATE dbo.TRAN_CTR_DOCPRE
    SET ESTATUS = 'PENDIENTE',
        FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    WHERE DOC = @DOC;

    COMMIT TRANSACTION;
    SELECT DOC, ESTATUS FROM dbo.TRAN_CTR_DOCPRE WHERE DOC = @DOC;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_trans_liberar
  @DOC NVARCHAR(255),
  @USER NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @sucSal NVARCHAR(20), @estatus NVARCHAR(30);
    SELECT
      @sucSal = LTRIM(RTRIM(ISNULL(SUC_SAL, ALM_SAL))),
      @estatus = UPPER(LTRIM(RTRIM(ISNULL(ESTATUS, ''))))
    FROM dbo.TRAN_CTR_DOCPRE WITH (UPDLOCK, HOLDLOCK)
    WHERE DOC = @DOC;

    IF @estatus IS NULL THROW 59120, 'Documento no existe.', 1;
    IF @estatus <> 'PENDIENTE' THROW 59121, 'Solo se puede liberar desde PENDIENTE.', 1;

    UPDATE d
    SET d.CTD_LIB = CASE
          WHEN ISNULL(TRY_CONVERT(FLOAT, d.CTD_LIB), 0) <= 0
            THEN ISNULL(TRY_CONVERT(FLOAT, d.CTD), 0)
          ELSE TRY_CONVERT(FLOAT, d.CTD_LIB)
        END,
        d.CTOLIB = CASE
          WHEN ISNULL(TRY_CONVERT(FLOAT, d.CTD_LIB), 0) <= 0
            THEN ISNULL(TRY_CONVERT(FLOAT, d.CTD), 0)
          ELSE TRY_CONVERT(FLOAT, d.CTD_LIB)
        END * ISNULL(a.CTOP, 0),
        d.CTOTAL = ISNULL(TRY_CONVERT(FLOAT, d.CTD), 0) * ISNULL(a.CTOP, 0),
        d.USR_L = @USER
    FROM dbo.TRAN_DET_ART d
    LEFT JOIN dbo.DAT_ART a
      ON LTRIM(RTRIM(ISNULL(a.SUC, ''))) = @sucSal
     AND LTRIM(RTRIM(ISNULL(a.ART, ''))) = LTRIM(RTRIM(ISNULL(d.ART, '')))
    WHERE d.DOC = @DOC AND ISNULL(d.BLOQ, 0) <> -1;

    IF EXISTS (
      SELECT 1
      FROM dbo.TRAN_DET_ART d
      JOIN dbo.DAT_ART a
        ON LTRIM(RTRIM(ISNULL(a.SUC, ''))) = @sucSal
       AND LTRIM(RTRIM(ISNULL(a.ART, ''))) = LTRIM(RTRIM(ISNULL(d.ART, '')))
      WHERE d.DOC = @DOC
        AND ISNULL(d.BLOQ, 0) <> -1
        AND ISNULL(d.CTD_LIB, 0) < 0
    )
      THROW 59122, 'La cantidad liberada no puede ser negativa.', 1;

    UPDATE h
    SET h.CTD = calc.CTD,
        h.IMP = calc.IMP,
        h.ESTATUS = 'LIBERADA',
        h.USR_L = @USER,
        h.FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.TRAN_CTR_DOCPRE h
    CROSS APPLY (
      SELECT
        SUM(CASE WHEN ISNULL(d.BLOQ, 0) = -1 THEN 0 ELSE ISNULL(d.CTD_LIB, 0) END) AS CTD,
        SUM(CASE WHEN ISNULL(d.BLOQ, 0) = -1 THEN 0 ELSE ISNULL(d.CTOLIB, 0) END) AS IMP
      FROM dbo.TRAN_DET_ART d
      WHERE d.DOC = h.DOC
    ) calc
    WHERE h.DOC = @DOC;

    COMMIT TRANSACTION;
    SELECT DOC, ESTATUS FROM dbo.TRAN_CTR_DOCPRE WHERE DOC = @DOC;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_trans_rechazar
  @DOC NVARCHAR(255),
  @USER NVARCHAR(100),
  @TXT NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  UPDATE dbo.TRAN_CTR_DOCPRE
  SET ESTATUS = 'RECHAZADA',
      TXT = COALESCE(@TXT, TXT),
      USR_L = @USER,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
  WHERE DOC = @DOC
    AND UPPER(LTRIM(RTRIM(ISNULL(ESTATUS, '')))) = 'PENDIENTE';

  IF @@ROWCOUNT = 0 THROW 59130, 'Solo se puede rechazar desde PENDIENTE.', 1;
  SELECT DOC, ESTATUS FROM dbo.TRAN_CTR_DOCPRE WHERE DOC = @DOC;
END;

/* 4) Aplicar merma o cambio desde 9.3 -> 9.1 / 9.2 */
CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_aplicar_merma_cambio
  @IORD NVARCHAR(255),
  @TIPOM INT,
  @MOTR INT,
  @OBS NVARCHAR(255) = NULL,
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;

  IF @TIPOM NOT IN (1, 2)
    THROW 58031, 'TIPOM debe ser 1 (CAMBIO) o 2 (MERMA).', 1;

  IF @MOTR IS NULL OR @MOTR <= 0
    THROW 58032, 'MOTR es requerido y debe ser mayor a 0.', 1;

  DECLARE @targetFlow FLOAT = CASE WHEN @TIPOM = 1 THEN 9.1 ELSE 9.2 END;

  IF NOT EXISTS (
    SELECT 1
    FROM dbo.PV_CTR_ORDS o
    WHERE o.IORD = @IORD
      AND ABS(TRY_CONVERT(FLOAT, o.ESTSEGU) - 9.3) <= 0.0001
  )
  BEGIN
    THROW 58033, 'La ORD debe estar en flujo 9.3 para aplicar merma o cambio.', 1;
  END

  EXEC dbo.sp_ordenes_trabajo_set_estado
    @IORD = @IORD,
    @ESTSEGU = @targetFlow,
    @ESTATUS = 2,
    @OBS = @OBS,
    @USER = @USER,
    @IP = @IP,
    @IS_ADMIN = @IS_ADMIN,
    @ALLOWED_SUCS = @ALLOWED_SUCS,
    @SUC = @SUC;

  DECLARE @sqlUpdate NVARCHAR(MAX) = N'UPDATE dbo.PV_CTR_ORDS SET FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))';
  IF COL_LENGTH('dbo.PV_CTR_ORDS', 'TIPOM') IS NOT NULL
    SET @sqlUpdate += N', TIPOM = @P_TIPOM';
  IF COL_LENGTH('dbo.PV_CTR_ORDS', 'TPOM') IS NOT NULL
    SET @sqlUpdate += N', TPOM = @P_TIPOM';
  IF COL_LENGTH('dbo.PV_CTR_ORDS', 'MOTR') IS NOT NULL
    SET @sqlUpdate += N', MOTR = @P_MOTR';
  SET @sqlUpdate += N' WHERE IORD = @P_IORD';
  EXEC sp_executesql
    @sqlUpdate,
    N'@P_TIPOM INT, @P_MOTR INT, @P_IORD NVARCHAR(255)',
    @P_TIPOM = @TIPOM,
    @P_MOTR = @MOTR,
    @P_IORD = @IORD;

  SELECT TOP 1
    o.IORD,
    o.IDFOL,
    o.ESTATUS,
    o.ESTSEGU,
    o.TIPOM,
    o.MOTR,
    o.SUC,
    o.FCNMOD,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR
  FROM dbo.PV_CTR_ORDS o
  WHERE o.IORD = @IORD;
END;

CREATE OR ALTER PROCEDURE dbo.sp_trans_preparar
  @DOC NVARCHAR(255),
  @USER NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON;
  UPDATE dbo.TRAN_CTR_DOCPRE
  SET ESTATUS = 'PREPARACION',
      USR_E = @USER,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
  WHERE DOC = @DOC
    AND UPPER(LTRIM(RTRIM(ISNULL(ESTATUS, '')))) = 'LIBERADA';

  IF @@ROWCOUNT = 0 THROW 59140, 'Solo se puede preparar desde LIBERADA.', 1;
  SELECT DOC, ESTATUS FROM dbo.TRAN_CTR_DOCPRE WHERE DOC = @DOC;
END;

/*
  Consulta / RecepciÃ³n en tienda:
  - Permite rechazar la recepciÃ³n de ORDs en flujo 9 con motivo obligatorio.
  - Devuelve cada ORD al flujo 5 (entregada a taller), manteniendo su TIPO
    registrado (TALLADO o BISELADO) para que el taller la reciba nuevamente.
*/

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_regresar_tienda_rechazar_lote
  @IORDS NVARCHAR(MAX),
  @MOTIVO NVARCHAR(500),
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @motivoNorm NVARCHAR(500) = LTRIM(RTRIM(ISNULL(@MOTIVO, N'')));
  IF LEN(@motivoNorm) < 3
    THROW 58340, 'El motivo del rechazo es obligatorio y debe tener al menos 3 caracteres.', 1;

  DECLARE @ords TABLE (IORD NVARCHAR(255) NOT NULL PRIMARY KEY);
  INSERT INTO @ords (IORD)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(ISNULL(value, N''))))
  FROM STRING_SPLIT(ISNULL(@IORDS, N''), N',')
  WHERE LTRIM(RTRIM(ISNULL(value, N''))) <> N'';

  IF NOT EXISTS (SELECT 1 FROM @ords)
    THROW 58341, 'Debe enviar al menos una ORD en @IORDS.', 1;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, N''), N',')
  WHERE LTRIM(RTRIM(ISNULL(value, N''))) <> N'';

  DECLARE @target TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY,
    IDFOL NVARCHAR(255) NULL,
    SUC NVARCHAR(10) NULL,
    TIPO NVARCHAR(50) NULL,
    ESTSEGU FLOAT NULL
  );

  BEGIN TRY
    BEGIN TRANSACTION;

    INSERT INTO @target (IORD, IDFOL, SUC, TIPO, ESTSEGU)
    SELECT
      UPPER(LTRIM(RTRIM(ISNULL(o.IORD, N'')))),
      o.IDFOL,
      o.SUC,
      UPPER(LTRIM(RTRIM(ISNULL(o.TIPO, N'')))),
      TRY_CONVERT(FLOAT, o.ESTSEGU)
    FROM dbo.PV_CTR_ORDS o WITH (UPDLOCK, HOLDLOCK)
    LEFT JOIN dbo.DAT_LAB lab
      ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
    INNER JOIN @ords i
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, N'')))) = i.IORD
    WHERE
      (
        @SUC IS NULL
        OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, N'')))) = UPPER(@SUC)
        OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, N'')))) = UPPER(@SUC)
      )
      AND (
        @IS_ADMIN = 1
        OR NOT EXISTS (SELECT 1 FROM @allowed)
        OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, N'')))) IN (SELECT SUC FROM @allowed)
        OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, N'')))) IN (SELECT SUC FROM @allowed)
      );

    IF EXISTS (
      SELECT 1
      FROM @ords i
      LEFT JOIN @target t ON t.IORD = i.IORD
      WHERE t.IORD IS NULL
    )
    BEGIN
      DECLARE @missingIords NVARCHAR(2000) = (
        SELECT STRING_AGG(i.IORD, N', ')
        FROM @ords i
        LEFT JOIN @target t ON t.IORD = i.IORD
        WHERE t.IORD IS NULL
      );
      DECLARE @missingMsg NVARCHAR(2048) = LEFT(
        CONCAT(N'ORD no encontrada o sin acceso por sucursal: ', ISNULL(@missingIords, N'')),
        2048
      );
      THROW 58342, @missingMsg, 1;
    END;

    IF EXISTS (SELECT 1 FROM @target WHERE ISNULL(ESTSEGU, -1) <> 9)
    BEGIN
      DECLARE @invalidFlowIords NVARCHAR(2000) = (
        SELECT STRING_AGG(IORD, N', ')
        FROM @target
        WHERE ISNULL(ESTSEGU, -1) <> 9
      );
      DECLARE @invalidFlowMsg NVARCHAR(2048) = LEFT(
        CONCAT(N'Solo se pueden rechazar ORDs en estatus 9: ', ISNULL(@invalidFlowIords, N'')),
        2048
      );
      THROW 58343, @invalidFlowMsg, 1;
    END;

    IF EXISTS (
      SELECT 1
      FROM @target
      WHERE TIPO NOT IN (N'TALLADO', N'TALLER', N'BISELADO', N'BISEL')
    )
    BEGIN
      DECLARE @invalidTypeIords NVARCHAR(2000) = (
        SELECT STRING_AGG(IORD, N', ')
        FROM @target
        WHERE TIPO NOT IN (N'TALLADO', N'TALLER', N'BISELADO', N'BISEL')
      );
      DECLARE @invalidTypeMsg NVARCHAR(2048) = LEFT(
        CONCAT(N'La ORD no tiene tipo TALLADO o BISELADO: ', ISNULL(@invalidTypeIords, N'')),
        2048
      );
      THROW 58344, @invalidTypeMsg, 1;
    END;

    UPDATE o
    SET
      o.ESTSEGU = 5,
      o.ESTATUS = 2,
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    INNER JOIN @target t
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, N'')))) = t.IORD;

    COMMIT TRANSACTION;

    SELECT
      o.IORD,
      o.IDFOL,
      o.SUC,
      o.TIPO,
      o.ESTATUS,
      o.ESTSEGU,
      @motivoNorm AS MOTIVO_RECHAZO,
      o.FCNMOD,
      @USER AS USER_ACTOR,
      @IP AS IP_ACTOR
    FROM dbo.PV_CTR_ORDS o
    INNER JOIN @target t
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, N'')))) = t.IORD
    ORDER BY o.IORD;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;
END;

/*
  DAT_MB51 representa el inventario acumulado mediante SUM(CTDA).
  Por ello, las salidas deben persistirse con CTDA/CTOT negativos:
    - transferencia, movimiento 121, en la sucursal origen;
    - merma, en la sucursal que contabiliza el documento.
  Las cantidades capturadas en las tablas de detalle se conservan positivas.
*/

CREATE OR ALTER PROCEDURE dbo.sp_trans_transito
  @DOC NVARCHAR(255),
  @USER NVARCHAR(100),
  @EMP NVARCHAR(120) = NULL,
  @NUM_GUIA NVARCHAR(120) = NULL,
  @RESP NVARCHAR(120) = NULL,
  @TXT NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @sucSal NVARCHAR(20), @estatus NVARCHAR(30), @docBase BIGINT;
    SELECT
      @sucSal = LTRIM(RTRIM(ISNULL(SUC_SAL, ALM_SAL))),
      @estatus = UPPER(LTRIM(RTRIM(ISNULL(ESTATUS, ''))))
    FROM dbo.TRAN_CTR_DOCPRE WITH (UPDLOCK, HOLDLOCK)
    WHERE DOC = @DOC;

    IF @estatus IS NULL THROW 59150, 'Documento no existe.', 1;
    IF @estatus <> 'PREPARACION' THROW 59151, 'Solo se puede enviar a transito desde PREPARACION.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.DAT_CMOV WHERE CMOV = 121)
      THROW 59152, 'DAT_CMOV no tiene configurado el movimiento 121.', 1;

    SELECT @docBase = TRY_CONVERT(BIGINT, NDOC)
    FROM dbo.DAT_CMOV WITH (UPDLOCK, HOLDLOCK)
    WHERE CMOV = 121;
    IF @docBase IS NULL SET @docBase = 121000000;
    SET @docBase = @docBase + 1;
    UPDATE dbo.DAT_CMOV SET NDOC = @docBase WHERE CMOV = 121;

    INSERT INTO dbo.DAT_MB51
      (IDPD, [USER], CLSM, DOCP, ART, CTDA, CTOT, FCND, FCNC, TXT, ALMACEN, VTAESP, SUC)
    SELECT
      CONVERT(NVARCHAR(36), NEWID()), @USER, 121, @DOC, d.ART,
      -ABS(ISNULL(d.CTD_LIB, 0)),
      -ABS(ISNULL(d.CTD_LIB, 0)) * ISNULL(a.CTOP, 0),
      CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())), CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())), CONCAT('TRANSFERENCIA SALIDA DOC ', @DOC),
      '001', 0, @sucSal
    FROM dbo.TRAN_DET_ART d
    LEFT JOIN dbo.DAT_ART a
      ON LTRIM(RTRIM(ISNULL(a.SUC, ''))) = @sucSal
     AND LTRIM(RTRIM(ISNULL(a.ART, ''))) = LTRIM(RTRIM(ISNULL(d.ART, '')))
    WHERE d.DOC = @DOC
      AND ISNULL(d.BLOQ, 0) <> -1
      AND ISNULL(d.CTD_LIB, 0) > 0;

    UPDATE a
    SET a.STOCK = ISNULL(a.STOCK, 0) - ISNULL(d.CTD_LIB, 0)
    FROM dbo.DAT_ART a
    JOIN dbo.TRAN_DET_ART d
      ON LTRIM(RTRIM(ISNULL(a.ART, ''))) = LTRIM(RTRIM(ISNULL(d.ART, '')))
     AND LTRIM(RTRIM(ISNULL(a.SUC, ''))) = @sucSal
    WHERE d.DOC = @DOC
      AND ISNULL(d.BLOQ, 0) <> -1;

    INSERT INTO dbo.TRAN_PAQ_ENV (DOC, EMP, NUM_GUIA, FENV, RESP, TXT, USR)
    VALUES (@DOC, @EMP, @NUM_GUIA, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())), @RESP, @TXT, @USER);

    UPDATE dbo.TRAN_CTR_DOCPRE
    SET ESTATUS = 'TRANSITO',
        DOC_MB51_SAL = CONVERT(NVARCHAR(50), @docBase),
        USR_E = @USER,
        FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    WHERE DOC = @DOC;

    COMMIT TRANSACTION;
    SELECT DOC, ESTATUS, DOC_MB51_SAL FROM dbo.TRAN_CTR_DOCPRE WHERE DOC = @DOC;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_trans_recibir
  @DOC NVARCHAR(255),
  @USER NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @estatus NVARCHAR(30);
    SELECT @estatus = UPPER(LTRIM(RTRIM(ISNULL(ESTATUS, ''))))
    FROM dbo.TRAN_CTR_DOCPRE WITH (UPDLOCK, HOLDLOCK)
    WHERE DOC = @DOC;

    IF @estatus IS NULL THROW 59160, 'Documento no existe.', 1;
    IF @estatus <> 'TRANSITO' THROW 59161, 'Solo se puede recibir desde TRANSITO.', 1;

    UPDATE d
    SET d.CTD_R = CASE WHEN d.CTD_R IS NULL THEN ISNULL(d.CTD_LIB, 0) ELSE d.CTD_R END,
        d.CTO_R = CASE WHEN d.CTD_R IS NULL THEN ISNULL(d.CTD_LIB, 0) ELSE d.CTD_R END * ISNULL(a.CTOP, 0),
        d.DIF_R = ISNULL(d.CTD_LIB, 0) - CASE WHEN d.CTD_R IS NULL THEN ISNULL(d.CTD_LIB, 0) ELSE d.CTD_R END,
        d.DIFCTO_R = (ISNULL(d.CTD_LIB, 0) - CASE WHEN d.CTD_R IS NULL THEN ISNULL(d.CTD_LIB, 0) ELSE d.CTD_R END) * ISNULL(a.CTOP, 0)
    FROM dbo.TRAN_DET_ART d
    LEFT JOIN dbo.TRAN_CTR_DOCPRE h ON h.DOC = d.DOC
    LEFT JOIN dbo.DAT_ART a
      ON LTRIM(RTRIM(ISNULL(a.SUC, ''))) = LTRIM(RTRIM(ISNULL(h.SUC_SAL, h.ALM_SAL)))
     AND LTRIM(RTRIM(ISNULL(a.ART, ''))) = LTRIM(RTRIM(ISNULL(d.ART, '')))
    WHERE d.DOC = @DOC AND ISNULL(d.BLOQ, 0) <> -1;

    UPDATE dbo.TRAN_CTR_DOCPRE
    SET ESTATUS = CASE
          WHEN EXISTS (
            SELECT 1 FROM dbo.TRAN_DET_ART
            WHERE DOC = @DOC AND ISNULL(BLOQ, 0) <> -1 AND ABS(ISNULL(DIF_R, 0)) > 0.00001
          ) THEN 'INCIDENCIA'
          ELSE 'REVISANDO'
        END,
        USR_R = @USER,
        FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    WHERE DOC = @DOC;

    COMMIT TRANSACTION;
    SELECT DOC, ESTATUS FROM dbo.TRAN_CTR_DOCPRE WHERE DOC = @DOC;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_cg_validar_opv_para_entrega
  @SUC VARCHAR(25),
  @FCN DATE,
  @OPV NVARCHAR(255)
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @sucNorm VARCHAR(25) = UPPER(LTRIM(RTRIM(ISNULL(@SUC, ''))));
  DECLARE @opvNorm NVARCHAR(255) = UPPER(LTRIM(RTRIM(ISNULL(@OPV, ''))));
  DECLARE @fcnDate DATE = ISNULL(CONVERT(DATE, @FCN), CONVERT(DATE, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))));
  DECLARE @dtIni DATETIME = CAST(@fcnDate AS DATETIME);
  DECLARE @dtFin DATETIME = DATEADD(DAY, 1, @dtIni);

  IF @sucNorm = ''
  BEGIN
    SELECT
      CAST(0 AS bit) AS ok,
      'ERROR' AS [status],
      'SUC es obligatorio.' AS [message],
      0 AS pagadoCount,
      0 AS totalTransacciones;
    RETURN;
  END;

  IF @opvNorm = ''
  BEGIN
    SELECT
      CAST(0 AS bit) AS ok,
      'ERROR' AS [status],
      'OPV es obligatorio.' AS [message],
      0 AS pagadoCount,
      0 AS totalTransacciones;
    RETURN;
  END;

  DECLARE @totalTransacciones INT = 0;
  DECLARE @pagadoCount INT = 0;

  ;WITH FoliosDia AS (
    SELECT
      a.IDFOL,
      UPPER(LTRIM(RTRIM(ISNULL(
        CASE
          WHEN NULLIF(LTRIM(RTRIM(ISNULL(a.OPVM, ''))), '') IS NOT NULL THEN a.OPVM
          ELSE a.OPV
        END,
      '')))) AS OPV_ACT,
      UPPER(LTRIM(RTRIM(ISNULL(a.ESTA, '')))) AS ESTA
    FROM dbo.PV_CTR_FOL_ASVR a
    WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = @sucNorm
      AND a.FCNM >= @dtIni
      AND a.FCNM < @dtFin
      AND UPPER(LTRIM(RTRIM(ISNULL(a.AUT, '')))) NOT IN ('CP', 'CPF', 'VA')
  )
  SELECT
    @totalTransacciones = COUNT(1),
    @pagadoCount = SUM(CASE WHEN ESTA = 'PAGADO' THEN 1 ELSE 0 END)
  FROM FoliosDia
  WHERE OPV_ACT = @opvNorm;

  IF ISNULL(@pagadoCount, 0) > 0
  BEGIN
    SELECT
      CAST(0 AS bit) AS ok,
      'BLOQUEADO' AS [status],
      'No se puede preparar la entrega: existen transacciones PAGADO para el OPV. Primero deben pasar a TERMINADO.' AS [message],
      ISNULL(@pagadoCount, 0) AS pagadoCount,
      ISNULL(@totalTransacciones, 0) AS totalTransacciones;
    RETURN;
  END;

  SELECT
    CAST(1 AS bit) AS ok,
    'OK' AS [status],
    'OPV listo para preparar entrega.' AS [message],
    ISNULL(@pagadoCount, 0) AS pagadoCount,
    ISNULL(@totalTransacciones, 0) AS totalTransacciones;
END;

CREATE OR ALTER PROCEDURE dbo.sp_dev_provd_recalcular
  @DOC NVARCHAR(40)
AS
BEGIN
  SET NOCOUNT ON;
  UPDATE d SET IMPT=CONVERT(MONEY,CTDA_DEV*CTOP),FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME())
  FROM dbo.DEV_CTRL_PROVD d WHERE d.DOC=@DOC AND d.ACTIVO=1;
  UPDATE h SET FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) FROM dbo.DEV_DOC_PROVD h WHERE h.DOC=@DOC;
END;

CREATE OR ALTER PROCEDURE dbo.sp_cg_resumen_opv
  @SUC VARCHAR(25),
  @FCN DATE,
  @OPV NVARCHAR(255),
  @TIPO_CORTE VARCHAR(10) = 'GLOBAL'
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @sucNorm VARCHAR(25) = UPPER(LTRIM(RTRIM(ISNULL(@SUC, ''))));
  DECLARE @opvNorm NVARCHAR(255) = UPPER(LTRIM(RTRIM(ISNULL(@OPV, ''))));
  DECLARE @tipoNorm VARCHAR(10) = UPPER(LTRIM(RTRIM(ISNULL(@TIPO_CORTE, 'GLOBAL'))));
  DECLARE @fcnDate DATE = ISNULL(CONVERT(DATE, @FCN), CONVERT(DATE, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))));
  DECLARE @dtIni DATETIME = CAST(@fcnDate AS DATETIME);
  DECLARE @dtFin DATETIME = DATEADD(DAY, 1, @dtIni);

  IF @tipoNorm NOT IN ('CA', 'VF', 'GLOBAL')
    SET @tipoNorm = 'GLOBAL';

  IF @sucNorm = ''
    THROW 58020, 'SUC es obligatorio', 1;

  IF @opvNorm = ''
    THROW 58021, 'OPV es obligatorio', 1;

  DECLARE @serial INT = DATEDIFF(DAY, '1899-12-30', @fcnDate);
  DECLARE @ide NVARCHAR(255) = CONCAT(@serial, @opvNorm);

  DECLARE @trn FLOAT = 0;
  DECLARE @art FLOAT = 0;
  DECLARE @difCalc MONEY = 0;

  ;WITH FoliosBase AS (
    SELECT
      a.IDFOL,
      UPPER(LTRIM(RTRIM(ISNULL(a.AUT, '')))) AS AUT,
      UPPER(LTRIM(RTRIM(ISNULL(
        CASE
          WHEN NULLIF(LTRIM(RTRIM(ISNULL(a.ORIGEN_AUT, ''))), '') IS NOT NULL THEN a.ORIGEN_AUT
          ELSE a.AUT
        END,
      '')))) AS TIPO_REF,
      UPPER(LTRIM(RTRIM(ISNULL(
        CASE
          WHEN NULLIF(LTRIM(RTRIM(ISNULL(a.OPVM, ''))), '') IS NOT NULL THEN a.OPVM
          ELSE a.OPV
        END,
      '')))) AS OPV_REF
    FROM dbo.PV_CTR_FOL_FORM f
    INNER JOIN dbo.PV_CTR_FOL_ASVR a
      ON a.IDFOL = f.IDFOL
    WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = @sucNorm
      AND f.FCN >= @dtIni
      AND f.FCN < @dtFin
  ),
  Folios AS (
    SELECT
      fb.IDFOL,
      fb.AUT,
      fb.TIPO_REF
    FROM FoliosBase fb
    WHERE fb.OPV_REF = @opvNorm
      AND fb.TIPO_REF NOT IN ('CP', 'CPF', 'VA')
      AND (
        @tipoNorm = 'GLOBAL'
        OR (@tipoNorm = 'CA' AND fb.TIPO_REF = 'CA')
        OR (@tipoNorm = 'VF' AND fb.TIPO_REF = 'VF')
      )
    GROUP BY fb.IDFOL, fb.AUT, fb.TIPO_REF
  )
  SELECT
    @trn = COUNT(1),
    @art = SUM(CASE WHEN f.TIPO_REF IN ('DF', 'CD') THEN -ABS(ISNULL(t.CTD, 0)) ELSE ISNULL(t.CTD, 0) END)
  FROM Folios f
  LEFT JOIN dbo.PV_TICKET_LOG t ON t.IDFOL = f.IDFOL;

  SELECT @difCalc = SUM(ISNULL(e.DIFD, 0))
  FROM dbo.DAT_FORM_ENTR_OPV_SVR e
  WHERE UPPER(LTRIM(RTRIM(ISNULL(e.SUC, '')))) = @sucNorm
    AND UPPER(LTRIM(RTRIM(ISNULL(e.OPV, '')))) = @opvNorm
    AND CONVERT(DATE, e.FCN) = @fcnDate;

  DECLARE @opvNombre NVARCHAR(255) = NULL;

  SELECT TOP (1)
    @opvNombre = LTRIM(RTRIM(
      ISNULL(o.NOMB, '') +
      CASE WHEN NULLIF(LTRIM(RTRIM(ISNULL(o.APELP, ''))), '') IS NULL THEN '' ELSE ' ' + LTRIM(RTRIM(ISNULL(o.APELP, ''))) END +
      CASE WHEN NULLIF(LTRIM(RTRIM(ISNULL(o.APELM, ''))), '') IS NULL THEN '' ELSE ' ' + LTRIM(RTRIM(ISNULL(o.APELM, ''))) END
    ))
  FROM dbo.PV_OPV o
  WHERE UPPER(LTRIM(RTRIM(ISNULL(o.IDOPV, '')))) = @opvNorm;

  SELECT TOP (1)
    @ide AS IDE,
    @opvNorm AS OPV,
    NULLIF(@opvNombre, '') AS OPV_NOMBRE,
    @dtIni AS FCN,
    ISNULL(fin.ART, ISNULL(@art, 0)) AS ART,
    ISNULL(fin.TRN, ISNULL(@trn, 0)) AS TRN,
    ISNULL(fin.DIF, ISNULL(@difCalc, 0)) AS DIF,
    ISNULL(NULLIF(LTRIM(RTRIM(ISNULL(fin.ESTA, ''))), ''), 'ABIERTA') AS ESTA,
    @sucNorm AS SUC,
    @tipoNorm AS TIPO_CORTE
  FROM (SELECT 1 AS X) AS base
  LEFT JOIN dbo.DAT_FORM_FIN fin
    ON fin.IDE = @ide;
END;

CREATE OR ALTER PROCEDURE dbo.sp_dev_provd_crear
  @SUC NVARCHAR(20), @ALMACEN NVARCHAR(20), @PROVD INT,
  @TIPO_DEV INT, @DOC_OC NVARCHAR(255)=NULL, @DOC_REC NVARCHAR(255)=NULL,
  @OBS NVARCHAR(1000)=NULL, @USR NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  BEGIN TRY
    BEGIN TRANSACTION;
    SET @SUC=UPPER(LTRIM(RTRIM(ISNULL(@SUC,''))));
    SET @ALMACEN=LTRIM(RTRIM(ISNULL(@ALMACEN,'002')));
    IF @SUC='' THROW 59200,'La sucursal es requerida.',1;
    IF NOT EXISTS(SELECT 1 FROM dbo.DAT_SUC WHERE UPPER(LTRIM(RTRIM(SUC)))=@SUC) THROW 59201,'La sucursal no existe.',1;
    IF NOT EXISTS(SELECT 1 FROM dbo.DAT_PROVD WHERE ID=@PROVD AND ISNULL(BLOQ,0)<>-1) THROW 59202,'El proveedor no existe o esta inactivo.',1;
    IF NOT EXISTS(SELECT 1 FROM dbo.DEV_TIPO_PROVD WHERE ID=@TIPO_DEV AND ACTIVO=1) THROW 59203,'El tipo de devolucion no es valido.',1;

    DECLARE @FOLIOS TABLE(ULTIMO BIGINT);
    MERGE dbo.DEV_FOLIO_PROVD WITH(HOLDLOCK) AS target
    USING(SELECT '__GLOBAL__' SUC) AS source ON target.SUC=source.SUC
    WHEN MATCHED THEN UPDATE SET ULTIMO=target.ULTIMO+1,FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME())
    WHEN NOT MATCHED THEN INSERT(SUC,ULTIMO) VALUES(source.SUC,1)
    OUTPUT inserted.ULTIMO INTO @FOLIOS;
    DECLARE @FOLIO BIGINT=(SELECT ULTIMO FROM @FOLIOS), @DOC NVARCHAR(40);
    SET @DOC=CONCAT('DEV-',@SUC,'-',RIGHT(CONCAT('00000000',CONVERT(VARCHAR(20),@FOLIO)),8));
    INSERT dbo.DEV_DOC_PROVD(DOC,SUC,ALMACEN,PROVD,DOC_OC,DOC_REC,TIPO_DEV,ESTATUS,OBS,USR_CREA)
    VALUES(@DOC,@SUC,@ALMACEN,@PROVD,NULLIF(LTRIM(RTRIM(@DOC_OC)),''),NULLIF(LTRIM(RTRIM(@DOC_REC)),''),@TIPO_DEV,'BORRADOR',NULLIF(LTRIM(RTRIM(@OBS)),''),@USR);
    INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
    SELECT IDUSUARIO,'CREAR','DEV_PROVD','DEV_DOC_PROVD',@DOC,@SUC,NULL,SYSUTCDATETIME() FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
    COMMIT;
    SELECT @DOC DOC;
  END TRY
  BEGIN CATCH
    IF XACT_STATE()<>0 ROLLBACK;
    THROW;
  END CATCH
END;

/*
  DEV_PROVD - Una sola evidencia por documento.
  La solicitud valida evidencia global y reserva solo los detalles activos.
*/
CREATE OR ALTER PROCEDURE dbo.sp_dev_provd_solicitar
  @DOC NVARCHAR(40), @USR NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @SUC NVARCHAR(20),@ESTATUS NVARCHAR(30),@LOCK INT,@LOCK_RESOURCE NVARCHAR(255);
    SELECT @SUC=SUC,@ESTATUS=ESTATUS FROM dbo.DEV_DOC_PROVD WITH(UPDLOCK,HOLDLOCK) WHERE DOC=@DOC;
    IF @ESTATUS IS NULL THROW 59220,'La devolucion no existe.',1;
    IF @ESTATUS='PENDIENTE' BEGIN COMMIT; SELECT @DOC DOC,'PENDIENTE' ESTATUS; RETURN; END;
    IF @ESTATUS<>'BORRADOR' THROW 59221,'Solo se puede solicitar desde BORRADOR.',1;
    SET @LOCK_RESOURCE=CONCAT('DEV_PROVD_RESERVA_',@SUC);
    EXEC @LOCK=sys.sp_getapplock @Resource=@LOCK_RESOURCE,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=15000;
    IF @LOCK<0 THROW 59222,'No fue posible bloquear el inventario para validar.',1;
    IF NOT EXISTS(SELECT 1 FROM dbo.DEV_CTRL_PROVD WHERE DOC=@DOC AND ACTIVO=1) THROW 59223,'La devolucion no tiene articulos.',1;
    IF NOT EXISTS(
      SELECT 1 FROM dbo.DEV_EVIDENCIA_PROVD e
      JOIN dbo.DEV_CTRL_PROVD d ON d.IDPD=e.IDPD
      WHERE d.DOC=@DOC AND d.ACTIVO=1
    ) THROW 59224,'La devolucion requiere una evidencia fotografica.',1;
    IF EXISTS(
      SELECT 1 FROM dbo.DEV_CTRL_PROVD d JOIN dbo.DEV_MOTIVO_PROVD m ON m.ID=d.MOV_DEV JOIN dbo.DEV_DOC_PROVD h ON h.DOC=d.DOC
      WHERE d.DOC=@DOC AND d.ACTIVO=1 AND m.REQUIERE_DOCUMENTO=1 AND NULLIF(LTRIM(RTRIM(COALESCE(h.DOC_REC,h.DOC_OC,''))),'') IS NULL
    ) THROW 59225,'El motivo requiere orden de compra o recepcion relacionada.',1;

    IF EXISTS(
      SELECT 1 FROM (SELECT ART,SUM(CTDA_DEV) CTD FROM dbo.DEV_CTRL_PROVD WHERE DOC=@DOC AND ACTIVO=1 GROUP BY ART) s
      LEFT JOIN dbo.DAT_ART a WITH(UPDLOCK,HOLDLOCK) ON a.SUC=@SUC AND a.ART=s.ART
      OUTER APPLY(SELECT SUM(x.CTDA_BLOQ) CTD FROM dbo.DEV_CTRL_PROVD x JOIN dbo.DEV_DOC_PROVD h ON h.DOC=x.DOC WHERE h.SUC=@SUC AND h.ESTATUS='PENDIENTE' AND x.ACTIVO=1 AND x.DOC<>@DOC AND x.ART=s.ART) r
      WHERE a.ART IS NULL OR ISNULL(a.STOCK,0)-ISNULL(r.CTD,0)<s.CTD
    ) THROW 59226,'Existencia disponible insuficiente para reservar.',1;

    UPDATE dbo.DEV_CTRL_PROVD SET CTDA_BLOQ=CTDA_DEV,FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE DOC=@DOC AND ACTIVO=1;
    UPDATE dbo.DEV_DOC_PROVD SET ESTATUS='PENDIENTE',USR_SOLICITA=@USR,FCN_SOLICITA=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE DOC=@DOC;
    INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
    SELECT IDUSUARIO,'SOLICITAR_RESERVAR','DEV_PROVD','DEV_DOC_PROVD',@DOC,@SUC,NULL,SYSUTCDATETIME() FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
    COMMIT;
    SELECT @DOC DOC,'PENDIENTE' ESTATUS;
  END TRY
  BEGIN CATCH
    IF XACT_STATE()<>0 ROLLBACK;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_dev_provd_autorizar
  @DOC NVARCHAR(40), @USR NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @SUC NVARCHAR(20),@ALMACEN VARCHAR(10),@ESTATUS NVARCHAR(30),@LOCK INT,@LOCK_RESOURCE NVARCHAR(255);
    SELECT @SUC=SUC,@ALMACEN=ALMACEN,@ESTATUS=ESTATUS FROM dbo.DEV_DOC_PROVD WITH(UPDLOCK,HOLDLOCK) WHERE DOC=@DOC;
    IF @ESTATUS IS NULL THROW 59230,'La devolucion no existe.',1;
    IF @ESTATUS IN ('AUTORIZADA','CONSOLIDADA','EN_TRANSITO') BEGIN COMMIT; SELECT @DOC DOC,@ESTATUS ESTATUS; RETURN; END;
    IF @ESTATUS<>'PENDIENTE' THROW 59231,'Solo se autoriza una devolucion PENDIENTE.',1;
    SET @LOCK_RESOURCE=CONCAT('DEV_PROVD_RESERVA_',@SUC);
    EXEC @LOCK=sys.sp_getapplock @Resource=@LOCK_RESOURCE,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=15000;
    IF @LOCK<0 THROW 59232,'No fue posible bloquear el inventario para autorizar.',1;
    IF NOT EXISTS(SELECT 1 FROM dbo.DAT_CMOV WHERE CMOV=102) THROW 59233,'DAT_CMOV no tiene configurado el movimiento 102.',1;
    IF EXISTS(
      SELECT 1 FROM (SELECT ART,SUM(CTDA_BLOQ) CTD FROM dbo.DEV_CTRL_PROVD WHERE DOC=@DOC AND ACTIVO=1 GROUP BY ART) q
      LEFT JOIN dbo.DAT_ART a WITH(UPDLOCK,HOLDLOCK) ON a.SUC=@SUC AND a.ART=q.ART
      WHERE a.ART IS NULL OR q.CTD<=0 OR ISNULL(a.STOCK,0)<q.CTD
    ) THROW 59234,'La existencia cambio y ya no permite autorizar la devolucion.',1;

    IF NOT EXISTS(SELECT 1 FROM dbo.DAT_CTR_DOC WITH(UPDLOCK,HOLDLOCK) WHERE DOC=@DOC)
      INSERT dbo.DAT_CTR_DOC(DOC,CLSMOV,FCND,[USER],STAT) VALUES(@DOC,'102',dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),@USR,'V');

    INSERT dbo.DAT_MB51(IDPD,[USER],CLSM,DOCP,ART,CTDA,CTOT,FCND,FCNC,TXT,ALMACEN,VTAESP,SUC)
    SELECT CONCAT('DEV-',d.DOC,'-',d.IDPD),@USR,102,d.DOC,d.ART,-ABS(CONVERT(FLOAT,d.CTDA_BLOQ)),-ABS(CONVERT(FLOAT,d.CTDA_BLOQ))*CONVERT(FLOAT,d.CTOP),dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),CONCAT('DEVOLUCION A PROVEEDOR ',d.DOC),@ALMACEN,0,@SUC
    FROM dbo.DEV_CTRL_PROVD d WHERE d.DOC=@DOC AND d.ACTIVO=1 AND d.CTDA_BLOQ>0
      AND NOT EXISTS(SELECT 1 FROM dbo.DAT_MB51 m WHERE m.IDPD=CONCAT('DEV-',d.DOC,'-',d.IDPD));

    DECLARE @SALIDA TABLE(ART NVARCHAR(20) PRIMARY KEY,CTD DECIMAL(18,4));
    INSERT @SALIDA(ART,CTD) SELECT ART,SUM(CTDA_BLOQ) FROM dbo.DEV_CTRL_PROVD WHERE DOC=@DOC AND ACTIVO=1 GROUP BY ART;
    UPDATE dbo.DEV_CTRL_PROVD SET CTDA_BLOQ=0,FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE DOC=@DOC AND ACTIVO=1;
    UPDATE a SET STOCK=ISNULL(a.STOCK,0)-q.CTD FROM dbo.DAT_ART a JOIN @SALIDA q ON q.ART=a.ART WHERE a.SUC=@SUC;
    UPDATE dbo.DEV_DOC_PROVD SET ESTATUS='AUTORIZADA',USR_AUTORIZA=@USR,FCN_AUTORIZA=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),DOC_MB51=@DOC,FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE DOC=@DOC;
    INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
    SELECT IDUSUARIO,'AUTORIZAR_CONTABILIZAR','DEV_PROVD','DEV_DOC_PROVD',@DOC,@SUC,'{"movimiento":102}',SYSUTCDATETIME() FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
    COMMIT;
    SELECT @DOC DOC,'AUTORIZADA' ESTATUS;
  END TRY
  BEGIN CATCH
    IF XACT_STATE()<>0 ROLLBACK;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_registrar_mb51
  @SUC NVARCHAR(10),
  @ART NVARCHAR(255),
  @CTDA FLOAT,
  @TXT NVARCHAR(255),
  @DOCP NVARCHAR(255),
  @USR NVARCHAR(255) = NULL,
  @CLSM NVARCHAR(50) = NULL
AS
BEGIN
  SET NOCOUNT ON;

  IF OBJECT_ID('dbo.DAT_MB51', 'U') IS NULL
    RETURN;

  DECLARE @ctop FLOAT = 0;
  IF OBJECT_ID('dbo.DAT_ART', 'U') IS NOT NULL
  BEGIN
    SELECT TOP 1
      @ctop = ISNULL(TRY_CONVERT(FLOAT, a.CTOP), 0)
    FROM dbo.DAT_ART a
    WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@SUC, ''))))
      AND UPPER(LTRIM(RTRIM(ISNULL(a.ART, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@ART, ''))))
    ORDER BY TRY_CONVERT(INT, ISNULL(a.BLOQ, 0)) ASC;
  END;

  DECLARE @cols NVARCHAR(MAX);
  DECLARE @vals NVARCHAR(MAX);
  DECLARE @sql NVARCHAR(MAX);

  ;WITH cols AS (
    SELECT
      c.name,
      c.column_id,
      CONVERT(INT, COLUMNPROPERTY(c.object_id, c.name, 'IsIdentity')) AS is_identity,
      CONVERT(INT, COLUMNPROPERTY(c.object_id, c.name, 'IsComputed')) AS is_computed
    FROM sys.columns c
    WHERE c.object_id = OBJECT_ID('dbo.DAT_MB51')
  )
  SELECT
    @cols = STRING_AGG(QUOTENAME(name), ','),
    @vals = STRING_AGG(
      CASE
        WHEN name = 'IDPD' THEN 'CONVERT(NVARCHAR(36), NEWID())'
        WHEN name = 'ART' THEN '@P_ART'
        WHEN name = 'CTDA' THEN '@P_CTDA'
        WHEN name = 'CTOT' THEN 'ROUND(ISNULL(@P_CTDA, 0) * ISNULL(@P_CTOP, 0), 2)'
        WHEN name = 'TXT' THEN 'LEFT(ISNULL(@P_TXT, ''''), 255)'
        WHEN name = 'SUC' THEN '@P_SUC'
        WHEN name = 'DOCP' THEN 'LEFT(ISNULL(@P_DOCP, ''''), 255)'
        WHEN name = 'USER' THEN 'LEFT(ISNULL(@P_USR, SYSTEM_USER), 255)'
        WHEN name = 'CLSM' THEN 'TRY_CONVERT(FLOAT, @P_CLSM)'
        WHEN name = 'FCND' THEN 'CONVERT(date, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())))'
        WHEN name = 'FCNC' THEN 'CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))'
        WHEN name = 'ALMACEN' THEN '''001'''
        ELSE 'NULL'
      END,
      ','
    )
  FROM cols
  WHERE ISNULL(is_identity, 0) = 0
    AND ISNULL(is_computed, 0) = 0;

  IF ISNULL(@cols, '') = '' OR ISNULL(@vals, '') = ''
    RETURN;

  SET @sql = N'INSERT INTO dbo.DAT_MB51 (' + @cols + N') VALUES (' + @vals + N');';

  EXEC sp_executesql
    @sql,
    N'@P_SUC NVARCHAR(10), @P_ART NVARCHAR(255), @P_CTDA FLOAT, @P_CTOP FLOAT, @P_TXT NVARCHAR(255), @P_DOCP NVARCHAR(255), @P_USR NVARCHAR(255), @P_CLSM NVARCHAR(50)',
    @P_SUC = @SUC,
    @P_ART = @ART,
    @P_CTDA = @CTDA,
    @P_CTOP = @ctop,
    @P_TXT = @TXT,
    @P_DOCP = @DOCP,
    @P_USR = @USR,
    @P_CLSM = @CLSM;

  IF OBJECT_ID('dbo.DAT_ART', 'U') IS NOT NULL
     AND COL_LENGTH('dbo.DAT_ART', 'STOCK') IS NOT NULL
  BEGIN
    ;WITH art_target AS (
      SELECT TOP 1
        a.SUC,
        a.ART,
        a.STOCK,
        a.BLOQ
      FROM dbo.DAT_ART a WITH (UPDLOCK, ROWLOCK)
      WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@SUC, ''))))
        AND UPPER(LTRIM(RTRIM(ISNULL(a.ART, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@ART, ''))))
      ORDER BY TRY_CONVERT(INT, ISNULL(a.BLOQ, 0)) ASC
    )
    UPDATE art_target
    SET STOCK = ROUND(ISNULL(TRY_CONVERT(FLOAT, STOCK), 0) + ISNULL(@CTDA, 0), 4);
  END;
END;

CREATE OR ALTER PROCEDURE dbo.sp_dev_provd_rechazar
  @DOC NVARCHAR(40), @USR NVARCHAR(100), @MOTIVO NVARCHAR(1000)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  BEGIN TRANSACTION;
  DECLARE @SUC NVARCHAR(20),@ESTATUS NVARCHAR(30);
  SELECT @SUC=SUC,@ESTATUS=ESTATUS FROM dbo.DEV_DOC_PROVD WITH(UPDLOCK,HOLDLOCK) WHERE DOC=@DOC;
  IF @ESTATUS IS NULL BEGIN ROLLBACK; THROW 59240,'La devolucion no existe.',1; END;
  IF @ESTATUS='RECHAZADA' BEGIN COMMIT; SELECT @DOC DOC,'RECHAZADA' ESTATUS; RETURN; END;
  IF @ESTATUS<>'PENDIENTE' BEGIN ROLLBACK; THROW 59241,'Solo se rechaza una devolucion PENDIENTE.',1; END;
  IF NULLIF(LTRIM(RTRIM(ISNULL(@MOTIVO,''))),'') IS NULL BEGIN ROLLBACK; THROW 59242,'El motivo de rechazo es requerido.',1; END;
  UPDATE dbo.DEV_CTRL_PROVD SET CTDA_BLOQ=0,FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE DOC=@DOC AND ACTIVO=1;
  UPDATE dbo.DEV_DOC_PROVD SET ESTATUS='RECHAZADA',USR_RECHAZA=@USR,FCN_RECHAZA=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),MOTIVO_RECHAZO=@MOTIVO,FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE DOC=@DOC;
  INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
  SELECT IDUSUARIO,'RECHAZAR_LIBERAR','DEV_PROVD','DEV_DOC_PROVD',@DOC,@SUC,CONCAT('{"motivo":"',STRING_ESCAPE(@MOTIVO,'json'),'"}'),SYSUTCDATETIME() FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
  COMMIT;
  SELECT @DOC DOC,'RECHAZADA' ESTATUS;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_registrar_ctrl_ctas_diff
  @SUC NVARCHAR(10),
  @CLIENT FLOAT,
  @IDFOL NVARCHAR(255),
  @DIFF FLOAT,
  @DOCDIF NVARCHAR(255),
  @DESC_MOV NVARCHAR(255),
  @USR NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;

  IF OBJECT_ID('dbo.DAT_CTRL_CTAS', 'U') IS NULL
    RETURN;

  IF ABS(ISNULL(@DIFF, 0)) < 0.0001
    RETURN;

  DECLARE @mov INT = CASE WHEN @DIFF > 0 THEN 802 ELSE 801 END;
  DECLARE @impt FLOAT = CASE WHEN @DIFF > 0 THEN -ABS(@DIFF) ELSE ABS(@DIFF) END;
  DECLARE @cta NVARCHAR(20) = NULL;
  DECLARE @docSeed BIGINT = 80000000;
  DECLARE @docWidth INT = 8;
  DECLARE @maxCtrl BIGINT = 0;
  DECLARE @maxDoc BIGINT = 0;
  DECLARE @nextDoc BIGINT = 0;
  DECLARE @ndoc NVARCHAR(255) = NULL;
  DECLARE @lockResult INT;
  DECLARE @classCol NVARCHAR(10) = NULL;
  DECLARE @sucNorm NVARCHAR(10) = UPPER(LTRIM(RTRIM(ISNULL(@SUC, ''))));
  DECLARE @lockResource NVARCHAR(255) = 'OT_CYM_CTRLCTA_DOC_GLOBAL';
  DECLARE @sql NVARCHAR(MAX);

  IF OBJECT_ID('dbo.DAT_CAT_CTAS', 'U') IS NOT NULL
  BEGIN
    SELECT TOP 1
      @cta = LTRIM(RTRIM(ISNULL(CTA, '')))
    FROM dbo.DAT_CAT_CTAS
    WHERE UPPER(LTRIM(RTRIM(ISNULL(RELACION, '')))) = 'AD'
    ORDER BY CASE
      WHEN UPPER(LTRIM(RTRIM(ISNULL(DCTA, '')))) = 'DIFERENCIAS EN ORD DE TRABAJO' THEN 0
      ELSE 1
    END, CTA;
  END;

  IF ISNULL(LTRIM(RTRIM(ISNULL(@cta, ''))), '') = ''
    SET @cta = '101001001';

  IF OBJECT_ID('dbo.DAT_CMOV', 'U') IS NOT NULL
  BEGIN
    SELECT TOP 1
      @docSeed = COALESCE(TRY_CONVERT(BIGINT, NDOC), @docSeed)
    FROM dbo.DAT_CMOV
    WHERE TRY_CONVERT(INT, CMOV) = @mov;
  END;

  SET @docWidth = CASE WHEN LEN(CONVERT(VARCHAR(50), ISNULL(@docSeed, 80000000))) > 8
                       THEN LEN(CONVERT(VARCHAR(50), ISNULL(@docSeed, 80000000)))
                       ELSE 8 END;

  EXEC @lockResult = sp_getapplock
    @Resource = @lockResource,
    @LockMode = 'Exclusive',
    @LockOwner = 'Transaction',
    @LockTimeout = 10000;

  IF @lockResult < 0
    THROW 58060, 'No se pudo obtener lock para generar NDOC de diferencia ORD trabajo', 1;

  SELECT @classCol = CASE
    WHEN COL_LENGTH('dbo.DAT_CTRL_CTAS', 'CMOV') IS NOT NULL THEN 'CMOV'
    WHEN COL_LENGTH('dbo.DAT_CTRL_CTAS', 'CLSD') IS NOT NULL THEN 'CLSD'
    ELSE NULL
  END;

  IF @classCol IS NOT NULL AND COL_LENGTH('dbo.DAT_CTRL_CTAS', 'NDOC') IS NOT NULL
  BEGIN
    SET @sql = N'
      SELECT @pMAX = ISNULL(MAX(
        TRY_CONVERT(BIGINT, LEFT(LTRIM(RTRIM(ISNULL(NDOC, ''''))), PATINDEX(''%[^0-9]%'', LTRIM(RTRIM(ISNULL(NDOC, ''''))) + ''X'') - 1))
      ), 0)
      FROM dbo.DAT_CTRL_CTAS WITH (UPDLOCK, HOLDLOCK)
      WHERE TRY_CONVERT(INT, ' + QUOTENAME(@classCol) + N') = @pMOV
        AND LTRIM(RTRIM(ISNULL(NDOC, ''''))) <> '''';';

    EXEC sp_executesql
      @sql,
      N'@pMOV INT, @pMAX BIGINT OUTPUT',
      @pMOV = @mov,
      @pMAX = @maxCtrl OUTPUT;
  END;

  IF OBJECT_ID('dbo.DAT_CTR_DOC', 'U') IS NOT NULL
     AND COL_LENGTH('dbo.DAT_CTR_DOC', 'DOC') IS NOT NULL
     AND COL_LENGTH('dbo.DAT_CTR_DOC', 'CLSMOV') IS NOT NULL
  BEGIN
    SELECT @maxDoc = ISNULL(MAX(
      TRY_CONVERT(BIGINT, LEFT(LTRIM(RTRIM(ISNULL(DOC, ''))), PATINDEX('%[^0-9]%', LTRIM(RTRIM(ISNULL(DOC, ''))) + 'X') - 1))
    ), 0)
    FROM dbo.DAT_CTR_DOC WITH (UPDLOCK, HOLDLOCK)
    WHERE TRY_CONVERT(INT, CLSMOV) = @mov
      AND LTRIM(RTRIM(ISNULL(DOC, ''))) <> '';
  END;

  SET @nextDoc = (SELECT MAX(V) FROM (VALUES (ISNULL(@docSeed, 80000000)), (ISNULL(@maxCtrl, 0)), (ISNULL(@maxDoc, 0))) AS T(V)) + 1;
  SET @ndoc = CONCAT(RIGHT(REPLICATE('0', @docWidth) + CONVERT(VARCHAR(50), @nextDoc), @docWidth), 'GT', ISNULL(@sucNorm, ''));

  WHILE OBJECT_ID('dbo.DAT_CTR_DOC', 'U') IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM dbo.DAT_CTR_DOC WITH (UPDLOCK, HOLDLOCK)
       WHERE LTRIM(RTRIM(ISNULL(DOC, ''))) = @ndoc
     )
  BEGIN
    SET @nextDoc += 1;
    SET @ndoc = CONCAT(RIGHT(REPLICATE('0', @docWidth) + CONVERT(VARCHAR(50), @nextDoc), @docWidth), 'GT', ISNULL(@sucNorm, ''));
  END;

  IF OBJECT_ID('dbo.DAT_CTR_DOC', 'U') IS NOT NULL
     AND COL_LENGTH('dbo.DAT_CTR_DOC', 'DOC') IS NOT NULL
     AND COL_LENGTH('dbo.DAT_CTR_DOC', 'CLSMOV') IS NOT NULL
  BEGIN
    INSERT INTO dbo.DAT_CTR_DOC (DOC, CLSMOV, FCND, [USER], STAT)
    VALUES (@ndoc, CONVERT(VARCHAR(20), @mov), CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())), LEFT(ISNULL(@USR, SYSTEM_USER), 255), 'V');
  END;

  DECLARE @cols NVARCHAR(MAX);
  DECLARE @vals NVARCHAR(MAX);

  ;WITH cols AS (
    SELECT
      c.name,
      c.column_id,
      CONVERT(INT, COLUMNPROPERTY(c.object_id, c.name, 'IsIdentity')) AS is_identity,
      CONVERT(INT, COLUMNPROPERTY(c.object_id, c.name, 'IsComputed')) AS is_computed
    FROM sys.columns c
    WHERE c.object_id = OBJECT_ID('dbo.DAT_CTRL_CTAS')
  )
  SELECT
    @cols = STRING_AGG(QUOTENAME(name), ','),
    @vals = STRING_AGG(
      CASE
        WHEN name = 'SUC' THEN '@P_SUC'
        WHEN name = 'CLIENT' THEN '@P_CLIENT'
        WHEN name = 'IDFOL' THEN '@P_IDFOL'
        WHEN name = 'CTA' THEN '@P_CTA'
        WHEN name = 'IMPT' THEN '@P_IMPT'
        WHEN name = 'FCND' THEN 'CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))'
        WHEN name = 'FCNR' THEN 'CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))'
        WHEN name = 'FCN' THEN 'CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))'
        WHEN name = 'FECHA' THEN 'CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))'
        WHEN name = 'RTXT' THEN 'LEFT(ISNULL(@P_DESC_MOV, ''''), 255)'
        WHEN name = 'NDOC' THEN 'LEFT(@P_DOC, 255)'
        WHEN name = 'CLSD' THEN '@P_MOV'
        WHEN name = 'CMOV' THEN '@P_MOV'
        ELSE 'NULL'
      END,
      ','
    )
  FROM cols
  WHERE ISNULL(is_identity, 0) = 0
    AND ISNULL(is_computed, 0) = 0;

  IF ISNULL(@cols, '') = '' OR ISNULL(@vals, '') = ''
    RETURN;

  SET @sql = N'INSERT INTO dbo.DAT_CTRL_CTAS (' + @cols + N') VALUES (' + @vals + N');';

  EXEC sp_executesql
    @sql,
    N'@P_SUC NVARCHAR(10), @P_CLIENT FLOAT, @P_IDFOL NVARCHAR(255), @P_CTA NVARCHAR(20), @P_IMPT FLOAT, @P_DESC_MOV NVARCHAR(255), @P_DOC NVARCHAR(255), @P_MOV INT',
    @P_SUC = @SUC,
    @P_CLIENT = @CLIENT,
    @P_IDFOL = @IDFOL,
    @P_CTA = @cta,
    @P_IMPT = @impt,
    @P_DESC_MOV = @DESC_MOV,
    @P_DOC = @ndoc,
    @P_MOV = @mov;
END;

CREATE OR ALTER PROCEDURE dbo.sp_dev_provd_cancelar
  @DOC NVARCHAR(40), @USR NVARCHAR(100), @MOTIVO NVARCHAR(1000)=NULL
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  BEGIN TRANSACTION;
  DECLARE @SUC NVARCHAR(20),@ESTATUS NVARCHAR(30);
  SELECT @SUC=SUC,@ESTATUS=ESTATUS FROM dbo.DEV_DOC_PROVD WITH(UPDLOCK,HOLDLOCK) WHERE DOC=@DOC;
  IF @ESTATUS IS NULL BEGIN ROLLBACK; THROW 59250,'La devolucion no existe.',1; END;
  IF @ESTATUS='CANCELADA' BEGIN COMMIT; SELECT @DOC DOC,'CANCELADA' ESTATUS; RETURN; END;
  IF @ESTATUS NOT IN('BORRADOR','PENDIENTE') BEGIN ROLLBACK; THROW 59251,'La devolucion ya no se puede cancelar.',1; END;
  UPDATE dbo.DEV_CTRL_PROVD SET CTDA_BLOQ=0,FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE DOC=@DOC AND ACTIVO=1;
  UPDATE dbo.DEV_DOC_PROVD SET ESTATUS='CANCELADA',OBS=COALESCE(NULLIF(LTRIM(RTRIM(@MOTIVO)),''),OBS),FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE DOC=@DOC;
  INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
  SELECT IDUSUARIO,'CANCELAR_LIBERAR','DEV_PROVD','DEV_DOC_PROVD',@DOC,@SUC,NULL,SYSUTCDATETIME() FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
  COMMIT;
  SELECT @DOC DOC,'CANCELADA' ESTATUS;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_clone_ord
  @IORD_ORIG NVARCHAR(255),
  @IORD_NEW NVARCHAR(255),
  @NEW_ART NVARCHAR(255) = NULL,
  @NEW_CTD FLOAT = NULL,
  @TIPOM INT = NULL,
  @MOTR INT = NULL,
  @REEORD NVARCHAR(255) = NULL,
  @DOCDIF NVARCHAR(255) = NULL,
  @ESTSEGU FLOAT = 3,
  @ESTATUS INT = 3
AS
BEGIN
  SET NOCOUNT ON;

  IF OBJECT_ID('dbo.PV_CTR_ORDS', 'U') IS NULL
    THROW 58001, 'No existe tabla PV_CTR_ORDS', 1;

  DECLARE @cols NVARCHAR(MAX);
  DECLARE @vals NVARCHAR(MAX);
  DECLARE @sql NVARCHAR(MAX);

  ;WITH cols AS (
    SELECT
      c.name,
      c.column_id,
      CONVERT(INT, COLUMNPROPERTY(c.object_id, c.name, 'IsComputed')) AS is_computed
    FROM sys.columns c
    WHERE c.object_id = OBJECT_ID('dbo.PV_CTR_ORDS')
  )
  SELECT
    @cols = STRING_AGG(QUOTENAME(name), ','),
    @vals = STRING_AGG(
      CASE
        WHEN name = 'ART' THEN 'COALESCE(NULLIF(@P_NEW_ART, ''''), o.[ART])'
        WHEN name = 'MAT' THEN 'COALESCE(NULLIF(@P_NEW_ART, ''''), o.[MAT])'
        WHEN name = 'CTD' THEN 'COALESCE(@P_NEW_CTD, TRY_CONVERT(FLOAT, o.[CTD]))'
        WHEN name = 'ESTSEGU' THEN '@P_ESTSEGU'
        WHEN name = 'ESTATUS' THEN '@P_ESTATUS'
        WHEN name = 'FCNMOD' THEN 'CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))'
        WHEN name = 'REEORD' THEN 'COALESCE(NULLIF(@P_REEORD, ''''), @P_IORD_ORIG)'
        WHEN name = 'REOORD' THEN 'COALESCE(NULLIF(@P_REEORD, ''''), @P_IORD_ORIG)'
        WHEN name = 'TIPOM' THEN 'COALESCE(@P_TIPOM, TRY_CONVERT(INT, o.[TIPOM]))'
        WHEN name = 'TPOM' THEN 'COALESCE(@P_TIPOM, TRY_CONVERT(INT, o.[TPOM]))'
        WHEN name = 'MOTR' THEN 'COALESCE(@P_MOTR, TRY_CONVERT(INT, o.[MOTR]))'
        WHEN name = 'DOCDIF' THEN 'COALESCE(NULLIF(@P_DOCDIF, ''''), o.[DOCDIF])'
        WHEN name = 'DOCIF' THEN 'COALESCE(NULLIF(@P_DOCDIF, ''''), o.[DOCIF])'
        WHEN name = 'ID_ENTREGA' THEN 'NULL'
        WHEN name = 'FIRMA_CLIENTE' THEN 'NULL'
        ELSE 'o.' + QUOTENAME(name)
      END,
      ','
    )
  FROM cols
  WHERE name <> 'IORD'
    AND ISNULL(is_computed, 0) = 0;

  IF ISNULL(@cols, '') = '' OR ISNULL(@vals, '') = ''
    THROW 58002, 'No se pudo resolver columnas para clonar ORD', 1;

  SET @sql = N'
    INSERT INTO dbo.PV_CTR_ORDS (IORD,' + @cols + N')
    SELECT @P_IORD_NEW,' + @vals + N'
    FROM dbo.PV_CTR_ORDS o
    WHERE o.IORD = @P_IORD_ORIG;

    IF @@ROWCOUNT = 0
      THROW 58003, ''No existe IORD origen para clonar'', 1;
  ';

  EXEC sp_executesql
    @sql,
    N'@P_IORD_ORIG NVARCHAR(255), @P_IORD_NEW NVARCHAR(255), @P_NEW_ART NVARCHAR(255), @P_NEW_CTD FLOAT, @P_TIPOM INT, @P_MOTR INT, @P_REEORD NVARCHAR(255), @P_DOCDIF NVARCHAR(255), @P_ESTSEGU FLOAT, @P_ESTATUS INT',
    @P_IORD_ORIG = @IORD_ORIG,
    @P_IORD_NEW = @IORD_NEW,
    @P_NEW_ART = @NEW_ART,
    @P_NEW_CTD = @NEW_CTD,
    @P_TIPOM = @TIPOM,
    @P_MOTR = @MOTR,
    @P_REEORD = @REEORD,
    @P_DOCDIF = @DOCDIF,
    @P_ESTSEGU = @ESTSEGU,
    @P_ESTATUS = @ESTATUS;
END;

CREATE OR ALTER PROCEDURE dbo.sp_dev_provd_consolidar_envio
  @DOCUMENTOS NVARCHAR(MAX), @TRANSPORTISTA NVARCHAR(120), @GUIA NVARCHAR(120),
  @CAJAS INT, @RMA NVARCHAR(120)=NULL, @OBS NVARCHAR(1000)=NULL, @USR NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  BEGIN TRY
    BEGIN TRANSACTION;
    IF ISJSON(@DOCUMENTOS)<>1 THROW 59260,'La lista de documentos no es valida.',1;
    DECLARE @DOCS TABLE(DOC NVARCHAR(40) PRIMARY KEY);
    INSERT @DOCS(DOC) SELECT DISTINCT LTRIM(RTRIM(CONVERT(NVARCHAR(40),[value]))) FROM OPENJSON(@DOCUMENTOS) WHERE NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(40),[value]))),'') IS NOT NULL;
    IF NOT EXISTS(SELECT 1 FROM @DOCS) THROW 59261,'Debe seleccionar al menos una devolucion.',1;
    IF @CAJAS<=0 THROW 59262,'El numero de cajas debe ser mayor a cero.',1;
    IF NULLIF(LTRIM(RTRIM(ISNULL(@TRANSPORTISTA,''))),'') IS NULL OR NULLIF(LTRIM(RTRIM(ISNULL(@GUIA,''))),'') IS NULL THROW 59263,'Transportista y guia son requeridos.',1;
    IF EXISTS(SELECT 1 FROM @DOCS x LEFT JOIN dbo.DEV_DOC_PROVD h WITH(UPDLOCK,HOLDLOCK) ON h.DOC=x.DOC WHERE h.DOC IS NULL OR h.ESTATUS<>'AUTORIZADA') THROW 59264,'Todas las devoluciones deben estar AUTORIZADAS.',1;
    IF (SELECT COUNT(DISTINCT h.PROVD) FROM @DOCS x JOIN dbo.DEV_DOC_PROVD h ON h.DOC=x.DOC)<>1 THROW 59265,'Solo se consolidan devoluciones del mismo proveedor.',1;
    IF EXISTS(SELECT 1 FROM @DOCS x JOIN dbo.DEV_ENVIO_DOC ed ON ed.DOC=x.DOC) THROW 59266,'Una devolucion ya pertenece a otro envio.',1;
    DECLARE @PROVD INT=(SELECT TOP(1) h.PROVD FROM @DOCS x JOIN dbo.DEV_DOC_PROVD h ON h.DOC=x.DOC);
    INSERT dbo.DEV_ENVIO_PROVD(ENVIO,PROVD,TRANSPORTISTA,GUIA,CAJAS,RMA,OBS,USR_CREA)
    VALUES(NULL,@PROVD,@TRANSPORTISTA,@GUIA,@CAJAS,NULLIF(LTRIM(RTRIM(@RMA)),''),NULLIF(LTRIM(RTRIM(@OBS)),''),@USR);
    DECLARE @ID BIGINT=SCOPE_IDENTITY(),@ENVIO NVARCHAR(40);
    SET @ENVIO=CONCAT('ENV-DEV-',RIGHT(CONCAT('00000000',CONVERT(VARCHAR(20),@ID)),8));
    UPDATE dbo.DEV_ENVIO_PROVD SET ENVIO=@ENVIO WHERE ID=@ID;
    INSERT dbo.DEV_ENVIO_DOC(IDENVIO,DOC) SELECT @ID,DOC FROM @DOCS;
    UPDATE h SET ESTATUS='CONSOLIDADA',FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) FROM dbo.DEV_DOC_PROVD h JOIN @DOCS x ON x.DOC=h.DOC;
    INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
    SELECT u.IDUSUARIO,'CONSOLIDAR_ENVIO','DEV_PROVD','DEV_ENVIO_PROVD',@ENVIO,NULL,CONCAT('{"documentos":',@DOCUMENTOS,'}'),SYSUTCDATETIME() FROM dbo.USUARIO u WHERE UPPER(u.USERNAME)=UPPER(@USR);
    COMMIT;
    SELECT @ENVIO ENVIO;
  END TRY
  BEGIN CATCH
    IF XACT_STATE()<>0 ROLLBACK;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_dev_provd_salida_fisica
  @ENVIO NVARCHAR(40), @USR NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  BEGIN TRANSACTION;
  DECLARE @ID BIGINT,@ESTATUS NVARCHAR(30);
  SELECT @ID=ID,@ESTATUS=ESTATUS FROM dbo.DEV_ENVIO_PROVD WITH(UPDLOCK,HOLDLOCK) WHERE ENVIO=@ENVIO;
  IF @ID IS NULL BEGIN ROLLBACK; THROW 59270,'El envio no existe.',1; END;
  IF @ESTATUS='EN_TRANSITO' BEGIN COMMIT; SELECT @ENVIO ENVIO,'EN_TRANSITO' ESTATUS; RETURN; END;
  IF @ESTATUS<>'CONSOLIDADO' BEGIN ROLLBACK; THROW 59271,'El envio no se puede registrar como salida.',1; END;
  UPDATE dbo.DEV_ENVIO_PROVD SET ESTATUS='EN_TRANSITO',USR_SALIDA=@USR,FCN_SALIDA=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE ID=@ID;
  UPDATE h SET ESTATUS='EN_TRANSITO',FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) FROM dbo.DEV_DOC_PROVD h JOIN dbo.DEV_ENVIO_DOC ed ON ed.DOC=h.DOC WHERE ed.IDENVIO=@ID;
  INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
  SELECT IDUSUARIO,'SALIDA_FISICA','DEV_PROVD','DEV_ENVIO_PROVD',@ENVIO,NULL,NULL,SYSUTCDATETIME() FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
  COMMIT;
  SELECT @ENVIO ENVIO,'EN_TRANSITO' ESTATUS;
END;

CREATE OR ALTER PROCEDURE dbo.sp_cg_reporte_entrega_opv
  @SUC VARCHAR(25),
  @FCN DATE,
  @OPV NVARCHAR(255),
  @TIPO_CORTE VARCHAR(10) = 'GLOBAL'
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @header TABLE (
    IDE NVARCHAR(255),
    OPV NVARCHAR(255),
    OPV_NOMBRE NVARCHAR(255),
    FCN DATETIME,
    ART FLOAT,
    TRN FLOAT,
    DIF MONEY,
    ESTA NVARCHAR(255),
    SUC VARCHAR(25),
    TIPO_CORTE VARCHAR(10)
  );

  DECLARE @formas TABLE (
    FORM NVARCHAR(255),
    NOM NVARCHAR(255),
    IMPT MONEY,
    IMPR MONEY,
    IMPE MONEY,
    DIFD MONEY,
    TRECIBIDO MONEY,
    TIPO_CORTE VARCHAR(10)
  );

  DECLARE @transacciones TABLE (
    AUT NVARCHAR(255),
    [DESC] NVARCHAR(255),
    CTA FLOAT,
    TOTAL MONEY,
    TIPO_CORTE VARCHAR(10)
  );

  DECLARE @ventas TABLE (
    DDEPA NVARCHAR(255),
    DSUBD NVARCHAR(255),
    VTAPZS FLOAT,
    VTAPSOS MONEY,
    TIPO_CORTE VARCHAR(10)
  );

  DECLARE @efectivo TABLE (
    DENO MONEY,
    CTDA FLOAT,
    EFECTIVO MONEY,
    TOTAL MONEY
  );

  INSERT INTO @header
  EXEC dbo.sp_cg_resumen_opv
    @SUC = @SUC,
    @FCN = @FCN,
    @OPV = @OPV,
    @TIPO_CORTE = @TIPO_CORTE;

  INSERT INTO @formas
  EXEC dbo.sp_cg_resumen_formas_pago_opv
    @SUC = @SUC,
    @FCN = @FCN,
    @OPV = @OPV,
    @TIPO_CORTE = @TIPO_CORTE;

  INSERT INTO @transacciones
  EXEC dbo.sp_cg_resumen_transacciones_opv
    @SUC = @SUC,
    @FCN = @FCN,
    @OPV = @OPV,
    @TIPO_CORTE = @TIPO_CORTE;

  INSERT INTO @ventas
  EXEC dbo.sp_cg_resumen_ventas_departamento_opv
    @SUC = @SUC,
    @FCN = @FCN,
    @OPV = @OPV,
    @TIPO_CORTE = @TIPO_CORTE;

  INSERT INTO @efectivo
  EXEC dbo.sp_cg_resumen_efectivo_opv
    @SUC = @SUC,
    @FCN = @FCN,
    @OPV = @OPV;

  SELECT
    ISNULL((SELECT TOP 1 * FROM @header FOR JSON PATH, WITHOUT_ARRAY_WRAPPER), '{}') AS HEADER_JSON,
    ISNULL((SELECT * FROM @formas ORDER BY FORM FOR JSON PATH), '[]') AS FORMAS_JSON,
    ISNULL((SELECT * FROM @transacciones ORDER BY AUT FOR JSON PATH), '[]') AS TRANSACCIONES_JSON,
    ISNULL((SELECT * FROM @ventas ORDER BY DDEPA, DSUBD FOR JSON PATH), '[]') AS VENTAS_JSON,
    ISNULL((SELECT * FROM @efectivo ORDER BY DENO DESC FOR JSON PATH), '[]') AS EFECTIVO_JSON,
    @SUC AS SUC,
    @FCN AS FCN,
    @OPV AS OPV,
    UPPER(LTRIM(RTRIM(ISNULL(@TIPO_CORTE, 'GLOBAL')))) AS TIPO_CORTE,
    GETUTCDATE() AS GENERATED_AT;
END;

CREATE OR ALTER PROCEDURE dbo.sp_rec_recepcion_fisica
  @NPED nvarchar(510),
  @USR nvarchar(100),
  @TIPO_RECEPCION nvarchar(20),
  @TIPO_DOC nvarchar(20)=NULL,
  @FOLIO_DOC nvarchar(100)=NULL,
  @ALMACEN varchar(10)='002',
  @OBSERVACIONES nvarchar(1000)=NULL,
  @ITEMS_JSON nvarchar(max),
  @GUIAS_JSON nvarchar(max)=N'[]',
  @INCIDENCIAS_JSON nvarchar(max)=N'[]'
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;
  SET @TIPO_RECEPCION=UPPER(LTRIM(RTRIM(@TIPO_RECEPCION)));
  SET @TIPO_DOC=NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@TIPO_DOC,'')))),'');
  SET @ALMACEN=COALESCE(NULLIF(LTRIM(RTRIM(@ALMACEN)),''),'002');
  IF @TIPO_RECEPCION NOT IN ('TOTAL','PARCIAL','DIFERENCIAS','RECHAZO') THROW 51000,'Tipo de recepcion invalido.',1;
  IF @TIPO_DOC IS NOT NULL AND @TIPO_DOC NOT IN ('FACTURA','NOTA','PENDIENTE','CONSIGNACION') THROW 51000,'Tipo documental invalido.',1;
  IF @TIPO_DOC IN ('FACTURA','NOTA') AND NULLIF(LTRIM(RTRIM(ISNULL(@FOLIO_DOC,''))),'') IS NULL THROW 51000,'El folio es obligatorio para factura o nota.',1;
  IF ISJSON(@ITEMS_JSON)<>1 THROW 51000,'El detalle de recepcion no es JSON valido.',1;

  DECLARE @items table(
    RN int IDENTITY(1,1),IDPED nvarchar(510),ART nvarchar(510),CTD_REC float,CTD_ACEP float,
    CALIDAD_ESTATUS nvarchar(20),CADUCIDAD date,OBSERVACIONES nvarchar(1000),CALIDAD_JSON nvarchar(max),
    POS int,CTD_SOL float,CTO money,PENDIENTE float
  );
  INSERT @items(IDPED,ART,CTD_REC,CTD_ACEP,CALIDAD_ESTATUS,CADUCIDAD,OBSERVACIONES,CALIDAD_JSON)
  SELECT NULLIF(LTRIM(RTRIM(IDPED)),''),LTRIM(RTRIM(ART)),CTD_REC,COALESCE(CTD_ACEP,CTD_REC),
         UPPER(NULLIF(LTRIM(RTRIM(CALIDAD_ESTATUS)),'')),CADUCIDAD,OBSERVACIONES,CALIDAD_JSON
  FROM OPENJSON(@ITEMS_JSON) WITH(
    IDPED nvarchar(510) '$.idped',ART nvarchar(510) '$.art',CTD_REC float '$.cantidadRecibida',
    CTD_ACEP float '$.cantidadAceptada',CALIDAD_ESTATUS nvarchar(20) '$.calidadEstado',
    CADUCIDAD date '$.caducidad',OBSERVACIONES nvarchar(1000) '$.observaciones',
    CALIDAD_JSON nvarchar(max) '$.calidad' AS JSON
  );
  IF NOT EXISTS(SELECT 1 FROM @items) THROW 51000,'Capture al menos un articulo.',1;
  IF EXISTS(SELECT 1 FROM @items WHERE ART='' OR CTD_REC<=0 OR CTD_ACEP<0 OR CTD_ACEP>CTD_REC) THROW 51000,'Cantidades o articulos invalidos en la recepcion.',1;
  IF EXISTS(SELECT IDPED FROM @items WHERE IDPED IS NOT NULL GROUP BY IDPED HAVING COUNT(*)>1) THROW 51000,'La recepcion contiene posiciones duplicadas.',1;

  BEGIN TRANSACTION;
  DECLARE @lock int,@lock_resource nvarchar(255)=CONCAT('DAT_REC_NPED_',@NPED);
  EXEC @lock=sys.sp_getapplock @Resource=@lock_resource,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=15000;
  IF @lock<0 THROW 51000,'No fue posible bloquear la orden para recepcion.',1;
  DECLARE @SUC nvarchar(510),@ESTATUS nvarchar(510);
  SELECT @SUC=SUC,@ESTATUS=UPPER(LTRIM(RTRIM(ISNULL(ESTATUS,'')))) FROM dbo.REC_CAB_PED WITH(UPDLOCK,HOLDLOCK) WHERE NPED=@NPED;
  IF @SUC IS NULL THROW 51000,'La orden de compra no existe.',1;
  IF @ESTATUS NOT IN ('PROCESADO','PARCIAL') THROW 51000,'La orden no esta disponible para recepcion.',1;
  IF EXISTS(SELECT 1 FROM dbo.REC_CTRL_DOC_REC WITH(UPDLOCK,HOLDLOCK) WHERE NPED=@NPED AND ESTATUS_REC IN ('RECEPCION_FISICA','PENDIENTE_AUTORIZACION'))
    THROW 51000,'La orden ya tiene una recepcion activa.',1;

  UPDATE i SET POS=d.POS,CTD_SOL=d.CTDPED,CTO=d.CTO,PENDIENTE=CASE WHEN ISNULL(d.CTDPED,0)>ISNULL(d.CTDREC,0) THEN d.CTDPED-ISNULL(d.CTDREC,0) ELSE 0 END
  FROM @items i JOIN dbo.REC_DET_PED d ON d.NPED=@NPED AND d.IDPED=i.IDPED AND ISNULL(d.BLOQ,0)<>-1;
  IF EXISTS(SELECT 1 FROM @items WHERE IDPED IS NOT NULL AND POS IS NULL) THROW 51000,'Una posicion no pertenece a la orden.',1;
  IF EXISTS(SELECT 1 FROM @items WHERE IDPED IS NOT NULL AND PENDIENTE<=0) THROW 51000,'Una posicion ya no tiene cantidad pendiente.',1;
  IF EXISTS(SELECT 1 FROM @items i WHERE i.IDPED IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.REC_DET_PED d WHERE d.IDPED=i.IDPED AND d.ART=i.ART)) THROW 51000,'Articulo y posicion no coinciden.',1;
  IF EXISTS(SELECT 1 FROM @items i WHERE i.IDPED IS NULL AND NOT EXISTS(SELECT 1 FROM dbo.DAT_ART a WHERE a.SUC=@SUC AND a.ART=i.ART)) THROW 51000,'Un articulo no solicitado no existe en la sucursal.',1;
  IF @TIPO_RECEPCION='RECHAZO' AND EXISTS(SELECT 1 FROM @items WHERE CTD_ACEP<>0) THROW 51000,'Una recepcion rechazada no puede aceptar cantidades.',1;
  IF @TIPO_RECEPCION='TOTAL' AND EXISTS(
    SELECT 1 FROM dbo.REC_DET_PED d WHERE d.NPED=@NPED AND ISNULL(d.BLOQ,0)<>-1 AND ISNULL(d.CTDREC,0)<ISNULL(d.CTDPED,0)
      AND ISNULL((SELECT SUM(i.CTD_ACEP) FROM @items i WHERE i.IDPED=d.IDPED),0)<>(ISNULL(d.CTDPED,0)-ISNULL(d.CTDREC,0))
  ) THROW 51000,'Recepcion total requiere cubrir exactamente todo lo pendiente.',1;

  UPDATE i SET CALIDAD_ESTATUS=COALESCE(i.CALIDAD_ESTATUS,CASE WHEN EXISTS(
    SELECT 1 FROM dbo.DAT_ART a JOIN dbo.REC_CALIDAD_CRITERIO c ON c.ACTIVO=1
      AND (c.TIPO IS NULL OR c.TIPO=a.TIPO) AND (c.DEPA IS NULL OR c.DEPA=a.DEPA) AND (c.SUBD IS NULL OR c.SUBD=a.SUBD)
      AND (c.CLAS IS NULL OR c.CLAS=a.CLAS) AND (c.SCLA IS NULL OR c.SCLA=a.SCLA) AND (c.SCLA2 IS NULL OR c.SCLA2=a.SCLA2)
    WHERE a.SUC=@SUC AND a.ART=i.ART) THEN 'PENDIENTE' ELSE 'NO_APLICA' END)
  FROM @items i;
  UPDATE i SET CTO=COALESCE(i.CTO,a.CTOP,0)
  FROM @items i LEFT JOIN dbo.DAT_ART a ON a.SUC=@SUC AND a.ART=i.ART;

  EXEC @lock=sys.sp_getapplock @Resource='REC_CTRL_DOC_REC_DOCREC',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=15000;
  IF @lock<0 THROW 51000,'No fue posible generar el documento de recepcion.',1;
  DECLARE @DOCREC nvarchar(510),@NEXT bigint;
  SELECT @NEXT=ISNULL(MAX(NUMERO),71000000)+1
  FROM (
    SELECT TRY_CONVERT(bigint,DOCREC) NUMERO FROM dbo.REC_CTRL_DOC_REC WITH(UPDLOCK,HOLDLOCK)
    UNION ALL SELECT TRY_CONVERT(bigint,DOC) FROM dbo.DAT_CTR_DOC WITH(UPDLOCK,HOLDLOCK)
    UNION ALL SELECT TRY_CONVERT(bigint,DOCP) FROM dbo.DAT_MB51 WITH(UPDLOCK,HOLDLOCK)
  ) documentos
  WHERE NUMERO IS NOT NULL;
  WHILE EXISTS(SELECT 1 FROM dbo.REC_CTRL_DOC_REC WHERE DOCREC=CONVERT(nvarchar(510),@NEXT))
     OR EXISTS(SELECT 1 FROM dbo.DAT_CTR_DOC WHERE DOC=CONVERT(nvarchar(510),@NEXT))
     OR EXISTS(SELECT 1 FROM dbo.DAT_MB51 WHERE DOCP=CONVERT(nvarchar(510),@NEXT))
    SET @NEXT+=1;
  SET @DOCREC=CONVERT(nvarchar(510),@NEXT);
  DECLARE @MAXPOS int=(SELECT ISNULL(MAX(POS),0) FROM dbo.REC_DET_PED WHERE NPED=@NPED);
  DECLARE @NART int=(SELECT COUNT(*) FROM @items);
  DECLARE @IMPT money=(SELECT SUM(ISNULL(CTO,0)*CTD_ACEP) FROM @items);
  INSERT dbo.REC_CTRL_DOC_REC(DOCREC,NPED,FCNC,NART,IMPT,ESTATUS_REC,TIPO_RECEPCION,FCN_FISICA,USR_RECEPCION,TIPO_DOC,FOLIO_DOC,OBSERVACIONES,ALMACEN)
  VALUES(@DOCREC,@NPED,dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),@NART,@IMPT,'RECEPCION_FISICA',@TIPO_RECEPCION,dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),@USR,@TIPO_DOC,NULLIF(LTRIM(RTRIM(ISNULL(@FOLIO_DOC,''))),''),@OBSERVACIONES,@ALMACEN);

  INSERT dbo.REC_CTO_HIST(IDREC,POS,ART,FCN,CTD,CTDVTA,DOCREC,IDPED,CTD_SOL,CTD_ACEP,CALIDAD_ESTATUS,CALIDAD_JSON,CADUCIDAD,OBSERVACIONES)
  SELECT CONCAT('REC-',@DOCREC,'-',CONVERT(varchar(12),RN)),COALESCE(POS,@MAXPOS+RN),ART,dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),CTD_REC,
         ISNULL(CTO,0)*CTD_ACEP,
         @DOCREC,IDPED,COALESCE(CTD_SOL,0),CTD_ACEP,CALIDAD_ESTATUS,CALIDAD_JSON,CADUCIDAD,OBSERVACIONES
  FROM @items i;

  IF ISJSON(@GUIAS_JSON)=1
    INSERT dbo.REC_GUIA_PED(DOCREC,GUIA,PAQUETERIA,NPAQ,OBSERVACIONES,USR)
    SELECT @DOCREC,LTRIM(RTRIM(GUIA)),NULLIF(LTRIM(RTRIM(PAQUETERIA)),''),NPAQ,OBSERVACIONES,@USR
    FROM OPENJSON(@GUIAS_JSON) WITH(GUIA nvarchar(100) '$.guia',PAQUETERIA nvarchar(120) '$.paqueteria',NPAQ int '$.cantidadPaquetes',OBSERVACIONES nvarchar(500) '$.observaciones')
    WHERE NULLIF(LTRIM(RTRIM(GUIA)),'') IS NOT NULL;

  INSERT dbo.REC_INCI_PED(DOCREC,IDREC,TIPO,ART,CTD_ESPERADA,CTD_RECIBIDA,DIFERENCIA,MOTIVO,USR)
  SELECT @DOCREC,h.IDREC,
         CASE WHEN i.IDPED IS NULL THEN 'NO_SOLICITADO' WHEN i.CTD_ACEP>i.PENDIENTE THEN 'SOBRANTE' WHEN i.CTD_ACEP<i.PENDIENTE THEN 'FALTANTE' ELSE 'CALIDAD' END,
         i.ART,COALESCE(i.PENDIENTE,0),i.CTD_REC,i.CTD_ACEP-COALESCE(i.PENDIENTE,0),i.OBSERVACIONES,@USR
  FROM @items i JOIN dbo.REC_CTO_HIST h ON h.DOCREC=@DOCREC AND h.ART=i.ART
    AND (h.IDPED=i.IDPED OR (h.IDPED IS NULL AND i.IDPED IS NULL))
  WHERE i.IDPED IS NULL OR i.CTD_ACEP<>i.PENDIENTE OR i.CTD_ACEP<i.CTD_REC OR i.CALIDAD_ESTATUS='RECHAZADO';

  IF ISJSON(@INCIDENCIAS_JSON)=1
    INSERT dbo.REC_INCI_PED(DOCREC,TIPO,ART,CTD_ESPERADA,CTD_RECIBIDA,DIFERENCIA,MOTIVO,USR)
    SELECT @DOCREC,UPPER(TIPO),NULLIF(LTRIM(RTRIM(ART)),''),CTD_ESPERADA,CTD_RECIBIDA,COALESCE(CTD_RECIBIDA,0)-COALESCE(CTD_ESPERADA,0),MOTIVO,@USR
    FROM OPENJSON(@INCIDENCIAS_JSON) WITH(TIPO nvarchar(30) '$.tipo',ART nvarchar(510) '$.art',CTD_ESPERADA float '$.cantidadEsperada',CTD_RECIBIDA float '$.cantidadRecibida',MOTIVO nvarchar(1000) '$.motivo')
    WHERE UPPER(TIPO) IN ('FALTANTE','SOBRANTE','NO_SOLICITADO','COSTO','DANO','CALIDAD','OTRO');

  INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
  SELECT u.IDUSUARIO,'RECEPCION_FISICA','DAT_REC','REC_CTRL_DOC_REC',@DOCREC,@SUC,
         CONCAT('{"nped":"',STRING_ESCAPE(@NPED,'json'),'","tipo":"',@TIPO_RECEPCION,'"}'),SYSUTCDATETIME()
  FROM dbo.USUARIO u WHERE UPPER(u.USERNAME)=UPPER(@USR);
  COMMIT;
  SELECT @DOCREC DOCREC,@NPED NPED,'RECEPCION_FISICA' ESTATUS_REC;
END;

CREATE OR ALTER PROCEDURE dbo.sp_rec_recepcion_solicitar
  @DOCREC nvarchar(510),
  @USR nvarchar(100),
  @MOTIVO nvarchar(1000) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;
  BEGIN TRANSACTION;

  DECLARE @lock int;
  DECLARE @lock_resource nvarchar(255) = CONCAT('DAT_REC_DOC_', @DOCREC);
  EXEC @lock = sys.sp_getapplock
    @Resource = @lock_resource,
    @LockMode = 'Exclusive',
    @LockOwner = 'Transaction',
    @LockTimeout = 15000;
  IF @lock < 0 THROW 51000, 'No fue posible bloquear la recepcion.', 1;

  DECLARE
    @ESTATUS nvarchar(30),
    @NPED nvarchar(510),
    @SUC nvarchar(510),
    @TIPO nvarchar(20);

  SELECT
    @ESTATUS = r.ESTATUS_REC,
    @NPED = r.NPED,
    @TIPO = r.TIPO_RECEPCION,
    @SUC = h.SUC
  FROM dbo.REC_CTRL_DOC_REC r WITH (UPDLOCK, HOLDLOCK)
  JOIN dbo.REC_CAB_PED h WITH (UPDLOCK, HOLDLOCK) ON h.NPED = r.NPED
  WHERE r.DOCREC = @DOCREC;

  IF @ESTATUS IS NULL THROW 51000, 'La recepcion no existe.', 1;

  IF @ESTATUS = 'VALIDADO'
  BEGIN
    UPDATE dbo.REC_CAB_PED
    SET ESTATUS = 'VALIDADO'
    WHERE NPED = @NPED
      AND UPPER(LTRIM(RTRIM(ISNULL(ESTATUS, '')))) NOT IN ('CANCELADA', 'ANULADO');
    COMMIT;
    SELECT @DOCREC DOCREC, @ESTATUS ESTATUS_REC;
    RETURN;
  END;

  IF @ESTATUS <> 'RECEPCION_FISICA'
    THROW 51000, 'La recepcion no se puede validar en su estado actual.', 1;
  IF @TIPO <> 'RECHAZO' AND NOT EXISTS (
    SELECT 1
    FROM dbo.REC_CTO_HIST
    WHERE DOCREC = @DOCREC AND ISNULL(CTD_ACEP, CTD) > 0
  )
    THROW 51000, 'No hay cantidades aceptadas.', 1;
  IF EXISTS (
    SELECT 1
    FROM dbo.REC_CTO_HIST
    WHERE DOCREC = @DOCREC AND CALIDAD_ESTATUS = 'PENDIENTE'
  )
    THROW 51000, 'Existen validaciones de calidad pendientes.', 1;

  UPDATE dbo.REC_CTRL_DOC_REC
  SET ESTATUS_REC = 'VALIDADO'
  WHERE DOCREC = @DOCREC;

  UPDATE dbo.REC_CAB_PED
  SET ESTATUS = 'VALIDADO'
  WHERE NPED = @NPED;

  INSERT dbo.AUDIT_LOG (
    IDUSUARIO, ACTION, MODULO, ENTIDAD, ENTIDAD_ID, SUC, METADATA_JSON, FCNR
  )
  SELECT
    IDUSUARIO,
    'VALIDAR_RECEPCION',
    'DAT_REC',
    'REC_CTRL_DOC_REC',
    @DOCREC,
    @SUC,
    NULL,
    SYSUTCDATETIME()
  FROM dbo.USUARIO
  WHERE UPPER(USERNAME) = UPPER(@USR);

  COMMIT;
  SELECT @DOCREC DOCREC, 'VALIDADO' ESTATUS_REC;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_enviar
  @IORD NVARCHAR(255),
  @ASIGN NVARCHAR(255) = NULL,
  @LABOR INT = NULL,
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE
    @estadoActual FLOAT = NULL,
    @laborActual INT = NULL,
    @laborFinal INT = NULL,
    @labSuc NVARCHAR(10) = '',
    @labTipo NVARCHAR(100) = '',
    @labUbicacion NVARCHAR(100) = '',
    @labDesc NVARCHAR(255) = '',
    @estadoDestino FLOAT = NULL;

  SELECT TOP 1
    @estadoActual = TRY_CONVERT(FLOAT, o.ESTSEGU),
    @laborActual = TRY_CONVERT(INT, o.LABOR)
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  WHERE UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@IORD, ''))))
    AND (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF @estadoActual IS NULL
    THROW 58110, 'No existe la ORD o no estÃ¡ autorizada para la sucursal', 1;

  IF ABS(@estadoActual - 3) > 0.0001
    THROW 58111, 'La ORD debe estar en estatus 3 (NUEVA AUTORIZADA) para poder enviarse', 1;

  SET @laborFinal = COALESCE(TRY_CONVERT(INT, @LABOR), @laborActual);
  IF ISNULL(@laborFinal, 0) <= 0
    THROW 58112, 'La ORD debe tener laboratorio asignado para enviar a taller', 1;

  SELECT TOP 1
    @labSuc = UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))),
    @labTipo = UPPER(LTRIM(RTRIM(ISNULL(lab.TIPOLAB, '')))),
    @labUbicacion = UPPER(LTRIM(RTRIM(ISNULL(lab.UBILAB, '')))),
    @labDesc = UPPER(LTRIM(RTRIM(ISNULL(lab.LAB, ''))))
  FROM dbo.DAT_LAB lab
  WHERE TRY_CONVERT(INT, lab.ID) = @laborFinal;

  SET @estadoDestino = CASE
    WHEN ISNULL(@labUbicacion, '') LIKE '%EXTER%'
      OR (
        ISNULL(@labUbicacion, '') = ''
        AND (
          ISNULL(@labSuc, '') = ''
          OR ISNULL(@labTipo, '') LIKE '%EXTER%'
          OR ISNULL(@labDesc, '') LIKE '%EXTER%'
        )
      )
    THEN 9
    ELSE 5
  END;

  BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE o
    SET
      o.ESTSEGU = @estadoDestino,
      o.ESTATUS = 2,
      o.LABOR = @laborFinal,
      o.ASIGN = COALESCE(@ASIGN, o.ASIGN),
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    WHERE UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@IORD, ''))));

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    o.IORD,
    o.IDFOL,
    o.SUC,
    o.ESTATUS,
    o.ESTSEGU,
    o.ASIGN,
    o.LABOR,
    o.FCNMOD,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR
  FROM dbo.PV_CTR_ORDS o
  WHERE UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@IORD, ''))));
END;

CREATE OR ALTER PROCEDURE dbo.sp_rec_recepcion_autorizar
  @DOCREC nvarchar(510),@USR nvarchar(100),@MOTIVO nvarchar(1000)=NULL
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;
  DECLARE @lock int,@lock_resource nvarchar(255)=CONCAT('DAT_REC_DOC_',@DOCREC);
  EXEC @lock=sys.sp_getapplock @Resource=@lock_resource,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=15000;
  IF @lock<0 THROW 51000,'No fue posible bloquear la recepcion.',1;
  DECLARE @ESTATUS nvarchar(30),@NPED nvarchar(510),@SUC nvarchar(510),@ALMACEN varchar(10),@TIPO nvarchar(20);
  SELECT @ESTATUS=r.ESTATUS_REC,@NPED=r.NPED,@ALMACEN=COALESCE(NULLIF(r.ALMACEN,''),'002'),@TIPO=r.TIPO_RECEPCION,@SUC=h.SUC
  FROM dbo.REC_CTRL_DOC_REC r WITH(UPDLOCK,HOLDLOCK)
  JOIN dbo.REC_CAB_PED h WITH(UPDLOCK,HOLDLOCK) ON h.NPED=r.NPED WHERE r.DOCREC=@DOCREC;
  IF @ESTATUS IS NULL THROW 51000,'La recepcion no existe.',1;
  IF @ESTATUS='CONTABILIZADO' BEGIN COMMIT; SELECT @DOCREC DOCREC,@ESTATUS ESTATUS_REC; RETURN; END;
  IF @ESTATUS NOT IN ('VALIDADO','PENDIENTE_AUTORIZACION') THROW 51000,'La recepcion no esta validada para autorizacion.',1;
  IF @TIPO='RECHAZO' THROW 51000,'Una recepcion rechazada no puede contabilizarse.',1;
  IF EXISTS(
    SELECT 1 FROM dbo.REC_CTO_HIST
    WHERE DOCREC=@DOCREC AND CALIDAD_ESTATUS IN ('PENDIENTE','RECHAZADO') AND ISNULL(CTD_ACEP,CTD)>0
  ) THROW 51000,'La calidad no permite contabilizar la recepcion.',1;

  IF NOT EXISTS(SELECT 1 FROM dbo.DAT_CTR_DOC WITH(UPDLOCK,HOLDLOCK) WHERE DOC=@DOCREC)
    INSERT dbo.DAT_CTR_DOC(DOC,CLSMOV,FCND,[USER],STAT) VALUES(@DOCREC,'101',dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),@USR,'V');

  INSERT dbo.DAT_MB51(IDPD,[USER],CLSM,DOCP,ART,CTDA,CTOT,FCND,FCNC,TXT,ALMACEN,VTAESP,SUC)
  SELECT x.IDREC,@USR,101,@DOCREC,x.ART,ISNULL(x.CTD_ACEP,x.CTD),
         ISNULL(x.CTD_ACEP,x.CTD)*COALESCE(d.CTO,a.CTOP,0),dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),@NPED,@ALMACEN,0,@SUC
  FROM dbo.REC_CTO_HIST x
  LEFT JOIN dbo.REC_DET_PED d ON d.IDPED=x.IDPED
  LEFT JOIN dbo.DAT_ART a ON a.SUC=@SUC AND a.ART=x.ART
  WHERE x.DOCREC=@DOCREC AND ISNULL(x.CTD_ACEP,x.CTD)>0
    AND NOT EXISTS(SELECT 1 FROM dbo.DAT_MB51 m WHERE m.IDPD=x.IDREC);

  ;WITH qty AS(
    SELECT ART,SUM(ISNULL(CTD_ACEP,CTD)) CTD FROM dbo.REC_CTO_HIST
    WHERE DOCREC=@DOCREC AND ISNULL(CTD_ACEP,CTD)>0 GROUP BY ART
  )
  UPDATE a SET STOCK=ISNULL(a.STOCK,0)+q.CTD
  FROM dbo.DAT_ART a JOIN qty q ON q.ART=a.ART WHERE a.SUC=@SUC;

  ;WITH qty AS(
    SELECT IDPED,SUM(ISNULL(CTD_ACEP,CTD)) CTD FROM dbo.REC_CTO_HIST
    WHERE DOCREC=@DOCREC AND IDPED IS NOT NULL GROUP BY IDPED
  )
  UPDATE d SET CTDREC=ISNULL(d.CTDREC,0)+q.CTD,
    RECI=CASE WHEN ISNULL(d.CTDREC,0)+q.CTD>=ISNULL(d.CTDPED,0) THEN -1 ELSE 0 END,DREC=@DOCREC
  FROM dbo.REC_DET_PED d JOIN qty q ON q.IDPED=d.IDPED;

  UPDATE dbo.REC_INCI_PED SET ESTATUS='AUTORIZADA',USR_AUTORIZA=@USR,FCN_AUTORIZA=dbo.fn_ioe_business_datetime(SYSUTCDATETIME())
  WHERE DOCREC=@DOCREC AND ESTATUS='ABIERTA';
  UPDATE dbo.REC_CTRL_DOC_REC
  SET ESTATUS_REC='CONTABILIZADO',USR_AUTORIZA=@USR,FCN_AUTORIZA=dbo.fn_ioe_business_datetime(SYSUTCDATETIME()) WHERE DOCREC=@DOCREC;
  UPDATE dbo.REC_CAB_PED
  SET ESTATUS='CONTABILIZADO',FCNR=COALESCE(FCNR,dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
  WHERE NPED=@NPED;
  INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
  SELECT IDUSUARIO,'AUTORIZAR_CONTABILIZAR','DAT_REC','REC_CTRL_DOC_REC',@DOCREC,@SUC,
    CONCAT('{"movimiento":101,"almacen":"',STRING_ESCAPE(@ALMACEN,'json'),'"}'),SYSUTCDATETIME()
  FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
  COMMIT; SELECT @DOCREC DOCREC,'CONTABILIZADO' ESTATUS_REC;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_recibir
  @IORD NVARCHAR(255),
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @estadoActual FLOAT = NULL;
  DECLARE @labSuc NVARCHAR(10) = '';
  DECLARE @labTipo NVARCHAR(100) = '';
  DECLARE @labUbicacion NVARCHAR(100) = '';
  DECLARE @labDesc NVARCHAR(255) = '';

  SELECT TOP 1
    @estadoActual = TRY_CONVERT(FLOAT, o.ESTSEGU),
    @labSuc = UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))),
    @labTipo = UPPER(LTRIM(RTRIM(ISNULL(lab.TIPOLAB, '')))),
    @labUbicacion = UPPER(LTRIM(RTRIM(ISNULL(lab.UBILAB, '')))),
    @labDesc = UPPER(LTRIM(RTRIM(ISNULL(lab.LAB, ''))))
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  WHERE UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@IORD, ''))))
    AND (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF @estadoActual IS NULL
    THROW 58230, 'No existe la ORD o no estÃ¡ autorizada para la sucursal', 1;

  DECLARE @isLabExterno BIT = CASE
    WHEN ISNULL(@labUbicacion, '') LIKE '%EXTER%'
      OR (
        ISNULL(@labUbicacion, '') = ''
        AND (
          ISNULL(@labSuc, '') = ''
          OR ISNULL(@labTipo, '') LIKE '%EXTER%'
          OR ISNULL(@labDesc, '') LIKE '%EXTER%'
        )
      )
    THEN 1
    ELSE 0
  END;

  IF @isLabExterno = 1
  BEGIN
    IF ABS(@estadoActual - 5) > 0.0001 AND ABS(@estadoActual - 9) > 0.0001
      THROW 58231, 'La ORD externa debe estar en estatus 5 o 9 para poder recibirse', 1;
  END
  ELSE IF ABS(@estadoActual - 5) > 0.0001
    THROW 58231, 'La ORD debe estar en estatus 5 (ENTREGADA A MAQ O BISEL) para poder recibirse', 1;

  DECLARE @estadoDestino FLOAT = CASE WHEN @isLabExterno = 1 THEN 10 ELSE 7 END;

  EXEC dbo.sp_ordenes_trabajo_set_estado
    @IORD = @IORD,
    @ESTSEGU = @estadoDestino,
    @ESTATUS = 2,
    @USER = @USER,
    @IP = @IP,
    @IS_ADMIN = @IS_ADMIN,
    @ALLOWED_SUCS = @ALLOWED_SUCS,
    @SUC = @SUC;

  IF @isLabExterno = 1 AND COL_LENGTH('dbo.PV_CTR_ORDS', 'FCNRT') IS NOT NULL
  BEGIN
    UPDATE o
    SET
      o.FCNRT = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    WHERE UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@IORD, ''))));
  END;
END;

CREATE OR ALTER PROCEDURE dbo.sp_rec_recepcion_rechazar
  @DOCREC nvarchar(510),
  @USR nvarchar(100),
  @MOTIVO nvarchar(1000) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;
  BEGIN TRANSACTION;

  DECLARE @lock int;
  DECLARE @lock_resource nvarchar(255) = CONCAT('DAT_REC_DOC_', @DOCREC);
  EXEC @lock = sys.sp_getapplock
    @Resource = @lock_resource,
    @LockMode = 'Exclusive',
    @LockOwner = 'Transaction',
    @LockTimeout = 15000;
  IF @lock < 0 THROW 51000, 'No fue posible bloquear la recepcion.', 1;

  DECLARE @ESTATUS nvarchar(30), @NPED nvarchar(510), @SUC nvarchar(510);
  SELECT @ESTATUS = r.ESTATUS_REC, @NPED = r.NPED, @SUC = h.SUC
  FROM dbo.REC_CTRL_DOC_REC r WITH (UPDLOCK, HOLDLOCK)
  JOIN dbo.REC_CAB_PED h WITH (UPDLOCK, HOLDLOCK) ON h.NPED = r.NPED
  WHERE r.DOCREC = @DOCREC;

  IF @ESTATUS IS NULL THROW 51000, 'La recepcion no existe.', 1;

  IF @ESTATUS = 'RECHAZADO'
  BEGIN
    UPDATE dbo.REC_CAB_PED
    SET ESTATUS = 'RECHAZADO'
    WHERE NPED = @NPED
      AND UPPER(LTRIM(RTRIM(ISNULL(ESTATUS, '')))) NOT IN ('CANCELADA', 'ANULADO');
    COMMIT;
    SELECT @DOCREC DOCREC, @ESTATUS ESTATUS_REC;
    RETURN;
  END;

  IF @ESTATUS NOT IN ('RECEPCION_FISICA', 'VALIDADO', 'PENDIENTE_AUTORIZACION')
    THROW 51000, 'La recepcion no se puede rechazar en su estado actual.', 1;

  UPDATE dbo.REC_CTRL_DOC_REC
  SET ESTATUS_REC = 'RECHAZADO',
      USR_AUTORIZA = @USR,
      FCN_AUTORIZA = dbo.fn_ioe_business_datetime(SYSUTCDATETIME()),
      OBSERVACIONES = COALESCE(NULLIF(@MOTIVO, ''), OBSERVACIONES)
  WHERE DOCREC = @DOCREC;

  UPDATE dbo.REC_CAB_PED
  SET ESTATUS = 'RECHAZADO'
  WHERE NPED = @NPED;

  UPDATE dbo.REC_INCI_PED
  SET ESTATUS = 'RECHAZADA', USR_AUTORIZA = @USR, FCN_AUTORIZA = dbo.fn_ioe_business_datetime(SYSUTCDATETIME())
  WHERE DOCREC = @DOCREC AND ESTATUS = 'ABIERTA';

  INSERT dbo.AUDIT_LOG (
    IDUSUARIO, ACTION, MODULO, ENTIDAD, ENTIDAD_ID, SUC, METADATA_JSON, FCNR
  )
  SELECT
    IDUSUARIO,
    'RECHAZAR',
    'DAT_REC',
    'REC_CTRL_DOC_REC',
    @DOCREC,
    @SUC,
    CASE WHEN @MOTIVO IS NULL THEN NULL
      ELSE CONCAT('{"motivo":"', STRING_ESCAPE(@MOTIVO, 'json'), '"}') END,
    SYSUTCDATETIME()
  FROM dbo.USUARIO
  WHERE UPPER(USERNAME) = UPPER(@USR);

  COMMIT;
  SELECT @DOCREC DOCREC, 'RECHAZADO' ESTATUS_REC;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_cambio_material
  @IORD NVARCHAR(255),
  @ART_NUEVO NVARCHAR(255),
  @MOTIVO NVARCHAR(255),
  @LABOR INT = NULL,
  @DOCDIF NVARCHAR(255) = NULL,
  @MOTR INT = NULL,
  @CTD_C_M FLOAT = 1,
  @PVTA_NUEVO FLOAT = NULL,
  @IORD_NUEVA NVARCHAR(255) = NULL,
  @DIFERENCIA_SELLADA FLOAT = NULL,
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @idfol NVARCHAR(255);
  DECLARE @sucOrd NVARCHAR(10);
  DECLARE @artOrig NVARCHAR(255);
  DECLARE @ctdOrig FLOAT;
  DECLARE @clien FLOAT;
  DECLARE @newIord NVARCHAR(255);
  DECLARE @tipom INT = 1;
  DECLARE @tipomOrd INT = 0;
  DECLARE @estseguOrd FLOAT = 0;
  DECLARE @selCtrlOrd INT = 0;
  DECLARE @motrInt INT = ISNULL(@MOTR, TRY_CONVERT(INT, @MOTIVO));
  DECLARE @motivoLabel NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@MOTIVO, '')));
  DECLARE @doc NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@DOCDIF, '')));
  DECLARE @ctdAfectada FLOAT;
  DECLARE @remanente FLOAT = 0;
  DECLARE @ctdAbs FLOAT = 0;
  DECLARE @ctdSalida FLOAT = 0;
  DECLARE @docpOrig NVARCHAR(255);
  DECLARE @docpNew NVARCHAR(255);
  DECLARE @txtReingreso NVARCHAR(255);
  DECLARE @txtSalida NVARCHAR(255);
  DECLARE @txtDiff NVARCHAR(255);
  DECLARE @precioOrig FLOAT = 0;
  DECLARE @precioNuevo FLOAT = 0;
  DECLARE @importeOrig FLOAT = 0;
  DECLARE @importeNuevo FLOAT = 0;
  DECLARE @diffVenta FLOAT = 0;

  IF LTRIM(RTRIM(ISNULL(@ART_NUEVO, ''))) = ''
    THROW 58020, 'artNuevo es requerido para cambio de material', 1;

  IF @doc = ''
    SET @doc = CONCAT(
      'ODIF-',
      FORMAT(CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())), 'yyyyMMddHHmmss'),
      '-',
      RIGHT(CONVERT(VARCHAR(36), NEWID()), 4)
    );

  IF ABS(ISNULL(@CTD_C_M, 0) - 1) > 0.0001
     AND ABS(ISNULL(@CTD_C_M, 0) - 0.5) > 0.0001
    THROW 58025, 'CTD_C_M solo permite valores 1 o 0.5', 1;

  IF OBJECT_ID('dbo.DAT_ORD_MOTM', 'U') IS NOT NULL
  BEGIN
    IF @motrInt IS NULL OR @motrInt <= 0
    BEGIN
      SELECT TOP 1 @motrInt = TRY_CONVERT(INT, IDM)
      FROM dbo.DAT_ORD_MOTM
      WHERE TRY_CONVERT(INT, TIPO) = 1
        AND UPPER(LTRIM(RTRIM(ISNULL(MOTM, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@motivoLabel, ''))));
    END;

    SELECT TOP 1 @motivoLabel = LTRIM(RTRIM(ISNULL(MOTM, '')))
    FROM dbo.DAT_ORD_MOTM
    WHERE TRY_CONVERT(INT, IDM) = @motrInt
      AND TRY_CONVERT(INT, TIPO) = 1;

    IF @motrInt IS NULL OR @motrInt <= 0 OR LTRIM(RTRIM(ISNULL(@motivoLabel, ''))) = ''
      THROW 58021, 'Debe seleccionar un motivo valido de DAT_ORD_MOTM para cambio de material', 1;
  END;

  IF LTRIM(RTRIM(ISNULL(@motivoLabel, ''))) = ''
    THROW 58021, 'motivo es requerido para cambio de material', 1;

  SELECT TOP 1
    @idfol = o.IDFOL,
    @sucOrd = o.SUC,
    @artOrig = o.ART,
    @ctdOrig = TRY_CONVERT(FLOAT, o.CTD),
    @clien = TRY_CONVERT(FLOAT, o.CLIEN),
    @tipomOrd = TRY_CONVERT(INT, o.TIPOM),
    @estseguOrd = TRY_CONVERT(FLOAT, o.ESTSEGU),
    @selCtrlOrd = TRY_CONVERT(INT, o.selCtrlOrd)
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  WHERE o.IORD = @IORD
    AND (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF @idfol IS NULL
    THROW 58022, 'No existe la ORD origen o no tiene acceso por sucursal', 1;

  IF NOT (
    (@estseguOrd IS NOT NULL AND ABS(@estseguOrd - 9.1) <= 0.0001)
    OR (@estseguOrd IS NULL AND ISNULL(@selCtrlOrd, 0) = 14)
  )
    THROW 58023, 'La ORD debe estar en flujo 9.1 o SIN FLUJO con selCtrlOrd=14 para autorizar cambio material', 1;

  IF ISNULL(@tipomOrd, 0) <> 1
    THROW 58024, 'La ORD debe tener TIPOM=1 para aplicar cambio material', 1;

  IF ISNULL(@ctdOrig, 0) <= 0
    THROW 58026, 'La ORD no tiene cantidad valida para cambio de material', 1;

  IF ABS(ISNULL(@ctdOrig, 0) - 1) > 0.0001
     AND ABS(ISNULL(@ctdOrig, 0) - 0.5) > 0.0001
    THROW 58029, 'La ORD origen debe haber sido creada con cantidad 1 o 0.5 para cambio de material', 1;

  -- Cambio material: la cantidad nueva puede superar la cantidad de la ORD origen.

  SET @ctdAfectada = @CTD_C_M;
  SET @remanente = CASE WHEN @ctdOrig > @ctdAfectada THEN @ctdOrig - @ctdAfectada ELSE 0 END;
  SET @newIord = NULLIF(LTRIM(RTRIM(ISNULL(@IORD_NUEVA, ''))), '');

  IF @newIord IS NULL
  BEGIN
    DECLARE @fcnGenCM DATETIME = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()));
    EXEC dbo.sp_pv_ctr_ords_generate_iord
      @SUC = @sucOrd,
      @FCN = @fcnGenCM,
      @IORD_OUT = @newIord OUTPUT;
  END;

  IF @newIord IS NULL OR LTRIM(RTRIM(@newIord)) = ''
    THROW 58028, 'No se pudo generar la nueva IORD para cambio material', 1;

  SET @ctdAbs = ABS(@ctdAfectada);
  SET @ctdSalida = -ABS(@ctdAfectada);
  SET @docpOrig = ISNULL(@idfol, @IORD);
  SET @docpNew = @docpOrig;
  SET @txtReingreso = CONCAT('Cambio - Reintegracion stock ORD', @IORD);
  SET @txtSalida = CONCAT('Cambio - Descuento stock ORD', @newIord);
  SET @txtDiff = CONCAT('Diferencia cambio material ORD ', @IORD, ' -> ', @newIord);

  BEGIN TRY
    BEGIN TRANSACTION;

    EXEC dbo.sp_ordenes_trabajo_clone_ord
      @IORD_ORIG = @IORD,
      @IORD_NEW = @newIord,
      @NEW_ART = @ART_NUEVO,
      @NEW_CTD = @ctdAfectada,
      @TIPOM = 0,
      @MOTR = NULL,
      @REEORD = @IORD,
      @DOCDIF = @doc,
      @ESTSEGU = 3,
      @ESTATUS = 2;

    IF OBJECT_ID('dbo.PV_CTR_ORDS_DET', 'U') IS NOT NULL
    BEGIN
      INSERT INTO dbo.PV_CTR_ORDS_DET (IORDP, IORD, ART, JOB, ESF, CIL, EJE)
      SELECT
        CONCAT(
          ROW_NUMBER() OVER (
            ORDER BY
              CASE UPPER(LTRIM(RTRIM(ISNULL(d.JOB, ''))))
                WHEN 'OD' THEN 1
                WHEN 'OI' THEN 2
                WHEN 'ADD' THEN 3
                ELSE 99
              END,
              UPPER(LTRIM(RTRIM(ISNULL(d.IORDP, ''))))
          ),
          @newIord
        ),
        @newIord,
        COALESCE(NULLIF(@ART_NUEVO, ''), d.ART),
        d.JOB,
        d.ESF,
        d.CIL,
        d.EJE
      FROM dbo.PV_CTR_ORDS_DET d
      WHERE d.IORD = @IORD;
    END;

    UPDATE dbo.PV_CTR_ORDS
    SET
      CTD = CASE WHEN @remanente > 0.0001 THEN @remanente ELSE @ctdOrig END,
      CTD_C_M = CASE WHEN @remanente > 0.0001 THEN NULL ELSE @ctdAfectada END,
      MOTR = CASE WHEN @remanente > 0.0001 THEN NULL ELSE MOTR END,
      TIPOM = CASE WHEN @remanente > 0.0001 THEN 0 ELSE TIPOM END,
      REEORD = CASE WHEN @remanente > 0.0001 THEN NULL ELSE @newIord END,
      selCtrlOrd = NULL,
      ESTSEGU = CASE WHEN @remanente > 0.0001 THEN 3 ELSE 4 END,
      ESTATUS = 2,
      FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
      COMAD = LEFT(
        CONCAT(
          ISNULL(CAST(COMAD AS NVARCHAR(MAX)), ''),
          CASE
            WHEN LTRIM(RTRIM(ISNULL(CAST(COMAD AS NVARCHAR(MAX)), ''))) = ''
              THEN ''
            ELSE ' | '
          END,
          'CAMBIO MATERIAL: ',
          @motivoLabel
        ),
        2000
      )
    WHERE IORD = @IORD;

    UPDATE dbo.PV_CTR_ORDS
    SET
      ASIGN = NULL,
      CTD_C_M = @ctdAfectada,
      MOTR = NULL,
      TIPOM = 0,
      DESCART = COALESCE(
        (
          SELECT TOP 1 LTRIM(RTRIM(ISNULL(a.DES, '')))
          FROM dbo.DAT_ART a
          WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@sucOrd, ''))))
            AND UPPER(LTRIM(RTRIM(ISNULL(a.ART, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@ART_NUEVO, ''))))
          ORDER BY TRY_CONVERT(INT, ISNULL(a.BLOQ, 0)) ASC
        ),
        DESCART
      ),
      selCtrlOrd = NULL,
      FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    WHERE IORD = @newIord;

    EXEC dbo.sp_ordenes_trabajo_registrar_mb51
      @SUC = @sucOrd,
      @ART = @artOrig,
      @CTDA = @ctdAbs,
      @TXT = @txtReingreso,
      @DOCP = @docpOrig,
      @USR = @USER,
      @CLSM = '204';

    EXEC dbo.sp_ordenes_trabajo_registrar_mb51
      @SUC = @sucOrd,
      @ART = @ART_NUEVO,
      @CTDA = @ctdSalida,
      @TXT = @txtSalida,
      @DOCP = @docpNew,
      @USR = @USER,
      @CLSM = '205';

    IF OBJECT_ID('dbo.PV_TICKET_LOG', 'U') IS NOT NULL
    BEGIN
      SELECT TOP 1
        @precioOrig = COALESCE(
          TRY_CONVERT(FLOAT, t.PVTAT),
          0
        )
      FROM dbo.PV_TICKET_LOG t
      WHERE (
          UPPER(LTRIM(RTRIM(ISNULL(t.ORD, '')))) = UPPER(@IORD)
          OR (
            UPPER(LTRIM(RTRIM(ISNULL(t.IDFOL, '')))) = UPPER(@idfol)
            AND UPPER(LTRIM(RTRIM(ISNULL(t.ART, '')))) = UPPER(@artOrig)
          )
        )
      ORDER BY
        CASE
          WHEN UPPER(LTRIM(RTRIM(ISNULL(t.ORD, '')))) = UPPER(@IORD) THEN 0
          ELSE 1
        END,
        CASE
          WHEN UPPER(LTRIM(RTRIM(ISNULL(t.ART, '')))) = UPPER(@artOrig) THEN 0
          ELSE 1
        END,
        ISNULL(t.updated_at, CONVERT(DATETIME, '19000101', 112)) DESC,
        LTRIM(RTRIM(ISNULL(t.ID, ''))) DESC;
    END;

    IF OBJECT_ID('dbo.DAT_ART', 'U') IS NOT NULL
    BEGIN
      SELECT TOP 1
        @precioNuevo = TRY_CONVERT(FLOAT, a.PVTA)
      FROM dbo.DAT_ART a
      WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@sucOrd, ''))))
        AND UPPER(LTRIM(RTRIM(ISNULL(a.ART, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@ART_NUEVO, ''))))
      ORDER BY TRY_CONVERT(INT, ISNULL(a.BLOQ, 0)) ASC;
    END;

    IF ISNULL(@precioOrig, 0) = 0 AND OBJECT_ID('dbo.DAT_ART', 'U') IS NOT NULL
    BEGIN
      SELECT TOP 1
        @precioOrig = TRY_CONVERT(FLOAT, a.PVTA)
      FROM dbo.DAT_ART a
      WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@sucOrd, ''))))
        AND UPPER(LTRIM(RTRIM(ISNULL(a.ART, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@artOrig, ''))))
      ORDER BY TRY_CONVERT(INT, ISNULL(a.BLOQ, 0)) ASC;
    END;
    SET @precioNuevo = COALESCE(@PVTA_NUEVO, @precioNuevo, @precioOrig, 0);
    SET @importeOrig = ROUND(
      ISNULL(@precioOrig, 0) * (ISNULL(@ctdAfectada, 0) / NULLIF(@ctdOrig, 0)),
      2
    );
    SET @importeNuevo = ROUND(ISNULL(@precioNuevo, 0) * @ctdAfectada, 2);

    DECLARE @ivaIntegrado INT = 0;
    DECLARE @rqfacFolio INT = 0;
    DECLARE @tipoTran NVARCHAR(2) = 'VF';
    DECLARE @totalOrig FLOAT = 0;
    DECLARE @totalNuevo FLOAT = 0;

    SELECT TOP 1
      @ivaIntegrado = ISNULL(TRY_CONVERT(INT, s.IVA_INTEGRADO), 0)
    FROM dbo.DAT_SUC s
    WHERE UPPER(LTRIM(RTRIM(ISNULL(s.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@sucOrd, ''))));

    SELECT TOP 1
      @rqfacFolio = ISNULL(TRY_CONVERT(INT, f.REQF), 0),
      @tipoTran = CASE
        WHEN UPPER(LTRIM(RTRIM(ISNULL(f.ORIGEN_AUT, '')))) IN ('CA', 'VF') THEN UPPER(LTRIM(RTRIM(ISNULL(f.ORIGEN_AUT, ''))))
        WHEN UPPER(LTRIM(RTRIM(ISNULL(f.AUT, '')))) IN ('DCA', 'CA', 'DC', 'DG', 'CP', 'PS') THEN 'CA'
        WHEN UPPER(LTRIM(RTRIM(ISNULL(f.AUT, '')))) IN ('DVF', 'VF') THEN 'VF'
        ELSE 'VF'
      END
    FROM dbo.PV_CTR_FOL_ASVR f
    WHERE UPPER(LTRIM(RTRIM(ISNULL(f.IDFOL, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@idfol, ''))))
    ORDER BY ISNULL(f.FCNM, f.FCN) DESC;

    IF @tipoTran = 'CA'
    BEGIN
      SET @totalOrig = ROUND(@importeOrig, 2);
      SET @totalNuevo = ROUND(@importeNuevo, 2);
    END
    ELSE IF @ivaIntegrado = -1
    BEGIN
      SET @totalOrig = ROUND(@importeOrig, 2);
      SET @totalNuevo = ROUND(@importeNuevo, 2);
    END
    ELSE IF @rqfacFolio = 1
    BEGIN
      SET @totalOrig = ROUND(@importeOrig * 1.16, 2);
      SET @totalNuevo = ROUND(@importeNuevo * 1.16, 2);
    END
    ELSE
    BEGIN
      SET @totalOrig = ROUND(@importeOrig, 2);
      SET @totalNuevo = ROUND(@importeNuevo, 2);
    END;

    SET @diffVenta = COALESCE(@DIFERENCIA_SELLADA, ROUND(@totalNuevo - @totalOrig, 2));

    EXEC dbo.sp_ordenes_trabajo_registrar_ctrl_ctas_diff
      @SUC = @sucOrd,
      @CLIENT = @clien,
      @IDFOL = @idfol,
      @DIFF = @diffVenta,
      @DOCDIF = @doc,
      @DESC_MOV = @txtDiff,
      @USR = @USER;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    @IORD AS IORD_ORIG,
    @newIord AS IORD_NUEVA,
    @idfol AS IDFOL,
    @doc AS DOCDIF,
    @motrInt AS MOTR,
    @motivoLabel AS MOTIVO,
    @ctdAfectada AS CTD_C_M,
    @ctdOrig AS CTD_ORIGINAL,
    @remanente AS CTD_REMANENTE,
    @diffVenta AS DIFERENCIA_ECONOMICA,
    CASE WHEN ABS(ISNULL(@diffVenta, 0)) >= 0.009 THEN 1 ELSE 0 END AS AFECTACION_CONTABLE,
    @sucOrd AS SUC,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_merma
  @IORD NVARCHAR(255),
  @CANTIDAD_MERMA FLOAT,
  @MOTIVO NVARCHAR(255),
  @CREAR_NUEVA_ORD BIT = 1,
  @MOTR INT = NULL,
  @ART_NUEVO NVARCHAR(255) = NULL,
  @CTD_C_M FLOAT = NULL,
  @PVTA_NUEVO FLOAT = NULL,
  @IORD_NUEVA NVARCHAR(255) = NULL,
  @DIFERENCIA_SELLADA FLOAT = NULL,
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @idfol NVARCHAR(255);
  DECLARE @sucOrd NVARCHAR(10);
  DECLARE @artOrig NVARCHAR(255);
  DECLARE @artSalida NVARCHAR(255);
  DECLARE @ctdOrig FLOAT;
  DECLARE @clien FLOAT;
  DECLARE @remanente FLOAT;
  DECLARE @newIord NVARCHAR(255) = NULL;
  DECLARE @tipom INT = 2;
  DECLARE @tipomOrd INT = 0;
  DECLARE @estseguOrd FLOAT = 0;
  DECLARE @motrInt INT = ISNULL(@MOTR, TRY_CONVERT(INT, @MOTIVO));
  DECLARE @motivoLabel NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@MOTIVO, '')));
  DECLARE @ctdAfectada FLOAT = ISNULL(@CTD_C_M, @CANTIDAD_MERMA);
  DECLARE @ctdMermaAbs FLOAT = 0;
  DECLARE @ctdMermaSalida FLOAT = 0;
  DECLARE @docpMerma NVARCHAR(255);
  DECLARE @docpMermaSalida NVARCHAR(255);
  DECLARE @txtMermaReingreso NVARCHAR(255);
  DECLARE @txtMermaCargo NVARCHAR(255);
  DECLARE @txtMermaSalida NVARCHAR(255);
  DECLARE @doc NVARCHAR(255);
  DECLARE @txtDiff NVARCHAR(255);
  DECLARE @precioOrig FLOAT = 0;
  DECLARE @precioNuevo FLOAT = 0;
  DECLARE @importeOrig FLOAT = 0;
  DECLARE @importeNuevo FLOAT = 0;
  DECLARE @diffVenta FLOAT = 0;

  IF ABS(ISNULL(@ctdAfectada, 0) - 1) > 0.0001
     AND ABS(ISNULL(@ctdAfectada, 0) - 0.5) > 0.0001
    THROW 58037, 'CTD_C_M solo permite valores 1 o 0.5', 1;

  IF ISNULL(@ctdAfectada, 0) <= 0
    THROW 58030, 'cantidadMerma debe ser mayor a cero', 1;

  IF OBJECT_ID('dbo.DAT_ORD_MOTM', 'U') IS NOT NULL
  BEGIN
    IF @motrInt IS NULL OR @motrInt <= 0
    BEGIN
      SELECT TOP 1 @motrInt = TRY_CONVERT(INT, IDM)
      FROM dbo.DAT_ORD_MOTM
      WHERE TRY_CONVERT(INT, TIPO) = 2
        AND UPPER(LTRIM(RTRIM(ISNULL(MOTM, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@motivoLabel, ''))));
    END;

    SELECT TOP 1 @motivoLabel = LTRIM(RTRIM(ISNULL(MOTM, '')))
    FROM dbo.DAT_ORD_MOTM
    WHERE TRY_CONVERT(INT, IDM) = @motrInt
      AND TRY_CONVERT(INT, TIPO) = 2;

    IF @motrInt IS NULL OR @motrInt <= 0 OR LTRIM(RTRIM(ISNULL(@motivoLabel, ''))) = ''
      THROW 58031, 'Debe seleccionar un motivo valido de DAT_ORD_MOTM para merma', 1;
  END;

  IF LTRIM(RTRIM(ISNULL(@motivoLabel, ''))) = ''
    THROW 58031, 'motivo es requerido para merma', 1;

  SELECT TOP 1
    @idfol = o.IDFOL,
    @sucOrd = o.SUC,
    @artOrig = o.ART,
    @ctdOrig = TRY_CONVERT(FLOAT, o.CTD),
    @clien = TRY_CONVERT(FLOAT, o.CLIEN),
    @tipomOrd = TRY_CONVERT(INT, o.TIPOM),
    @estseguOrd = TRY_CONVERT(FLOAT, o.ESTSEGU)
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  WHERE o.IORD = @IORD
    AND (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF @idfol IS NULL
    THROW 58032, 'No existe la ORD origen o no tiene acceso por sucursal', 1;

  IF @estseguOrd IS NULL OR ABS(@estseguOrd - 9.2) > 0.0001
    THROW 58035, 'La ORD debe estar en flujo 9.2 para aplicar merma', 1;

  IF ISNULL(@tipomOrd, 0) <> 2
    THROW 58036, 'La ORD debe tener TIPOM=2 para aplicar merma', 1;

  IF ISNULL(@ctdOrig, 0) <= 0
    THROW 58033, 'La ORD no tiene cantidad valida para procesar merma', 1;

  IF ABS(ISNULL(@ctdOrig, 0) - 1) > 0.0001
     AND ABS(ISNULL(@ctdOrig, 0) - 0.5) > 0.0001
    THROW 58038, 'La ORD origen debe haber sido creada con cantidad 1 o 0.5 para merma', 1;

  IF @ctdAfectada - @ctdOrig > 0.0001
    THROW 58034, 'cantidadMerma no puede ser mayor a la cantidad original', 1;

  SET @CANTIDAD_MERMA = @ctdAfectada;
  SET @remanente = @ctdOrig - @ctdAfectada;
  SET @artSalida = COALESCE(NULLIF(LTRIM(RTRIM(ISNULL(@ART_NUEVO, ''))), ''), @artOrig);
  SET @doc = CONCAT(
    'ODIF-',
    FORMAT(CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())), 'yyyyMMddHHmmss'),
    '-',
    RIGHT(CONVERT(VARCHAR(36), NEWID()), 4)
  );
  SET @txtDiff = CONCAT('Diferencia merma ORD ', @IORD);

  IF @CREAR_NUEVA_ORD = 1
  BEGIN
    SET @newIord = NULLIF(LTRIM(RTRIM(ISNULL(@IORD_NUEVA, ''))), '');

    IF @newIord IS NULL
    BEGIN
      DECLARE @fcnGenMerma DATETIME = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()));
      EXEC dbo.sp_pv_ctr_ords_generate_iord
        @SUC = @sucOrd,
        @FCN = @fcnGenMerma,
        @IORD_OUT = @newIord OUTPUT;
    END;

    IF @newIord IS NULL OR LTRIM(RTRIM(@newIord)) = ''
      THROW 58038, 'No se pudo generar la nueva IORD para merma', 1;
  END;

  SET @ctdMermaAbs = ABS(@ctdAfectada);
  SET @ctdMermaSalida = -ABS(@ctdAfectada);
  SET @docpMerma = ISNULL(@idfol, @IORD);
  SET @docpMermaSalida = @docpMerma;
  SET @txtMermaReingreso = CONCAT('Merma - Reintegracion stock ORD', @IORD);
  SET @txtMermaCargo = CONCAT('Merma por uso ', @motrInt, ', ORD: ', @IORD);
  SET @txtMermaSalida = CONCAT('Merma - Descuento stock ORD', ISNULL(@newIord, @IORD));

  BEGIN TRY
    BEGIN TRANSACTION;

    IF @CREAR_NUEVA_ORD = 1
    BEGIN
      EXEC dbo.sp_ordenes_trabajo_clone_ord
        @IORD_ORIG = @IORD,
        @IORD_NEW = @newIord,
        @NEW_ART = @artSalida,
        @NEW_CTD = @ctdAfectada,
        @TIPOM = 0,
        @MOTR = NULL,
        @REEORD = @IORD,
        @DOCDIF = @doc,
        @ESTSEGU = 3,
        @ESTATUS = 2;

      IF OBJECT_ID('dbo.PV_CTR_ORDS_DET', 'U') IS NOT NULL
      BEGIN
        INSERT INTO dbo.PV_CTR_ORDS_DET (IORDP, IORD, ART, JOB, ESF, CIL, EJE)
        SELECT
          CONCAT(
            ROW_NUMBER() OVER (
              ORDER BY
                CASE UPPER(LTRIM(RTRIM(ISNULL(d.JOB, ''))))
                  WHEN 'OD' THEN 1
                  WHEN 'OI' THEN 2
                  WHEN 'ADD' THEN 3
                  ELSE 99
                END,
                UPPER(LTRIM(RTRIM(ISNULL(d.IORDP, ''))))
            ),
            @newIord
          ),
          @newIord,
          COALESCE(NULLIF(@artSalida, ''), d.ART),
          d.JOB,
          d.ESF,
          d.CIL,
          d.EJE
        FROM dbo.PV_CTR_ORDS_DET d
        WHERE d.IORD = @IORD;
      END;
    END;

    UPDATE dbo.PV_CTR_ORDS
    SET
      CTD = @ctdOrig,
      CTD_C_M = @ctdAfectada,
      REEORD = @newIord,
      selCtrlOrd = NULL,
      ESTSEGU = 4,
      ESTATUS = 2,
      FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
      COMAD = LEFT(
        CONCAT(
          ISNULL(CAST(COMAD AS NVARCHAR(MAX)), ''),
          CASE
            WHEN LTRIM(RTRIM(ISNULL(CAST(COMAD AS NVARCHAR(MAX)), ''))) = ''
              THEN ''
            ELSE ' | '
          END,
          'MERMA: ',
          @motivoLabel
        ),
        2000
      )
    WHERE IORD = @IORD;

    IF @CREAR_NUEVA_ORD = 1
    BEGIN
      UPDATE dbo.PV_CTR_ORDS
      SET
        ASIGN = NULL,
        CTD_C_M = @ctdAfectada,
        MOTR = NULL,
        TIPOM = 0,
        DESCART = COALESCE(
          (
            SELECT TOP 1 LTRIM(RTRIM(ISNULL(a.DES, '')))
            FROM dbo.DAT_ART a
            WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@sucOrd, ''))))
              AND UPPER(LTRIM(RTRIM(ISNULL(a.ART, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@artSalida, ''))))
            ORDER BY TRY_CONVERT(INT, ISNULL(a.BLOQ, 0)) ASC
          ),
          DESCART
        ),
        selCtrlOrd = NULL,
        FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
      WHERE IORD = @newIord;
    END;

    EXEC dbo.sp_ordenes_trabajo_registrar_mb51
      @SUC = @sucOrd,
      @ART = @artOrig,
      @CTDA = @ctdMermaAbs,
      @TXT = @txtMermaReingreso,
      @DOCP = @docpMerma,
      @USR = @USER,
      @CLSM = '456';

    EXEC dbo.sp_ordenes_trabajo_registrar_mb51
      @SUC = @sucOrd,
      @ART = @artOrig,
      @CTDA = @ctdMermaSalida,
      @TXT = @txtMermaCargo,
      @DOCP = @docpMerma,
      @USR = @USER,
      @CLSM = '455';

    EXEC dbo.sp_ordenes_trabajo_registrar_mb51
      @SUC = @sucOrd,
      @ART = @artSalida,
      @CTDA = @ctdMermaSalida,
      @TXT = @txtMermaSalida,
      @DOCP = @docpMermaSalida,
      @USR = @USER,
      @CLSM = '457';

    IF @CREAR_NUEVA_ORD = 1
    BEGIN
      IF OBJECT_ID('dbo.PV_TICKET_LOG', 'U') IS NOT NULL
      BEGIN
        SELECT TOP 1
          @precioOrig = COALESCE(
            TRY_CONVERT(FLOAT, t.PVTAT),
            0
          )
        FROM dbo.PV_TICKET_LOG t
        WHERE (
            UPPER(LTRIM(RTRIM(ISNULL(t.ORD, '')))) = UPPER(@IORD)
            OR (
              UPPER(LTRIM(RTRIM(ISNULL(t.IDFOL, '')))) = UPPER(@idfol)
              AND UPPER(LTRIM(RTRIM(ISNULL(t.ART, '')))) = UPPER(@artOrig)
            )
          )
        ORDER BY
          CASE
            WHEN UPPER(LTRIM(RTRIM(ISNULL(t.ORD, '')))) = UPPER(@IORD) THEN 0
            ELSE 1
          END,
          CASE
            WHEN UPPER(LTRIM(RTRIM(ISNULL(t.ART, '')))) = UPPER(@artOrig) THEN 0
            ELSE 1
          END,
          ISNULL(t.updated_at, CONVERT(DATETIME, '19000101', 112)) DESC,
          LTRIM(RTRIM(ISNULL(t.ID, ''))) DESC;
      END;

      IF OBJECT_ID('dbo.DAT_ART', 'U') IS NOT NULL
      BEGIN
        SELECT TOP 1
          @precioNuevo = TRY_CONVERT(FLOAT, a.PVTA)
        FROM dbo.DAT_ART a
        WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@sucOrd, ''))))
          AND UPPER(LTRIM(RTRIM(ISNULL(a.ART, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@artSalida, ''))))
        ORDER BY TRY_CONVERT(INT, ISNULL(a.BLOQ, 0)) ASC;
      END;

      IF ISNULL(@precioOrig, 0) = 0 AND OBJECT_ID('dbo.DAT_ART', 'U') IS NOT NULL
      BEGIN
        SELECT TOP 1
          @precioOrig = TRY_CONVERT(FLOAT, a.PVTA)
        FROM dbo.DAT_ART a
        WHERE UPPER(LTRIM(RTRIM(ISNULL(a.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@sucOrd, ''))))
          AND UPPER(LTRIM(RTRIM(ISNULL(a.ART, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@artOrig, ''))))
        ORDER BY TRY_CONVERT(INT, ISNULL(a.BLOQ, 0)) ASC;
      END;
    SET @precioNuevo = COALESCE(@PVTA_NUEVO, @precioNuevo, @precioOrig, 0);
    SET @importeOrig = ROUND(
      ISNULL(@precioOrig, 0) * (ISNULL(@ctdAfectada, 0) / NULLIF(@ctdOrig, 0)),
      2
    );
    SET @importeNuevo = ROUND(ISNULL(@precioNuevo, 0) * @ctdAfectada, 2);

    DECLARE @ivaIntegrado INT = 0;
    DECLARE @rqfacFolio INT = 0;
    DECLARE @tipoTran NVARCHAR(2) = 'VF';
    DECLARE @totalOrig FLOAT = 0;
    DECLARE @totalNuevo FLOAT = 0;

    SELECT TOP 1
      @ivaIntegrado = ISNULL(TRY_CONVERT(INT, s.IVA_INTEGRADO), 0)
    FROM dbo.DAT_SUC s
    WHERE UPPER(LTRIM(RTRIM(ISNULL(s.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@sucOrd, ''))));

    SELECT TOP 1
      @rqfacFolio = ISNULL(TRY_CONVERT(INT, f.REQF), 0),
      @tipoTran = CASE
        WHEN UPPER(LTRIM(RTRIM(ISNULL(f.ORIGEN_AUT, '')))) IN ('CA', 'VF') THEN UPPER(LTRIM(RTRIM(ISNULL(f.ORIGEN_AUT, ''))))
        WHEN UPPER(LTRIM(RTRIM(ISNULL(f.AUT, '')))) IN ('DCA', 'CA', 'DC', 'DG', 'CP', 'PS') THEN 'CA'
        WHEN UPPER(LTRIM(RTRIM(ISNULL(f.AUT, '')))) IN ('DVF', 'VF') THEN 'VF'
        ELSE 'VF'
      END
    FROM dbo.PV_CTR_FOL_ASVR f
    WHERE UPPER(LTRIM(RTRIM(ISNULL(f.IDFOL, '')))) = UPPER(LTRIM(RTRIM(ISNULL(@idfol, ''))))
    ORDER BY ISNULL(f.FCNM, f.FCN) DESC;

    IF @tipoTran = 'CA'
    BEGIN
      SET @totalOrig = ROUND(@importeOrig, 2);
      SET @totalNuevo = ROUND(@importeNuevo, 2);
    END
    ELSE IF @ivaIntegrado = -1
    BEGIN
      SET @totalOrig = ROUND(@importeOrig, 2);
      SET @totalNuevo = ROUND(@importeNuevo, 2);
    END
    ELSE IF @rqfacFolio = 1
    BEGIN
      SET @totalOrig = ROUND(@importeOrig * 1.16, 2);
      SET @totalNuevo = ROUND(@importeNuevo * 1.16, 2);
    END
    ELSE
    BEGIN
      SET @totalOrig = ROUND(@importeOrig, 2);
      SET @totalNuevo = ROUND(@importeNuevo, 2);
    END;

    SET @diffVenta = COALESCE(@DIFERENCIA_SELLADA, ROUND(@totalNuevo - @totalOrig, 2));

      EXEC dbo.sp_ordenes_trabajo_registrar_ctrl_ctas_diff
        @SUC = @sucOrd,
        @CLIENT = @clien,
        @IDFOL = @idfol,
        @DIFF = @diffVenta,
        @DOCDIF = @doc,
        @DESC_MOV = @txtDiff,
      @USR = @USER;
    END;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    @IORD AS IORD_ORIG,
    @newIord AS IORD_NUEVA,
    @idfol AS IDFOL,
    @motrInt AS MOTR,
    @motivoLabel AS MOTIVO,
    @ctdOrig AS CTD_ORIGINAL,
    @ctdAfectada AS CTD_MERMA,
    @ctdAfectada AS CTD_C_M,
    @remanente AS CTD_REMANENTE,
    1 AS ORD_CANCELADA,
    @diffVenta AS DIFERENCIA_ECONOMICA,
    CASE WHEN ABS(ISNULL(@diffVenta, 0)) >= 0.009 THEN 1 ELSE 0 END AS AFECTACION_CONTABLE,
    @sucOrd AS SUC,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR;
END;

CREATE OR ALTER PROCEDURE [dbo].[sp_cont_apply_adjustment]
  @SUC        NVARCHAR(10),
  @CONT       NVARCHAR(255),
  @USR        NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  IF @SUC IS NULL OR LTRIM(RTRIM(@SUC)) = '' THROW 50010, 'SUC no puede venir vacío', 1;
  IF @CONT IS NULL OR LTRIM(RTRIM(@CONT)) = '' THROW 50011, 'CONT no puede venir vacío', 1;
  IF @USR IS NULL OR LTRIM(RTRIM(@USR)) = '' SET @USR = 'SYSTEM';

  DECLARE @now DATETIME = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()));
  DECLARE @ESTA NVARCHAR(50);
  DECLARE @EPS FLOAT = 0.000001;   -- tolerancia para “casi cero”

  SELECT TOP 1 @ESTA = ESTA
  FROM dbo.DAT_CONT_CTRL
  WHERE SUC=@SUC AND CONT=@CONT;

  IF @ESTA IS NULL THROW 50001, 'No existe el conteo en DAT_CONT_CTRL', 1;

  IF @ESTA NOT IN ('LISTO','CERRADO')
    THROW 50012, 'El conteo no está en un estado válido para AJUSTAR (permitidos: LISTO/CERRADO).', 1;

  IF @ESTA IN ('AJUSTADO','CERRADO_AJUSTADO')
    THROW 50020, 'El conteo ya fue ajustado previamente (ESTA=AJUSTADO).', 1;

  IF EXISTS (SELECT 1 FROM dbo.DAT_CONT_AJUSTE_LOG WHERE SUC=@SUC AND CONT=@CONT)
    THROW 50022, 'Este conteo ya tiene registro de ajuste en LOG. Evito duplicar.', 1;

  IF EXISTS (SELECT 1 FROM dbo.DAT_MB51 WHERE SUC=@SUC AND TXT=@CONT AND CLSM IN ('701','702'))
    THROW 50021, 'Ya existen movimientos en DAT_MB51 con TXT=CONT para este conteo. Evito doble ajuste.', 1;

  BEGIN TRAN;
  BEGIN TRY

    DECLARE @doc701 BIGINT = NEXT VALUE FOR dbo.SEQ_DOC_MOV;
    DECLARE @doc702 BIGINT = NEXT VALUE FOR dbo.SEQ_DOC_MOV;

    DECLARE @DOCP701 NVARCHAR(50) = CONCAT('NC', @doc701);
    DECLARE @DOCP702 NVARCHAR(50) = CONCAT('NC', @doc702);

    /* =========================================================
       1) Tomar DIFs por almacén (SOLO EXT=0) y SOLO DIF != 0
          Importante: CTDA y CTOT conservan signo (como tu VBA)
       ========================================================= */

    ;WITH D AS (
      SELECT
        d.SUC,
        d.CONT,
        d.ART,
        d.CTOP,
        v.ALMACEN,
        TRY_CONVERT(FLOAT, v.DIF_RAW) AS DIF
      FROM dbo.DAT_DET_SVR d
      CROSS APPLY (VALUES
        ('001', d.DIF_01),
        ('002', d.DIF_02),
        ('M001', d.DIF_M1),
        ('T001', d.DIF_T1)
      ) v(ALMACEN, DIF_RAW)
      WHERE d.SUC=@SUC
        AND d.CONT=@CONT
        AND ISNULL(d.EXT,0) = 0
    ),
    F AS (
      SELECT
        SUC,
        CONT,
        ART,
        CTOP,
        ALMACEN,
        DIF,
        CASE WHEN DIF > 0 THEN '701' ELSE '702' END AS CLSM,
        CASE WHEN DIF > 0 THEN @doc701 ELSE @doc702 END AS DOCNUM,
        CASE WHEN DIF > 0 THEN @DOCP701 ELSE @DOCP702 END AS DOCP_TXT
      FROM D
      WHERE DIF IS NOT NULL
        AND ABS(DIF) > @EPS          -- ✅ solo diferencias reales
    ),
    R AS (
      SELECT
        *,
        ROW_NUMBER() OVER (PARTITION BY CLSM ORDER BY ART, ALMACEN) AS RN
      FROM F
    )
    INSERT INTO dbo.DAT_MB51
    (
      IDPD,
      [USER],
      CLSM,
      DOCP,
      ART,
      CTDA,
      CTOT,
      FCND,
      FCNC,
      TXT,
      ALMACEN,
      VTAESP,
      SUC
    )
    SELECT
      CONCAT(CAST(RN AS NVARCHAR(20)), CAST(DOCNUM AS NVARCHAR(30))) AS IDPD,
      @USR AS [USER],
      CLSM,
      DOCP_TXT AS DOCP,
      ART,
      DIF AS CTDA,                                 -- ✅ con signo
      CAST(DIF * ISNULL(CTOP,0) AS FLOAT) AS CTOT,  -- ✅ con signo
      @now AS FCND,
      @now AS FCNC,
      @CONT AS TXT,
      ALMACEN,
      NULL AS VTAESP,
      @SUC AS SUC
    FROM R;

    DECLARE @rows INT = @@ROWCOUNT;
    IF @rows = 0 THROW 50030, 'No hay diferencias por almacén (EXT=0) para ajustar (no se generó ningún ajuste).', 1;

    /* =========================================================
       2) Actualizar stock en DAT_ART al total capturado
          (001+002+M001+T001) SOLO EXT=0
       ========================================================= */
    ;WITH S AS (
      SELECT
        SUC,
        ART,
        CAST(ISNULL([001],0) + ISNULL([002],0) + ISNULL(M001,0) + ISNULL(T001,0) AS FLOAT) AS STOCK_FINAL
      FROM dbo.DAT_DET_SVR
      WHERE SUC=@SUC AND CONT=@CONT AND ISNULL(EXT,0)=0
    )
    UPDATE a
    SET a.STOCK = s.STOCK_FINAL
    FROM dbo.DAT_ART a
    INNER JOIN S s ON a.SUC=s.SUC AND a.ART=s.ART;

    /* 3) Marcar conteo como AJUSTADO */
    UPDATE dbo.DAT_CONT_CTRL
    SET ESTA = 'AJUSTADO',
        FCNC = @now,
        [modificado_por] = @USR
    WHERE SUC=@SUC AND CONT=@CONT;

    /* 4) Log */
    INSERT INTO dbo.DAT_CONT_AJUSTE_LOG (SUC, CONT, DOCP_701, DOCP_702, MOVS, AJUST_USER)
    VALUES (@SUC, @CONT, @DOCP701, @DOCP702, @rows, @USR);

    COMMIT;

    SELECT
      @SUC AS SUC,
      @CONT AS CONT,
      @DOCP701 AS DOCP_701,
      @DOCP702 AS DOCP_702,
      @rows AS MOVIMIENTOS_INSERTADOS;

  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;
    THROW;
  END CATCH
END

CREATE OR ALTER PROCEDURE dbo.sp_ps_ticket_update_pvta
  @IDFOL NVARCHAR(255),
  @ART NVARCHAR(255),
  @PVTA DECIMAL(18, 4),
  @USER NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @idfolNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@IDFOL, '')));
  DECLARE @artNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@ART, '')));
  DECLARE @lineOrd NVARCHAR(255);
  DECLARE @lineUpc NVARCHAR(10);
  DECLARE @lineCtd DECIMAL(18, 4);
  DECLARE @clienActual BIGINT;
  DECLARE @valimp DECIMAL(18, 4);
  DECLARE @isAdeudoService BIT = 0;
  DECLARE @consumidoOtros DECIMAL(18, 4) = 0;
  DECLARE @saldoDisponible DECIMAL(18, 4) = 0;
  DECLARE @lineTotal DECIMAL(18, 4) = 0;
  DECLARE @ticketObjId INT = OBJECT_ID('dbo.PV_TICKET_LOG');
  DECLARE @hasPvta BIT = 0;
  DECLARE @hasPvtat BIT = 0;
  DECLARE @hasUpdatedAt BIT = 0;
  DECLARE @sql NVARCHAR(MAX);

  IF @idfolNorm = '' OR @artNorm = ''
    THROW 57050, 'IDFOL y ART son requeridos', 1;

  IF @PVTA IS NULL OR @PVTA <= 0
    THROW 57051, 'PVTA debe ser mayor a 0', 1;

  IF @ticketObjId IS NULL
    THROW 57052, 'No existe tabla PV_TICKET_LOG', 1;

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    SELECT TOP 1
      @lineOrd = LTRIM(RTRIM(ISNULL(ORD, ''))),
      @lineUpc = UPPER(LTRIM(RTRIM(ISNULL(UPC, '')))),
      @lineCtd = TRY_CONVERT(DECIMAL(18,4), CTD)
    FROM dbo.PV_TICKET_LOG WITH (UPDLOCK, HOLDLOCK)
    WHERE IDFOL = @idfolNorm
      AND ART = @artNorm;

    IF @lineUpc IS NULL OR @lineUpc = ''
      THROW 57053, 'La linea de ticket no existe', 1;

    IF @lineUpc IN ('AD', 'AP', 'CR')
      SET @isAdeudoService = 1;

    IF @lineOrd IS NULL OR @lineOrd = ''
      THROW 57054, 'Debe asignar referencia (ORD) antes de capturar PVTA', 1;

    SELECT TOP 1
      @clienActual = TRY_CONVERT(BIGINT, CLIEN)
    FROM dbo.PV_CTR_FOL_ASVR
    WHERE UPPER(LTRIM(RTRIM(ISNULL(IDFOL, '')))) = UPPER(@idfolNorm);

    IF @clienActual IS NULL OR @clienActual <= 1
      THROW 57055, 'El folio no tiene cliente válido para validar adeudo', 1;

    IF @isAdeudoService = 1
    BEGIN
      ;WITH adeudoFolio AS (
        SELECT
          LTRIM(RTRIM(ISNULL(CAST(c.IDFOL AS NVARCHAR(255)), ''))) AS IDFOL,
          LTRIM(RTRIM(ISNULL(CAST(c.NDOC AS NVARCHAR(255)), ''))) AS NDOC,
          ROUND(SUM(ISNULL(TRY_CONVERT(DECIMAL(18,4), c.IMPT), 0)), 4) AS ADEUDO
        FROM dbo.DAT_CTRL_CTAS c
        WHERE TRY_CONVERT(BIGINT, c.CLIENT) = @clienActual
        GROUP BY
          c.IDFOL,
          c.NDOC
      )
      SELECT
        @valimp = ABS(ROUND(ISNULL(SUM(ADEUDO), 0), 4))
      FROM adeudoFolio
      WHERE
        (
          UPPER(LTRIM(RTRIM(ISNULL(IDFOL, '')))) = UPPER(@lineOrd)
          OR UPPER(LTRIM(RTRIM(ISNULL(NDOC, '')))) = UPPER(@lineOrd)
        )
        AND ADEUDO < 0;
    END
    ELSE
    BEGIN
      ;WITH adeudoSel AS (
        SELECT
          LTRIM(RTRIM(ISNULL(CAST(c.IDFOL AS NVARCHAR(255)), ''))) AS IDFOL,
          LTRIM(RTRIM(ISNULL(CAST(c.NDOC AS NVARCHAR(255)), ''))) AS NDOC,
          ISNULL(rel.RELACION, '') AS RELACION,
          ROUND(SUM(ISNULL(TRY_CONVERT(DECIMAL(18,4), c.IMPT), 0)), 4) AS ADEUDO
        FROM dbo.DAT_CTRL_CTAS c
        OUTER APPLY (
          SELECT TOP 1
            UPPER(LTRIM(RTRIM(ISNULL(x.RELACION, '')))) AS RELACION
          FROM dbo.DAT_CAT_CTAS x
          WHERE UPPER(LTRIM(RTRIM(ISNULL(x.CTA, '')))) = UPPER(LTRIM(RTRIM(ISNULL(CAST(c.CTA AS NVARCHAR(50)), ''))))
            AND (
              UPPER(LTRIM(RTRIM(ISNULL(x.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(CAST(c.SUC AS NVARCHAR(10)), ''))))
              OR LTRIM(RTRIM(ISNULL(x.SUC, ''))) = ''
            )
          ORDER BY CASE
            WHEN UPPER(LTRIM(RTRIM(ISNULL(x.SUC, '')))) = UPPER(LTRIM(RTRIM(ISNULL(CAST(c.SUC AS NVARCHAR(10)), ''))))
              THEN 0 ELSE 1
          END
        ) rel
        WHERE TRY_CONVERT(BIGINT, c.CLIENT) = @clienActual
        GROUP BY
          c.IDFOL,
          c.NDOC,
          rel.RELACION
      )
      SELECT
        @valimp = ABS(ROUND(ISNULL(SUM(ADEUDO), 0), 4))
      FROM adeudoSel
      WHERE
        UPPER(LTRIM(RTRIM(ISNULL(RELACION, '')))) = @lineUpc
        AND (
          UPPER(LTRIM(RTRIM(ISNULL(IDFOL, '')))) = UPPER(@lineOrd)
          OR UPPER(LTRIM(RTRIM(ISNULL(NDOC, '')))) = UPPER(@lineOrd)
        )
        AND ADEUDO < 0;
    END;

    IF @valimp IS NULL
      THROW 57056, 'No se encontro adeudo para validar el importe capturado', 1;

    IF @lineCtd IS NULL OR @lineCtd <= 0
      SET @lineCtd = 1;

    SELECT
      @consumidoOtros = ISNULL(SUM(
        ROUND(
          ISNULL(TRY_CONVERT(DECIMAL(18,4), t.PVTA), 0)
          * ISNULL(NULLIF(TRY_CONVERT(DECIMAL(18,4), t.CTD), 0), 1),
          4
        )
      ), 0)
    FROM dbo.PV_TICKET_LOG t
    WHERE t.IDFOL = @idfolNorm
      AND t.ART <> @artNorm
      AND (
        (@isAdeudoService = 1 AND UPPER(LTRIM(RTRIM(ISNULL(t.UPC, '')))) IN ('AD', 'AP', 'CR'))
        OR (@isAdeudoService = 0 AND UPPER(LTRIM(RTRIM(ISNULL(t.UPC, '')))) = @lineUpc)
      )
      AND UPPER(LTRIM(RTRIM(ISNULL(t.ORD, '')))) = UPPER(@lineOrd);

    SET @saldoDisponible = ROUND(@valimp - @consumidoOtros, 4);
    SET @lineTotal = ROUND(@PVTA * @lineCtd, 4);

    IF @isAdeudoService = 1 AND @lineTotal > @valimp
      THROW 57057, 'PVTA excede la deuda del folio referenciado', 1;

    IF @saldoDisponible <= 0 OR @lineTotal > @saldoDisponible
      THROW 57057, 'PVTA excede el adeudo disponible para la referencia', 1;

    SELECT
      @hasPvta = MAX(CASE WHEN UPPER(name) = 'PVTA' THEN 1 ELSE 0 END),
      @hasPvtat = MAX(CASE WHEN UPPER(name) = 'PVTAT' THEN 1 ELSE 0 END),
      @hasUpdatedAt = MAX(CASE WHEN UPPER(name) = 'UPDATED_AT' THEN 1 ELSE 0 END)
    FROM sys.columns
    WHERE object_id = @ticketObjId;

    IF @hasPvta = 0
      THROW 57058, 'La tabla PV_TICKET_LOG no contiene columna PVTA', 1;

    SET @sql = N'UPDATE dbo.PV_TICKET_LOG SET PVTA = @pPVTA'
      + CASE WHEN @hasPvtat = 1 THEN N', PVTAT = ROUND(@pPVTA * @pCTD, 4)' ELSE N'' END
      + CASE WHEN @hasUpdatedAt = 1 THEN N', UPDATED_AT = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))' ELSE N'' END
      + N' WHERE IDFOL = @pIDFOL AND ART = @pART;';

    EXEC sys.sp_executesql
      @sql,
      N'@pPVTA DECIMAL(18,4), @pCTD DECIMAL(18,4), @pIDFOL NVARCHAR(255), @pART NVARCHAR(255)',
      @pPVTA = @PVTA,
      @pCTD = @lineCtd,
      @pIDFOL = @idfolNorm,
      @pART = @artNorm;

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;

    SELECT
      ID,
      IDFOL,
      ART,
      UPC,
      DES,
      ORD,
      TRY_CONVERT(DECIMAL(18,4), CTD) AS CTD,
      TRY_CONVERT(DECIMAL(18,4), PVTA) AS PVTA,
      TRY_CONVERT(DECIMAL(18,4), PVTAT) AS PVTAT,
      ROUND(ISNULL(TRY_CONVERT(DECIMAL(18,4), PVTA), 0) * ISNULL(TRY_CONVERT(DECIMAL(18,4), CTD), 0), 4) AS TOTAL
    FROM dbo.PV_TICKET_LOG
    WHERE IDFOL = @idfolNorm
      AND ART = @artNorm;
  END TRY
  BEGIN CATCH
    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_rec_recepcion_borrador_guardar
  @NPED nvarchar(100),
  @USR nvarchar(100),
  @TIPO_RECEPCION nvarchar(20)=NULL,
  @TIPO_DOC nvarchar(20)=NULL,
  @FOLIO_DOC nvarchar(100)=NULL,
  @GUIA nvarchar(100)=NULL,
  @PAQUETERIA nvarchar(120)=NULL,
  @OBSERVACIONES nvarchar(1000)=NULL,
  @ITEMS_JSON nvarchar(max)=N'[]'
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  IF ISJSON(@ITEMS_JSON)<>1 THROW 51000,'El borrador de artÃ­culos no es JSON vÃ¡lido.',1;

  DECLARE @SUC nvarchar(20);
  SELECT @SUC=UPPER(LTRIM(RTRIM(SUC)))
  FROM dbo.REC_CAB_PED
  WHERE NPED=@NPED;
  IF @SUC IS NULL THROW 51000,'La orden de compra no existe.',1;

  BEGIN TRANSACTION;
  MERGE dbo.REC_BORRADOR_REC WITH(HOLDLOCK) AS target
  USING (SELECT @NPED NPED) AS source ON source.NPED=target.NPED
  WHEN MATCHED THEN UPDATE SET
    SUC=@SUC,USR=@USR,TIPO_RECEPCION=NULLIF(@TIPO_RECEPCION,''),
    TIPO_DOC=NULLIF(@TIPO_DOC,''),FOLIO_DOC=NULLIF(@FOLIO_DOC,''),
    GUIA=NULLIF(@GUIA,''),PAQUETERIA=NULLIF(@PAQUETERIA,''),
    OBSERVACIONES=NULLIF(@OBSERVACIONES,''),FCNM=dbo.fn_ioe_business_datetime(SYSUTCDATETIME())
  WHEN NOT MATCHED THEN
    INSERT(NPED,SUC,USR,TIPO_RECEPCION,TIPO_DOC,FOLIO_DOC,GUIA,PAQUETERIA,OBSERVACIONES,FCNM)
    VALUES(@NPED,@SUC,@USR,NULLIF(@TIPO_RECEPCION,''),NULLIF(@TIPO_DOC,''),
      NULLIF(@FOLIO_DOC,''),NULLIF(@GUIA,''),NULLIF(@PAQUETERIA,''),
      NULLIF(@OBSERVACIONES,''),dbo.fn_ioe_business_datetime(SYSUTCDATETIME()));

  DELETE dbo.REC_BORRADOR_REC_DET WHERE NPED=@NPED;
  INSERT dbo.REC_BORRADOR_REC_DET(NPED,IDPED,ART,CTD_REC,CTD_ACEP,ESTATUS)
  SELECT @NPED,LTRIM(RTRIM(IDPED)),LTRIM(RTRIM(ART)),
    COALESCE(CTD_REC,0),COALESCE(CTD_ACEP,0),
    CASE WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATUS,'')))) IN ('APROBADO','RECHAZADO','NO_APLICA')
      THEN UPPER(LTRIM(RTRIM(ESTATUS))) ELSE NULL END
  FROM OPENJSON(@ITEMS_JSON) WITH(
    IDPED nvarchar(510) '$.idped',
    ART nvarchar(510) '$.art',
    CTD_REC float '$.cantidadRecibida',
    CTD_ACEP float '$.cantidadAceptada',
    ESTATUS nvarchar(20) '$.estatus'
  )
  WHERE NULLIF(LTRIM(RTRIM(IDPED)),'') IS NOT NULL
    AND NULLIF(LTRIM(RTRIM(ART)),'') IS NOT NULL;
  COMMIT;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_enviar_lote
  @IORDS NVARCHAR(MAX),
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @ords TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY
  );

  INSERT INTO @ords (IORD)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(ISNULL(value, ''))))
  FROM STRING_SPLIT(ISNULL(@IORDS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  IF NOT EXISTS (SELECT 1 FROM @ords)
    THROW 58100, 'Debe enviar al menos una ORD en @IORDS', 1;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @target TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY,
    IDFOL NVARCHAR(255) NULL,
    SUC NVARCHAR(10) NULL,
    ESTSEGU FLOAT NULL,
    LABOR INT NULL,
    LAB_SUC NVARCHAR(10) NULL,
    LAB_TIPOLAB NVARCHAR(100) NULL,
    LAB_UBILAB NVARCHAR(100) NULL,
    LAB_DESC NVARCHAR(255) NULL
  );

  INSERT INTO @target (IORD, IDFOL, SUC, ESTSEGU, LABOR, LAB_SUC, LAB_TIPOLAB, LAB_UBILAB, LAB_DESC)
  SELECT
    UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) AS IORD,
    o.IDFOL,
    o.SUC,
    TRY_CONVERT(FLOAT, o.ESTSEGU) AS ESTSEGU,
    TRY_CONVERT(INT, o.LABOR) AS LABOR,
    UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) AS LAB_SUC,
    UPPER(LTRIM(RTRIM(ISNULL(lab.TIPOLAB, '')))) AS LAB_TIPOLAB,
    UPPER(LTRIM(RTRIM(ISNULL(lab.UBILAB, '')))) AS LAB_UBILAB,
    UPPER(LTRIM(RTRIM(ISNULL(lab.LAB, '')))) AS LAB_DESC
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  INNER JOIN @ords i
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = i.IORD
  WHERE
    (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF EXISTS (
    SELECT 1
    FROM @ords i
    LEFT JOIN @target t ON t.IORD = i.IORD
    WHERE t.IORD IS NULL
  )
  BEGIN
    DECLARE @missingIords NVARCHAR(2000) = (
      SELECT STRING_AGG(i.IORD, ', ')
      FROM @ords i
      LEFT JOIN @target t ON t.IORD = i.IORD
      WHERE t.IORD IS NULL
    );
    DECLARE @missingMsg NVARCHAR(2048) = LEFT(
      CONCAT('ORD no encontrada o sin acceso por sucursal: ', ISNULL(@missingIords, '')),
      2048
    );
    THROW 58101, @missingMsg, 1;
  END;

  IF EXISTS (
    SELECT 1
    FROM @target t
    WHERE ISNULL(t.ESTSEGU, -1) <> 3
  )
  BEGIN
    DECLARE @invalidIords NVARCHAR(2000) = (
      SELECT STRING_AGG(t.IORD, ', ')
      FROM @target t
      WHERE ISNULL(t.ESTSEGU, -1) <> 3
    );
    DECLARE @invalidMsg NVARCHAR(2048) = LEFT(
      CONCAT('Solo se pueden enviar ORDs en estatus 3 (NUEVA AUTORIZADA): ', ISNULL(@invalidIords, '')),
      2048
    );
    THROW 58102, @invalidMsg, 1;
  END;

  IF EXISTS (
    SELECT 1
    FROM @target t
    WHERE ISNULL(t.LABOR, 0) <= 0
  )
  BEGIN
    DECLARE @invalidLaborIords NVARCHAR(2000) = (
      SELECT STRING_AGG(t.IORD, ', ')
      FROM @target t
      WHERE ISNULL(t.LABOR, 0) <= 0
    );
    DECLARE @invalidLaborMsg NVARCHAR(2048) = LEFT(
      CONCAT('Las siguientes ORDs deben tener laboratorio asignado para enviar a taller: ', ISNULL(@invalidLaborIords, '')),
      2048
    );
    THROW 58103, @invalidLaborMsg, 1;
  END;

  BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE o
    SET
      o.ESTSEGU = CASE
        WHEN ISNULL(t.LAB_UBILAB, '') LIKE '%EXTER%'
          OR (
            ISNULL(t.LAB_UBILAB, '') = ''
            AND (
              ISNULL(t.LAB_SUC, '') = ''
              OR ISNULL(t.LAB_TIPOLAB, '') LIKE '%EXTER%'
              OR ISNULL(t.LAB_DESC, '') LIKE '%EXTER%'
            )
          )
        THEN 9
        ELSE 5
      END,
      o.ESTATUS = 2,
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    INNER JOIN @target t
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    o.IORD,
    o.IDFOL,
    o.SUC,
    o.ESTATUS,
    o.ESTSEGU,
    o.FCNMOD,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR
  FROM dbo.PV_CTR_ORDS o
  INNER JOIN @target t
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD
  ORDER BY o.IORD;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ps_form_delete
  @IDFOL NVARCHAR(255),
  @IDF NVARCHAR(255),
  @USER NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @idfolNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@IDFOL, '')));
  DECLARE @idfNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@IDF, '')));
  DECLARE @total DECIMAL(18, 4);
  DECLARE @pagado DECIMAL(18, 4);
  DECLARE @epsilon DECIMAL(18, 6) = 0.0001;
  DECLARE @formTableName NVARCHAR(128) = NULL;
  DECLARE @sql NVARCHAR(MAX);

  IF @idfolNorm = '' OR @idfNorm = ''
    THROW 57100, 'IDFOL e IDF son requeridos', 1;

  IF OBJECT_ID('dbo.PV_CTR_FOL_FORMTMP', 'U') IS NOT NULL
    SET @formTableName = N'dbo.PV_CTR_FOL_FORMTMP';
  ELSE IF OBJECT_ID('dbo.PV_CTR_FOL_FORM', 'U') IS NOT NULL
    SET @formTableName = N'dbo.PV_CTR_FOL_FORM';

  IF @formTableName IS NULL
    THROW 57101, 'No existe tabla de formas de pago (PV_CTR_FOL_FORMTMP/PV_CTR_FOL_FORM)', 1;

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    SET @sql = N'
      DELETE FROM ' + @formTableName + N'
      WHERE IDFOL = @pIDFOL
        AND UPPER(LTRIM(RTRIM(CAST(IDF AS NVARCHAR(255))))) = UPPER(@pIDF);';
    EXEC sys.sp_executesql
      @sql,
      N'@pIDFOL NVARCHAR(255), @pIDF NVARCHAR(255)',
      @pIDFOL = @idfolNorm,
      @pIDF = @idfNorm;

    IF @@ROWCOUNT = 0
      THROW 57102, 'La forma de pago no existe para el folio', 1;

    SELECT TOP 1 @total = ABS(TRY_CONVERT(DECIMAL(18,4), IMPT))
    FROM dbo.PV_CTR_FOL_ASVR WITH (UPDLOCK, HOLDLOCK)
    WHERE IDFOL = @idfolNorm;

    SET @total = ISNULL(@total, 0);

    SET @sql = N'
      SELECT @pPagado = ROUND(SUM(ISNULL(TRY_CONVERT(DECIMAL(18,4), IMPP), 0)), 4)
      FROM ' + @formTableName + N'
      WHERE IDFOL = @pIDFOL;';
    EXEC sys.sp_executesql
      @sql,
      N'@pIDFOL NVARCHAR(255), @pPagado DECIMAL(18,4) OUTPUT',
      @pIDFOL = @idfolNorm,
      @pPagado = @pagado OUTPUT;

    SET @pagado = ISNULL(@pagado, 0);

    UPDATE dbo.PV_CTR_FOL_ASVR
    SET
      ESTA = CASE WHEN @total <= 0 OR @pagado + @epsilon < @total THEN 'PENDIENTE' ELSE ESTA END,
      IMPP = @pagado,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    WHERE IDFOL = @idfolNorm;

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;

    EXEC dbo.sp_ps_form_summary @IDFOL = @idfolNorm;
  END TRY
  BEGIN CATCH
    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_rec_recepcion_actualizar_cantidad
  @DOCREC nvarchar(510),@IDREC nvarchar(510),@CANTIDAD float,@USR nvarchar(100)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;
  DECLARE @lock int,@lock_resource nvarchar(255)=CONCAT('DAT_REC_DOC_',@DOCREC);
  EXEC @lock=sys.sp_getapplock @Resource=@lock_resource,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=15000;
  IF @lock<0 THROW 51000,'No fue posible bloquear la recepcion.',1;
  IF @CANTIDAD IS NULL OR @CANTIDAD<0 THROW 51000,'La cantidad fisica no es valida.',1;
  DECLARE @ESTATUS nvarchar(30),@NPED nvarchar(510),@SUC nvarchar(510);
  SELECT @ESTATUS=r.ESTATUS_REC,@NPED=r.NPED,@SUC=c.SUC FROM dbo.REC_CTRL_DOC_REC r WITH(UPDLOCK,HOLDLOCK) JOIN dbo.REC_CAB_PED c ON c.NPED=r.NPED WHERE r.DOCREC=@DOCREC;
  IF @ESTATUS IS NULL THROW 51000,'La recepcion no existe.',1;
  IF @ESTATUS<>'VALIDADO' THROW 51000,'Solo se puede editar una recepcion validada.',1;
  DECLARE @IDPED nvarchar(510),@ART nvarchar(510),@ANTERIOR float,@PENDIENTE float,@CTO money;
  SELECT @IDPED=h.IDPED,@ART=h.ART,@ANTERIOR=h.CTD,@PENDIENTE=CASE WHEN h.IDPED IS NULL THEN 0 WHEN ISNULL(d.CTDPED,0)>ISNULL(d.CTDREC,0) THEN ISNULL(d.CTDPED,0)-ISNULL(d.CTDREC,0) ELSE 0 END,@CTO=COALESCE(d.CTO,a.CTOP,0)
  FROM dbo.REC_CTO_HIST h WITH(UPDLOCK,HOLDLOCK) LEFT JOIN dbo.REC_DET_PED d ON d.IDPED=h.IDPED LEFT JOIN dbo.DAT_ART a ON a.SUC=@SUC AND a.ART=h.ART WHERE h.DOCREC=@DOCREC AND h.IDREC=@IDREC;
  IF @ART IS NULL THROW 51000,'El articulo no pertenece a la recepcion.',1;
  UPDATE dbo.REC_CTO_HIST SET CTD=@CANTIDAD,CTD_ACEP=@CANTIDAD,CTDVTA=ISNULL(@CTO,0)*@CANTIDAD,CALIDAD_ESTATUS='APROBADO' WHERE DOCREC=@DOCREC AND IDREC=@IDREC;
  DELETE dbo.REC_INCI_PED WHERE DOCREC=@DOCREC AND IDREC=@IDREC AND TIPO IN ('FALTANTE','SOBRANTE','NO_SOLICITADO');
  IF @IDPED IS NULL OR @CANTIDAD<>@PENDIENTE
    INSERT dbo.REC_INCI_PED(DOCREC,IDREC,TIPO,ART,CTD_ESPERADA,CTD_RECIBIDA,DIFERENCIA,MOTIVO,ESTATUS,USR)
    VALUES(@DOCREC,@IDREC,CASE WHEN @IDPED IS NULL THEN 'NO_SOLICITADO' WHEN @CANTIDAD>@PENDIENTE THEN 'SOBRANTE' ELSE 'FALTANTE' END,@ART,@PENDIENTE,@CANTIDAD,@CANTIDAD-@PENDIENTE,'Ajuste por Jefe de Inventarios','ABIERTA',@USR);
  UPDATE r SET NART=(SELECT COUNT(*) FROM dbo.REC_CTO_HIST h WHERE h.DOCREC=@DOCREC AND ISNULL(h.CTD,0)>0),IMPT=(SELECT SUM(ISNULL(h.CTDVTA,0)) FROM dbo.REC_CTO_HIST h WHERE h.DOCREC=@DOCREC) FROM dbo.REC_CTRL_DOC_REC r WHERE r.DOCREC=@DOCREC;
  INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
  SELECT IDUSUARIO,'AJUSTAR_CANTIDAD_FISICA','DAT_REC','REC_CTO_HIST',@IDREC,@SUC,CONCAT('{"docrec":"',STRING_ESCAPE(@DOCREC,'json'),'","anterior":',COALESCE(CONVERT(varchar(50),@ANTERIOR),'null'),',"nueva":',CONVERT(varchar(50),@CANTIDAD),'}'),SYSUTCDATETIME() FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
  COMMIT; SELECT @DOCREC DOCREC,@IDREC IDREC,@CANTIDAD CANTIDAD_FISICA;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_recibir_lote
  @IORDS NVARCHAR(MAX),
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @ords TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY
  );

  INSERT INTO @ords (IORD)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(ISNULL(value, ''))))
  FROM STRING_SPLIT(ISNULL(@IORDS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  IF NOT EXISTS (SELECT 1 FROM @ords)
    THROW 58210, 'Debe enviar al menos una ORD en @IORDS', 1;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @target TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY,
    IDFOL NVARCHAR(255) NULL,
    SUC NVARCHAR(10) NULL,
    ESTSEGU FLOAT NULL,
    LAB_SUC NVARCHAR(10) NULL,
    LAB_TIPOLAB NVARCHAR(100) NULL,
    LAB_UBILAB NVARCHAR(100) NULL,
    LAB_DESC NVARCHAR(255) NULL
  );

  INSERT INTO @target (IORD, IDFOL, SUC, ESTSEGU, LAB_SUC, LAB_TIPOLAB, LAB_UBILAB, LAB_DESC)
  SELECT
    UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) AS IORD,
    o.IDFOL,
    o.SUC,
    TRY_CONVERT(FLOAT, o.ESTSEGU) AS ESTSEGU,
    UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) AS LAB_SUC,
    UPPER(LTRIM(RTRIM(ISNULL(lab.TIPOLAB, '')))) AS LAB_TIPOLAB,
    UPPER(LTRIM(RTRIM(ISNULL(lab.UBILAB, '')))) AS LAB_UBILAB,
    UPPER(LTRIM(RTRIM(ISNULL(lab.LAB, '')))) AS LAB_DESC
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  INNER JOIN @ords i
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = i.IORD
  WHERE
    (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF EXISTS (
    SELECT 1
    FROM @ords i
    LEFT JOIN @target t ON t.IORD = i.IORD
    WHERE t.IORD IS NULL
  )
  BEGIN
    DECLARE @missingIords NVARCHAR(2000) = (
      SELECT STRING_AGG(i.IORD, ', ')
      FROM @ords i
      LEFT JOIN @target t ON t.IORD = i.IORD
      WHERE t.IORD IS NULL
    );
    DECLARE @missingMsg NVARCHAR(2048) = LEFT(
      CONCAT('ORD no encontrada o sin acceso por sucursal: ', ISNULL(@missingIords, '')),
      2048
    );
    THROW 58211, @missingMsg, 1;
  END;

  IF EXISTS (
    SELECT 1
    FROM @target t
    WHERE NOT (
      (
        (
          ISNULL(t.LAB_UBILAB, '') LIKE '%EXTER%'
          OR (
            ISNULL(t.LAB_UBILAB, '') = ''
            AND (
              ISNULL(t.LAB_SUC, '') = ''
              OR ISNULL(t.LAB_TIPOLAB, '') LIKE '%EXTER%'
              OR ISNULL(t.LAB_DESC, '') LIKE '%EXTER%'
            )
          )
        )
        AND ISNULL(t.ESTSEGU, -1) IN (5, 9)
      )
      OR (
        NOT (
          ISNULL(t.LAB_UBILAB, '') LIKE '%EXTER%'
          OR (
            ISNULL(t.LAB_UBILAB, '') = ''
            AND (
              ISNULL(t.LAB_SUC, '') = ''
              OR ISNULL(t.LAB_TIPOLAB, '') LIKE '%EXTER%'
              OR ISNULL(t.LAB_DESC, '') LIKE '%EXTER%'
            )
          )
        )
        AND ISNULL(t.ESTSEGU, -1) = 5
      )
    )
  )
  BEGIN
    DECLARE @invalidIords NVARCHAR(2000) = (
      SELECT STRING_AGG(t.IORD, ', ')
      FROM @target t
      WHERE NOT (
        (
          (
            ISNULL(t.LAB_UBILAB, '') LIKE '%EXTER%'
            OR (
              ISNULL(t.LAB_UBILAB, '') = ''
              AND (
                ISNULL(t.LAB_SUC, '') = ''
                OR ISNULL(t.LAB_TIPOLAB, '') LIKE '%EXTER%'
                OR ISNULL(t.LAB_DESC, '') LIKE '%EXTER%'
              )
            )
          )
          AND ISNULL(t.ESTSEGU, -1) IN (5, 9)
        )
        OR (
          NOT (
            ISNULL(t.LAB_UBILAB, '') LIKE '%EXTER%'
            OR (
              ISNULL(t.LAB_UBILAB, '') = ''
              AND (
                ISNULL(t.LAB_SUC, '') = ''
                OR ISNULL(t.LAB_TIPOLAB, '') LIKE '%EXTER%'
                OR ISNULL(t.LAB_DESC, '') LIKE '%EXTER%'
              )
            )
          )
          AND ISNULL(t.ESTSEGU, -1) = 5
        )
      )
    );
    DECLARE @invalidMsg NVARCHAR(2048) = LEFT(
      CONCAT('Solo se pueden recibir ORDs en estatus 5 (interno) o 9 (externo): ', ISNULL(@invalidIords, '')),
      2048
    );
    THROW 58212, @invalidMsg, 1;
  END;

  BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE o
    SET
      o.ESTSEGU = CASE
        WHEN ISNULL(t.LAB_UBILAB, '') LIKE '%EXTER%'
          OR (
            ISNULL(t.LAB_UBILAB, '') = ''
            AND (
              ISNULL(t.LAB_SUC, '') = ''
              OR ISNULL(t.LAB_TIPOLAB, '') LIKE '%EXTER%'
              OR ISNULL(t.LAB_DESC, '') LIKE '%EXTER%'
            )
          )
        THEN 10
        ELSE 7
      END,
      o.ESTATUS = 2,
      o.FCNRT = CASE
        WHEN ISNULL(t.LAB_UBILAB, '') LIKE '%EXTER%'
          OR (
            ISNULL(t.LAB_UBILAB, '') = ''
            AND (
              ISNULL(t.LAB_SUC, '') = ''
              OR ISNULL(t.LAB_TIPOLAB, '') LIKE '%EXTER%'
              OR ISNULL(t.LAB_DESC, '') LIKE '%EXTER%'
            )
          )
        THEN CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
        ELSE o.FCNRT
      END,
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    INNER JOIN @target t
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    o.IORD,
    o.IDFOL,
    o.SUC,
    o.ESTATUS,
    o.ESTSEGU,
    o.FCNMOD,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR
  FROM dbo.PV_CTR_ORDS o
  INNER JOIN @target t
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD
  ORDER BY o.IORD;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ps_terminar
  @IDFOL NVARCHAR(255),
  @USER NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @idfolNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@IDFOL, '')));

  IF @idfolNorm = ''
    THROW 57110, 'IDFOL es requerido', 1;

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    UPDATE dbo.PV_CTR_FOL_ASVR
    SET ESTA = 'CERRADO_PS',
        FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    WHERE IDFOL = @idfolNorm;

    IF @@ROWCOUNT = 0
      THROW 57111, 'El folio no existe', 1;

    IF OBJECT_ID('dbo.PV_CTR_FOL_FORMTMP', 'U') IS NOT NULL
    BEGIN
      DELETE FROM dbo.PV_CTR_FOL_FORMTMP
      WHERE IDFOL = @idfolNorm;
    END;

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;

    SELECT
      @idfolNorm AS IDFOL,
      'CERRADO_PS' AS ESTA,
      CAST(1 AS BIT) AS OK;
  END TRY
  BEGIN CATCH
    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_ps_folio_create
  @SUC VARCHAR(4),
  @TER NVARCHAR(50) = NULL,
  @OPV NVARCHAR(255),
  @USER NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @sucNorm VARCHAR(4) = UPPER(LTRIM(RTRIM(ISNULL(@SUC, ''))));
  DECLARE @terNorm NVARCHAR(50) = NULLIF(LTRIM(RTRIM(ISNULL(@TER, ''))), '');
  DECLARE @opvNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@OPV, '')));
  DECLARE @idfol NVARCHAR(255);
  DECLARE @nextTra INT;
  DECLARE @fechaProceso DATETIME = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()));
  DECLARE @fechaProcesoDate DATE = CONVERT(DATE, @fechaProceso);

  IF @sucNorm = ''
    THROW 57001, 'SUC es requerido', 1;

  IF @opvNorm = ''
    THROW 57002, 'OPV es requerido', 1;

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    EXEC dbo.sp_pv_next_visible_folio
      @SUC = @sucNorm,
      @TIPO_FOLIO = 'CP',
      @FECHA = @fechaProcesoDate,
      @IDFOL_OUT = @idfol OUTPUT,
      @CONSEC_OUT = @nextTra OUTPUT;

    IF ISNULL(LTRIM(RTRIM(@idfol)), '') = ''
      THROW 57003, 'No se pudo generar folio CP para Pago de Servicios', 1;

    INSERT INTO dbo.PV_CTR_FOL_ASVR (
      IDFOL,
      CLIEN,
      FCN,
      SUC,
      TER,
      TRA,
      OPV,
      ESTA,
      IMPT,
      FPGO,
      IMPP,
      AUT,
      REQF,
      FCNM,
      OPVM,
      IDFOLINICIAL,
      ORIGEN_AUT
    )
    VALUES (
      @idfol,
      1,
      @fechaProceso,
      @sucNorm,
      @terNorm,
      CAST(@nextTra AS NVARCHAR(20)),
      @opvNorm,
      'PENDIENTE',
      0,
      NULL,
      0,
      'PS',
      0,
      @fechaProceso,
      @opvNorm,
      @idfol,
      'CA'
    );

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;

    SELECT
      @idfol AS IDFOL,
      @sucNorm AS SUC,
      CAST(@nextTra AS NVARCHAR(20)) AS TRA,
      @opvNorm AS OPV,
      'PENDIENTE' AS ESTA,
      'CA' AS ORIGEN_AUT;
  END TRY
  BEGIN CATCH
    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_asignar_lote
  @IORDS NVARCHAR(MAX),
  @IDOPV NVARCHAR(100),
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @idopvClean NVARCHAR(100) = UPPER(LTRIM(RTRIM(ISNULL(@IDOPV, ''))));
  IF @idopvClean = ''
    THROW 58300, 'Debe enviar un colaborador vÃ¡lido en @IDOPV', 1;

  DECLARE @ords TABLE (IORD NVARCHAR(255) NOT NULL PRIMARY KEY);
  INSERT INTO @ords (IORD)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(ISNULL(value, ''))))
  FROM STRING_SPLIT(ISNULL(@IORDS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  IF NOT EXISTS (SELECT 1 FROM @ords)
    THROW 58301, 'Debe enviar al menos una ORD en @IORDS', 1;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @target TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY,
    IDFOL NVARCHAR(255) NULL,
    SUC NVARCHAR(10) NULL,
    ESTSEGU FLOAT NULL
  );

  INSERT INTO @target (IORD, IDFOL, SUC, ESTSEGU)
  SELECT
    UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))),
    o.IDFOL,
    o.SUC,
    TRY_CONVERT(FLOAT, o.ESTSEGU)
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  INNER JOIN @ords i
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = i.IORD
  WHERE
    (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF EXISTS (
    SELECT 1
    FROM @ords i
    LEFT JOIN @target t ON t.IORD = i.IORD
    WHERE t.IORD IS NULL
  )
  BEGIN
    DECLARE @missingIords NVARCHAR(2000) = (
      SELECT STRING_AGG(i.IORD, ', ')
      FROM @ords i
      LEFT JOIN @target t ON t.IORD = i.IORD
      WHERE t.IORD IS NULL
    );
    DECLARE @missingMsg NVARCHAR(2048) = LEFT(
      CONCAT('ORD no encontrada o sin acceso por sucursal: ', ISNULL(@missingIords, '')),
      2048
    );
    THROW 58302, @missingMsg, 1;
  END;

  IF EXISTS (
    SELECT 1
    FROM @target t
    WHERE ISNULL(t.ESTSEGU, -1) <> 7
  )
  BEGIN
    DECLARE @invalidIords NVARCHAR(2000) = (
      SELECT STRING_AGG(t.IORD, ', ')
      FROM @target t
      WHERE ISNULL(t.ESTSEGU, -1) <> 7
    );
    DECLARE @invalidMsg NVARCHAR(2048) = LEFT(
      CONCAT('Solo se pueden asignar ORDs en estatus 7 (RECIBIDA A TALLER): ', ISNULL(@invalidIords, '')),
      2048
    );
    THROW 58303, @invalidMsg, 1;
  END;

  BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE o
    SET
      o.ESTSEGU = 8,
      o.ESTATUS = 2,
      o.ASIGN = @idopvClean,
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    INNER JOIN @target t
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD;

    IF COL_LENGTH('dbo.PV_CTR_ORDS', 'FCNAS') IS NOT NULL
    BEGIN
      UPDATE o
      SET o.FCNAS = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
      FROM dbo.PV_CTR_ORDS o
      INNER JOIN @target t
        ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD;
    END;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    o.IORD,
    o.IDFOL,
    o.SUC,
    o.ESTATUS,
    o.ESTSEGU,
    o.ASIGN,
    o.FCNMOD,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR
  FROM dbo.PV_CTR_ORDS o
  INNER JOIN @target t
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD
  ORDER BY o.IORD;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ps_ticket_add_service
  @IDFOL NVARCHAR(255),
  @IDS CHAR(2),
  @USER NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @idfolNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@IDFOL, '')));
  DECLARE @idsNorm CHAR(2) = UPPER(LTRIM(RTRIM(ISNULL(@IDS, ''))));
  DECLARE @descSvr VARCHAR(120);
  DECLARE @existingCount INT = 0;
  DECLARE @firstUpc CHAR(2);
  DECLARE @autRelacion NVARCHAR(40);
  DECLARE @nextSeq INT;
  DECLARE @art NVARCHAR(255);
  DECLARE @ticketObjId INT = OBJECT_ID('dbo.PV_TICKET_LOG');
  DECLARE @hasId BIT = 0;
  DECLARE @idIsIdentity BIT = 0;
  DECLARE @hasPvtat BIT = 0;
  DECLARE @hasUpdatedAt BIT = 0;
  DECLARE @sql NVARCHAR(MAX);
  DECLARE @newTicketId NVARCHAR(36);
  DECLARE @folioFound BIT = 0;
  DECLARE @folioCliente FLOAT = NULL;

  IF @idfolNorm = ''
    THROW 57020, 'IDFOL es requerido', 1;

  IF @idsNorm = ''
    THROW 57021, 'IDS es requerido', 1;

  IF @ticketObjId IS NULL
    THROW 57022, 'No existe tabla PV_TICKET_LOG', 1;

  SELECT TOP 1
    @folioFound = 1,
    @folioCliente = TRY_CONVERT(FLOAT, CLIEN)
  FROM dbo.PV_CTR_FOL_ASVR
  WHERE IDFOL = @idfolNorm;

  IF @folioFound = 0
    THROW 57023, 'El folio PS no existe', 1;

  IF @idsNorm IN ('AD', 'AP', 'CR') AND ISNULL(@folioCliente, 0) <= 1
    THROW 57029, 'Seleccione Cliente', 1;

  SELECT TOP 1 @descSvr = DESSV
  FROM dbo.PV_DAT_PS
  WHERE IDS = @idsNorm;

  IF @descSvr IS NULL
    THROW 57024, 'El servicio IDS no existe en PV_DAT_PS', 1;

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    SELECT @existingCount = COUNT(1)
    FROM dbo.PV_TICKET_LOG WITH (UPDLOCK, HOLDLOCK)
    WHERE IDFOL = @idfolNorm;

    IF @existingCount > 0
    BEGIN
      SELECT TOP 1 @firstUpc = UPPER(LTRIM(RTRIM(ISNULL(UPC, ''))))
      FROM dbo.PV_TICKET_LOG
      WHERE IDFOL = @idfolNorm
      ORDER BY ART;

      IF @firstUpc IS NOT NULL AND @firstUpc <> @idsNorm
        THROW 57025, 'No se permite mezclar tipos de servicio en el mismo folio', 1;
    END
    ELSE
    BEGIN
      IF OBJECT_ID('dbo.PV_TIPO_ESTA', 'U') IS NOT NULL
      BEGIN
        SELECT TOP 1 @autRelacion = LTRIM(RTRIM(ISNULL(RELACION, '')))
        FROM dbo.PV_TIPO_ESTA
        WHERE UPPER(LTRIM(RTRIM(ISNULL(TIPO, '')))) = @idsNorm;
      END

      IF @autRelacion IS NULL OR @autRelacion = ''
        SET @autRelacion = @idsNorm;

      UPDATE dbo.PV_CTR_FOL_ASVR
      SET AUT = @autRelacion,
          FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
      WHERE IDFOL = @idfolNorm;
    END

    IF @idsNorm IN ('DC', 'DG')
    BEGIN
      IF @startedTran = 1 AND @@TRANCOUNT > 0
        COMMIT TRANSACTION;

      SELECT
        CAST(1 AS BIT) AS requiresAuthorizationForm,
        @idfolNorm AS IDFOL,
        @idsNorm AS IDS,
        CAST(NULL AS NVARCHAR(255)) AS ART,
        'Servicio requiere autorizacion previa' AS message;
      RETURN;
    END

    SELECT @nextSeq = ISNULL(COUNT(1), 0) + 1
    FROM dbo.PV_TICKET_LOG
    WHERE IDFOL = @idfolNorm;

    SET @art = CONCAT(CAST(@nextSeq AS NVARCHAR(20)), @idsNorm);

    SELECT
      @hasId = MAX(CASE WHEN UPPER(name) = 'ID' THEN 1 ELSE 0 END),
      @hasPvtat = MAX(CASE WHEN UPPER(name) = 'PVTAT' THEN 1 ELSE 0 END),
      @hasUpdatedAt = MAX(CASE WHEN UPPER(name) = 'UPDATED_AT' THEN 1 ELSE 0 END)
    FROM sys.columns
    WHERE object_id = @ticketObjId;

    IF @hasId = 1
      SET @idIsIdentity = CASE WHEN COLUMNPROPERTY(@ticketObjId, 'ID', 'IsIdentity') = 1 THEN 1 ELSE 0 END;

    SET @sql = N'INSERT INTO dbo.PV_TICKET_LOG ('
      + CASE WHEN @hasId = 1 AND @idIsIdentity = 0 THEN N'ID, ' ELSE N'' END
      + N'IDFOL, UPC, ART, DES, CTD, PVTA, ORD'
      + CASE WHEN @hasPvtat = 1 THEN N', PVTAT' ELSE N'' END
      + CASE WHEN @hasUpdatedAt = 1 THEN N', UPDATED_AT' ELSE N'' END
      + N') VALUES ('
      + CASE WHEN @hasId = 1 AND @idIsIdentity = 0 THEN N'@pID, ' ELSE N'' END
      + N'@pIDFOL, @pUPC, @pART, @pDES, 1, NULL, NULL'
      + CASE WHEN @hasPvtat = 1 THEN N', NULL' ELSE N'' END
      + CASE WHEN @hasUpdatedAt = 1 THEN N', CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))' ELSE N'' END
      + N');';

    SET @newTicketId = CONVERT(NVARCHAR(36), NEWID());

    EXEC sys.sp_executesql
      @sql,
      N'@pID NVARCHAR(36), @pIDFOL NVARCHAR(255), @pUPC CHAR(2), @pART NVARCHAR(255), @pDES VARCHAR(120)',
      @pID = @newTicketId,
      @pIDFOL = @idfolNorm,
      @pUPC = @idsNorm,
      @pART = @art,
      @pDES = @descSvr;

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;

    SELECT
      CAST(0 AS BIT) AS requiresAuthorizationForm,
      @idfolNorm AS IDFOL,
      @idsNorm AS IDS,
      @art AS ART,
      @descSvr AS DES;
  END TRY
  BEGIN CATCH
    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_asignar_laboratorio_lote
  @IORDS NVARCHAR(MAX),
  @LABOR INT,
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  IF ISNULL(@LABOR, 0) <= 0
    THROW 58340, 'Debe enviar un laboratorio vÃ¡lido en @LABOR', 1;

  DECLARE @ords TABLE (IORD NVARCHAR(255) NOT NULL PRIMARY KEY);
  INSERT INTO @ords (IORD)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(ISNULL(value, ''))))
  FROM STRING_SPLIT(ISNULL(@IORDS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  IF NOT EXISTS (SELECT 1 FROM @ords)
    THROW 58341, 'Debe enviar al menos una ORD en @IORDS', 1;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @target TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY,
    IDFOL NVARCHAR(255) NULL,
    SUC NVARCHAR(10) NULL
  );

  INSERT INTO @target (IORD, IDFOL, SUC)
  SELECT
    UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))),
    o.IDFOL,
    o.SUC
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  INNER JOIN @ords i
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = i.IORD
  WHERE
    (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF EXISTS (
    SELECT 1
    FROM @ords i
    LEFT JOIN @target t ON t.IORD = i.IORD
    WHERE t.IORD IS NULL
  )
  BEGIN
    DECLARE @missingIords NVARCHAR(2000) = (
      SELECT STRING_AGG(i.IORD, ', ')
      FROM @ords i
      LEFT JOIN @target t ON t.IORD = i.IORD
      WHERE t.IORD IS NULL
    );
    DECLARE @missingMsg NVARCHAR(2048) = LEFT(
      CONCAT('ORD no encontrada o sin acceso por sucursal: ', ISNULL(@missingIords, '')),
      2048
    );
    THROW 58342, @missingMsg, 1;
  END;

  BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE o
    SET
      o.LABOR = @LABOR,
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    INNER JOIN @target t
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    o.IORD,
    o.IDFOL,
    o.SUC,
    o.LABOR,
    o.ESTATUS,
    o.ESTSEGU,
    o.FCNMOD,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR
  FROM dbo.PV_CTR_ORDS o
  INNER JOIN @target t
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD
  ORDER BY o.IORD;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ps_procesar
  @IDFOL NVARCHAR(255),
  @USER NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @idfolNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@IDFOL, '')));
  DECLARE @serviceType CHAR(2);
  DECLARE @total DECIMAL(18, 4);
  DECLARE @isCashOut BIT = 0;
  DECLARE @hasNonCashForm BIT = 0;

  IF @idfolNorm = ''
    THROW 57070, 'IDFOL es requerido', 1;

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    IF NOT EXISTS (SELECT 1 FROM dbo.PV_TICKET_LOG WHERE IDFOL = @idfolNorm)
      THROW 57071, 'El ticket no contiene renglones', 1;

    IF EXISTS (
      SELECT 1
      FROM dbo.PV_TICKET_LOG
      WHERE IDFOL = @idfolNorm
        AND LTRIM(RTRIM(ISNULL(ORD, ''))) = ''
    )
      THROW 57072, 'Todas las lineas deben tener referencia asignada (ORD)', 1;

    IF EXISTS (
      SELECT 1
      FROM dbo.PV_TICKET_LOG
      WHERE IDFOL = @idfolNorm
        AND TRY_CONVERT(DECIMAL(18,4), PVTA) IS NULL
    )
      THROW 57073, 'Todas las lineas deben tener PVTA capturado', 1;

    SELECT TOP 1 @serviceType = UPPER(LTRIM(RTRIM(ISNULL(UPC, ''))))
    FROM dbo.PV_TICKET_LOG
    WHERE IDFOL = @idfolNorm;

    SELECT @total = ROUND(SUM(
      ISNULL(TRY_CONVERT(DECIMAL(18,4), PVTA), 0)
      * ISNULL(TRY_CONVERT(DECIMAL(18,4), CTD), 0)
    ), 4)
    FROM dbo.PV_TICKET_LOG
    WHERE IDFOL = @idfolNorm;

    IF @total IS NULL OR @total <= 0
      THROW 57074, 'El total del ticket no es valido para procesar', 1;

    IF @serviceType IN ('DG', 'DC')
      SET @isCashOut = 1;

    UPDATE dbo.PV_CTR_FOL_ASVR
    SET
      IMPT = CASE WHEN @isCashOut = 1 THEN (@total * -1) ELSE @total END,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    WHERE IDFOL = @idfolNorm;

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;

    SELECT
      @idfolNorm AS IDFOL,
      @serviceType AS SERVICE_TYPE,
      @total AS TOTAL,
      CASE WHEN @isCashOut = 1 THEN (@total * -1) ELSE @total END AS IMPT,
      CAST(NULL AS NVARCHAR(40)) AS FPGO,
      CAST(1 AS BIT) AS GO_TO_PAGO;
  END TRY
  BEGIN CATCH
    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_trabajo_terminado_lote
  @IORDS NVARCHAR(MAX),
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @ords TABLE (IORD NVARCHAR(255) NOT NULL PRIMARY KEY);
  INSERT INTO @ords (IORD)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(ISNULL(value, ''))))
  FROM STRING_SPLIT(ISNULL(@IORDS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  IF NOT EXISTS (SELECT 1 FROM @ords)
    THROW 58310, 'Debe enviar al menos una ORD en @IORDS', 1;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @target TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY,
    IDFOL NVARCHAR(255) NULL,
    SUC NVARCHAR(10) NULL,
    ESTSEGU FLOAT NULL
  );

  INSERT INTO @target (IORD, IDFOL, SUC, ESTSEGU)
  SELECT
    UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))),
    o.IDFOL,
    o.SUC,
    TRY_CONVERT(FLOAT, o.ESTSEGU)
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  INNER JOIN @ords i
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = i.IORD
  WHERE
    (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF EXISTS (
    SELECT 1
    FROM @ords i
    LEFT JOIN @target t ON t.IORD = i.IORD
    WHERE t.IORD IS NULL
  )
  BEGIN
    DECLARE @missingIords NVARCHAR(2000) = (
      SELECT STRING_AGG(i.IORD, ', ')
      FROM @ords i
      LEFT JOIN @target t ON t.IORD = i.IORD
      WHERE t.IORD IS NULL
    );
    DECLARE @missingMsg NVARCHAR(2048) = LEFT(
      CONCAT('ORD no encontrada o sin acceso por sucursal: ', ISNULL(@missingIords, '')),
      2048
    );
    THROW 58311, @missingMsg, 1;
  END;

  IF EXISTS (
    SELECT 1
    FROM @target t
    WHERE ISNULL(t.ESTSEGU, -1) <> 8
  )
  BEGIN
    DECLARE @invalidIords NVARCHAR(2000) = (
      SELECT STRING_AGG(t.IORD, ', ')
      FROM @target t
      WHERE ISNULL(t.ESTSEGU, -1) <> 8
    );
    DECLARE @invalidMsg NVARCHAR(2048) = LEFT(
      CONCAT('Solo se pueden marcar ORDs en estatus 8 (ASIGNADA): ', ISNULL(@invalidIords, '')),
      2048
    );
    THROW 58312, @invalidMsg, 1;
  END;

  BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE o
    SET
      o.ESTSEGU = 9,
      o.ESTATUS = 2,
      o.FCNTD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    INNER JOIN @target t
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    o.IORD,
    o.IDFOL,
    o.SUC,
    o.ESTATUS,
    o.ESTSEGU,
    o.FCNMOD,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR
  FROM dbo.PV_CTR_ORDS o
  INNER JOIN @target t
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD
  ORDER BY o.IORD;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ps_form_add
  @IDFOL NVARCHAR(255),
  @FORM NVARCHAR(40),
  @IMPP DECIMAL(18, 4),
  @AUT NVARCHAR(255) = NULL,
  @USER NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @idfolNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@IDFOL, '')));
  DECLARE @formNorm NVARCHAR(40) = UPPER(LTRIM(RTRIM(ISNULL(@FORM, ''))));
  DECLARE @autNorm NVARCHAR(255) = NULLIF(LTRIM(RTRIM(ISNULL(@AUT, ''))), '');
  DECLARE @total DECIMAL(18, 4);
  DECLARE @pagado DECIMAL(18, 4);
  DECLARE @restante DECIMAL(18, 4);
  DECLARE @epsilon DECIMAL(18, 6) = 0.0001;
  DECLARE @formTableName NVARCHAR(128) = NULL;
  DECLARE @formTableObjId INT = NULL;
  DECLARE @formNeedsAut BIT = 0;
  DECLARE @hasIdf BIT = 0;
  DECLARE @idfIsIdentity BIT = 0;
  DECLARE @hasAut BIT = 0;
  DECLARE @hasFcn BIT = 0;
  DECLARE @sql NVARCHAR(MAX);
  DECLARE @newFormaId NVARCHAR(36);

  IF @idfolNorm = '' OR @formNorm = ''
    THROW 57090, 'IDFOL y FORM son requeridos', 1;

  IF @IMPP IS NULL OR @IMPP <= 0
    THROW 57091, 'IMPP debe ser mayor a 0', 1;

  IF @formNorm IN ('TARJETA', 'CHEQUE', 'TRANSFERENCIA', 'DEPOSITO 3RO')
    SET @formNeedsAut = 1;

  IF OBJECT_ID('dbo.PV_CTR_FOL_FORMTMP', 'U') IS NOT NULL
  BEGIN
    SET @formTableName = N'dbo.PV_CTR_FOL_FORMTMP';
    SET @formTableObjId = OBJECT_ID('dbo.PV_CTR_FOL_FORMTMP');
  END
  ELSE IF OBJECT_ID('dbo.PV_CTR_FOL_FORM', 'U') IS NOT NULL
  BEGIN
    SET @formTableName = N'dbo.PV_CTR_FOL_FORM';
    SET @formTableObjId = OBJECT_ID('dbo.PV_CTR_FOL_FORM');
  END

  IF @formTableObjId IS NULL
    THROW 57092, 'No existe tabla de formas de pago (PV_CTR_FOL_FORMTMP/PV_CTR_FOL_FORM)', 1;

  IF @formNeedsAut = 1 AND (@autNorm IS NULL OR @autNorm = '')
    THROW 57093, 'La forma seleccionada requiere autorizacion/referencia', 1;

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    SELECT TOP 1 @total = ABS(TRY_CONVERT(DECIMAL(18,4), IMPT))
    FROM dbo.PV_CTR_FOL_ASVR WITH (UPDLOCK, HOLDLOCK)
    WHERE IDFOL = @idfolNorm;

    IF @total IS NULL OR @total <= 0
    BEGIN
      SELECT @total = ROUND(SUM(
        ISNULL(TRY_CONVERT(DECIMAL(18,4), PVTA), 0)
        * ISNULL(TRY_CONVERT(DECIMAL(18,4), CTD), 0)
      ), 4)
      FROM dbo.PV_TICKET_LOG
      WHERE IDFOL = @idfolNorm;
    END

    SET @total = ISNULL(@total, 0);

    SET @sql = N'
      SELECT @pPagado = ROUND(SUM(ISNULL(TRY_CONVERT(DECIMAL(18,4), IMPP), 0)), 4)
      FROM ' + @formTableName + N'
      WHERE IDFOL = @pIDFOL;';
    EXEC sys.sp_executesql
      @sql,
      N'@pIDFOL NVARCHAR(255), @pPagado DECIMAL(18,4) OUTPUT',
      @pIDFOL = @idfolNorm,
      @pPagado = @pagado OUTPUT;

    SET @pagado = ISNULL(@pagado, 0);
    SET @restante = CASE WHEN @total > @pagado THEN ROUND(@total - @pagado, 4) ELSE 0 END;

    IF @formNorm <> 'EFECTIVO' AND @IMPP > (@restante + @epsilon)
      THROW 57094, 'El importe de la forma excede el restante por pagar', 1;

    SELECT
      @hasIdf = MAX(CASE WHEN UPPER(name) = 'IDF' THEN 1 ELSE 0 END),
      @hasAut = MAX(CASE WHEN UPPER(name) = 'AUT' THEN 1 ELSE 0 END),
      @hasFcn = MAX(CASE WHEN UPPER(name) = 'FCN' THEN 1 ELSE 0 END)
    FROM sys.columns
    WHERE object_id = @formTableObjId;

    IF @hasIdf = 1
      SET @idfIsIdentity = CASE WHEN COLUMNPROPERTY(@formTableObjId, 'IDF', 'IsIdentity') = 1 THEN 1 ELSE 0 END;

    SET @sql = N'INSERT INTO ' + @formTableName + N' ('
      + CASE WHEN @hasIdf = 1 AND @idfIsIdentity = 0 THEN N'IDF, ' ELSE N'' END
      + N'IDFOL, FORM, IMPP'
      + CASE WHEN @hasAut = 1 THEN N', AUT' ELSE N'' END
      + CASE WHEN @hasFcn = 1 THEN N', FCN' ELSE N'' END
      + N') VALUES ('
      + CASE WHEN @hasIdf = 1 AND @idfIsIdentity = 0 THEN N'@pIDF, ' ELSE N'' END
      + N'@pIDFOL, @pFORM, @pIMPP'
      + CASE WHEN @hasAut = 1 THEN N', @pAUT' ELSE N'' END
      + CASE WHEN @hasFcn = 1 THEN N', CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))' ELSE N'' END
      + N');';

    SET @newFormaId = CONVERT(NVARCHAR(36), NEWID());

    EXEC sys.sp_executesql
      @sql,
      N'@pIDF NVARCHAR(36), @pIDFOL NVARCHAR(255), @pFORM NVARCHAR(40), @pIMPP DECIMAL(18,4), @pAUT NVARCHAR(255)',
      @pIDF = @newFormaId,
      @pIDFOL = @idfolNorm,
      @pFORM = @formNorm,
      @pIMPP = @IMPP,
      @pAUT = @autNorm;

    SET @sql = N'
      SELECT @pPagado = ROUND(SUM(ISNULL(TRY_CONVERT(DECIMAL(18,4), IMPP), 0)), 4)
      FROM ' + @formTableName + N'
      WHERE IDFOL = @pIDFOL;';
    EXEC sys.sp_executesql
      @sql,
      N'@pIDFOL NVARCHAR(255), @pPagado DECIMAL(18,4) OUTPUT',
      @pIDFOL = @idfolNorm,
      @pPagado = @pagado OUTPUT;

    SET @pagado = ISNULL(@pagado, 0);

    UPDATE dbo.PV_CTR_FOL_ASVR
    SET
      ESTA = CASE WHEN @pagado + @epsilon >= @total AND @total > 0 THEN 'PAGADO' ELSE ESTA END,
      IMPP = @pagado,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    WHERE IDFOL = @idfolNorm;

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;

    EXEC dbo.sp_ps_form_summary @IDFOL = @idfolNorm;
  END TRY
  BEGIN CATCH
    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_regresar_incidencia_lote
  @IORDS NVARCHAR(MAX),
  @TIPOM INT,
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  IF ISNULL(@TIPOM, 0) <= 0
    THROW 58320, 'Debe enviar un motivo valido en @TIPOM', 1;

  IF NOT EXISTS (
    SELECT 1
    FROM dbo.DAT_ORD_TMOV
    WHERE TRY_CONVERT(INT, IDT) = @TIPOM
  )
    THROW 58321, 'El motivo de incidencia enviado no existe en DAT_ORD_TMOV', 1;

  DECLARE @ords TABLE (IORD NVARCHAR(255) NOT NULL PRIMARY KEY);
  INSERT INTO @ords (IORD)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(ISNULL(value, ''))))
  FROM STRING_SPLIT(ISNULL(@IORDS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  IF NOT EXISTS (SELECT 1 FROM @ords)
    THROW 58322, 'Debe enviar al menos una ORD en @IORDS', 1;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @target TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY,
    IDFOL NVARCHAR(255) NULL,
    SUC NVARCHAR(10) NULL,
    ESTSEGU FLOAT NULL,
    ASIGN NVARCHAR(100) NULL
  );

  INSERT INTO @target (IORD, IDFOL, SUC, ESTSEGU, ASIGN)
  SELECT
    UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))),
    o.IDFOL,
    o.SUC,
    TRY_CONVERT(FLOAT, o.ESTSEGU),
    LTRIM(RTRIM(ISNULL(CAST(o.ASIGN AS NVARCHAR(100)), '')))
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  INNER JOIN @ords i
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = i.IORD
  WHERE
    (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF EXISTS (
    SELECT 1
    FROM @ords i
    LEFT JOIN @target t ON t.IORD = i.IORD
    WHERE t.IORD IS NULL
  )
  BEGIN
    DECLARE @missingIords NVARCHAR(2000) = (
      SELECT STRING_AGG(i.IORD, ', ')
      FROM @ords i
      LEFT JOIN @target t ON t.IORD = i.IORD
      WHERE t.IORD IS NULL
    );
    DECLARE @missingMsg NVARCHAR(2048) = LEFT(
      CONCAT('ORD no encontrada o sin acceso por sucursal: ', ISNULL(@missingIords, '')),
      2048
    );
    THROW 58323, @missingMsg, 1;
  END;

  IF EXISTS (
    SELECT 1
    FROM @target t
    WHERE ISNULL(t.ESTSEGU, -1) <> 8
  )
  BEGIN
    DECLARE @invalidIords NVARCHAR(2000) = (
      SELECT STRING_AGG(t.IORD, ', ')
      FROM @target t
      WHERE ISNULL(t.ESTSEGU, -1) <> 8
    );
    DECLARE @invalidMsg NVARCHAR(2048) = LEFT(
      CONCAT('Solo se pueden registrar incidencias para ORDs en estatus 8 (ASIGNADA): ', ISNULL(@invalidIords, '')),
      2048
    );
    THROW 58324, @invalidMsg, 1;
  END;

  IF EXISTS (
    SELECT 1
    FROM @target t
    WHERE LTRIM(RTRIM(ISNULL(t.ASIGN, ''))) = ''
  )
  BEGIN
    DECLARE @invalidAsignIords NVARCHAR(2000) = (
      SELECT STRING_AGG(t.IORD, ', ')
      FROM @target t
      WHERE LTRIM(RTRIM(ISNULL(t.ASIGN, ''))) = ''
    );
    DECLARE @invalidAsignMsg NVARCHAR(2048) = LEFT(
      CONCAT('Las siguientes ORDs deben tener colaborador asignado para registrar incidencia: ', ISNULL(@invalidAsignIords, '')),
      2048
    );
    THROW 58325, @invalidAsignMsg, 1;
  END;

  BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE o
    SET
      o.ESTSEGU = 9,
      o.ESTATUS = 2,
      o.TIPOM = @TIPOM,
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    INNER JOIN @target t
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    o.IORD,
    o.IDFOL,
    o.SUC,
    o.ESTATUS,
    o.ESTSEGU,
    o.TIPOM,
    o.FCNMOD,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR
  FROM dbo.PV_CTR_ORDS o
  INNER JOIN @target t
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD
  ORDER BY o.IORD;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ordenes_trabajo_regresar_tienda_lote
  @IORDS NVARCHAR(MAX),
  @USER NVARCHAR(255) = NULL,
  @IP NVARCHAR(100) = NULL,
  @IS_ADMIN BIT = 0,
  @ALLOWED_SUCS NVARCHAR(MAX) = NULL,
  @SUC NVARCHAR(10) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @ords TABLE (IORD NVARCHAR(255) NOT NULL PRIMARY KEY);
  INSERT INTO @ords (IORD)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(ISNULL(value, ''))))
  FROM STRING_SPLIT(ISNULL(@IORDS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  IF NOT EXISTS (SELECT 1 FROM @ords)
    THROW 58330, 'Debe enviar al menos una ORD en @IORDS', 1;

  DECLARE @allowed TABLE (SUC NVARCHAR(10) PRIMARY KEY);
  INSERT INTO @allowed (SUC)
  SELECT DISTINCT UPPER(LTRIM(RTRIM(value)))
  FROM STRING_SPLIT(ISNULL(@ALLOWED_SUCS, ''), ',')
  WHERE LTRIM(RTRIM(ISNULL(value, ''))) <> '';

  DECLARE @target TABLE (
    IORD NVARCHAR(255) NOT NULL PRIMARY KEY,
    IDFOL NVARCHAR(255) NULL,
    SUC NVARCHAR(10) NULL,
    ESTSEGU FLOAT NULL,
    TIPOM INT NULL
  );

  INSERT INTO @target (IORD, IDFOL, SUC, ESTSEGU, TIPOM)
  SELECT
    UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))),
    o.IDFOL,
    o.SUC,
    TRY_CONVERT(FLOAT, o.ESTSEGU),
    TRY_CONVERT(INT, o.TIPOM)
  FROM dbo.PV_CTR_ORDS o
  LEFT JOIN dbo.DAT_LAB lab
    ON TRY_CONVERT(INT, lab.ID) = TRY_CONVERT(INT, o.LABOR)
  INNER JOIN @ords i
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = i.IORD
  WHERE
    (
      @SUC IS NULL
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) = UPPER(@SUC)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) = UPPER(@SUC)
    )
    AND (
      @IS_ADMIN = 1
      OR NOT EXISTS (SELECT 1 FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(o.SUC, '')))) IN (SELECT SUC FROM @allowed)
      OR UPPER(LTRIM(RTRIM(ISNULL(lab.SUC, '')))) IN (SELECT SUC FROM @allowed)
    );

  IF EXISTS (
    SELECT 1
    FROM @ords i
    LEFT JOIN @target t ON t.IORD = i.IORD
    WHERE t.IORD IS NULL
  )
  BEGIN
    DECLARE @missingIords NVARCHAR(2000) = (
      SELECT STRING_AGG(i.IORD, ', ')
      FROM @ords i
      LEFT JOIN @target t ON t.IORD = i.IORD
      WHERE t.IORD IS NULL
    );
    DECLARE @missingMsg NVARCHAR(2048) = LEFT(
      CONCAT('ORD no encontrada o sin acceso por sucursal: ', ISNULL(@missingIords, '')),
      2048
    );
    THROW 58331, @missingMsg, 1;
  END;

  IF EXISTS (
    SELECT 1
    FROM @target t
    WHERE ISNULL(t.ESTSEGU, -1) <> 9
  )
  BEGIN
    DECLARE @invalidIords NVARCHAR(2000) = (
      SELECT STRING_AGG(t.IORD, ', ')
      FROM @target t
      WHERE ISNULL(t.ESTSEGU, -1) <> 9
    );
    DECLARE @invalidMsg NVARCHAR(2048) = LEFT(
      CONCAT('Solo se pueden recibir en tienda ORDs en estatus 9: ', ISNULL(@invalidIords, '')),
      2048
    );
    THROW 58332, @invalidMsg, 1;
  END;

  BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE o
    SET
      o.ESTSEGU = CASE
        WHEN
          NULLIF(LTRIM(RTRIM(ISNULL(CAST(o.REEORD AS NVARCHAR(255)), ''))), '') IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM dbo.PV_CTR_ORDS_FLUJO_HIST h
            WHERE UPPER(LTRIM(RTRIM(ISNULL(h.IORD, '')))) =
                  UPPER(LTRIM(RTRIM(ISNULL(CAST(o.REEORD AS NVARCHAR(255)), ''))))
              AND TRY_CONVERT(FLOAT, h.ESTSEGU) = 11
          ) THEN 10
        WHEN NULLIF(LTRIM(RTRIM(ISNULL(CAST(o.REEORD AS NVARCHAR(255)), ''))), '') IS NOT NULL
          AND TRY_CONVERT(INT, o.TIPOM) = 2 THEN 9.2
        WHEN NULLIF(LTRIM(RTRIM(ISNULL(CAST(o.REEORD AS NVARCHAR(255)), ''))), '') IS NOT NULL THEN 10
        WHEN TRY_CONVERT(INT, o.TIPOM) = 1 THEN 9.1
        WHEN TRY_CONVERT(INT, o.TIPOM) = 2 THEN 9.2
        ELSE 10
      END,
      o.ESTATUS = 2,
      o.FCNRT = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
      o.FCNMOD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.PV_CTR_ORDS o
    INNER JOIN @target t
      ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH;

  SELECT
    o.IORD,
    o.IDFOL,
    o.SUC,
    o.ESTATUS,
    o.ESTSEGU,
    o.TIPOM,
    o.FCNMOD,
    @USER AS USER_ACTOR,
    @IP AS IP_ACTOR
  FROM dbo.PV_CTR_ORDS o
  INNER JOIN @target t
    ON UPPER(LTRIM(RTRIM(ISNULL(o.IORD, '')))) = t.IORD
  ORDER BY o.IORD;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ps_folio_set_cliente
  @IDFOL NVARCHAR(255),
  @CLIEN FLOAT,
  @USER NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @idfolNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@IDFOL, '')));
  DECLARE @clienNorm FLOAT = TRY_CONVERT(FLOAT, @CLIEN);
  DECLARE @userNorm NVARCHAR(255) = NULLIF(LTRIM(RTRIM(ISNULL(@USER, ''))), '');

  IF @idfolNorm = ''
    THROW 57012, 'IDFOL es requerido', 1;

  IF @clienNorm IS NULL OR @clienNorm <= 0
    THROW 57013, 'CLIEN debe ser un número positivo', 1;

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    IF NOT EXISTS (
      SELECT 1
      FROM dbo.PV_CTR_FOL_ASVR WITH (UPDLOCK, HOLDLOCK)
      WHERE IDFOL = @idfolNorm
    )
      THROW 57014, 'El folio PS no existe', 1;

    IF NOT EXISTS (
      SELECT 1
      FROM dbo.FACT_CLIENT_SHP
      WHERE TRY_CONVERT(FLOAT, IDC) = @clienNorm
    )
      THROW 57015, 'El cliente no existe', 1;

    IF EXISTS (
      SELECT 1
      FROM dbo.PV_TICKET_LOG
      WHERE IDFOL = @idfolNorm
    )
      THROW 57016, 'No se puede cambiar cliente cuando el ticket ya tiene líneas', 1;

    UPDATE dbo.PV_CTR_FOL_ASVR
    SET
      CLIEN = @clienNorm,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
      OPVM = COALESCE(@userNorm, OPVM)
    WHERE IDFOL = @idfolNorm;

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;

    SELECT TOP 1
      a.IDFOL,
      TRY_CONVERT(FLOAT, a.CLIEN) AS CLIEN,
      c.RazonSocialReceptor
    FROM dbo.PV_CTR_FOL_ASVR a
    LEFT JOIN dbo.FACT_CLIENT_SHP c
      ON TRY_CONVERT(FLOAT, c.IDC) = TRY_CONVERT(FLOAT, a.CLIEN)
    WHERE a.IDFOL = @idfolNorm;
  END TRY
  BEGIN CATCH
    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_pv_ctr_ords_generate_iord
  @SUC NVARCHAR(10),
  @FCN DATETIME = NULL,
  @IORD_OUT NVARCHAR(255) OUTPUT
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @sucNorm NVARCHAR(10) = UPPER(LTRIM(RTRIM(ISNULL(@SUC, ''))));
  DECLARE @fcnNorm DATETIME = ISNULL(@FCN, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())));
  DECLARE @fcnDate DATE = CAST(@fcnNorm AS DATE);
  DECLARE @serie INT;
  DECLARE @serieTxt NVARCHAR(10);
  DECLARE @prefix NVARCHAR(30);
  DECLARE @next INT;
  DECLARE @lockResult INT;
  DECLARE @lockResource NVARCHAR(200);
  DECLARE @used TABLE (IORD NVARCHAR(255) NOT NULL);

  IF @sucNorm = ''
    THROW 50064, 'SUC es requerida.', 1;

  SET @serie = DATEDIFF(DAY, CONVERT(DATE, '19900101'), @fcnDate);
  IF @serie < 0
    THROW 50065, 'La fecha de serie no es valida para generar IORD.', 1;

  SET @serieTxt = RIGHT(REPLICATE('0', 5) + CAST(@serie AS NVARCHAR(10)), 5);
  SET @prefix = @sucNorm + @serieTxt;
  SET @lockResource = CONCAT('PV_CTR_ORDS_IORD_', @sucNorm, '_', CONVERT(VARCHAR(8), @fcnDate, 112));

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    EXEC @lockResult = sp_getapplock
      @Resource = @lockResource,
      @LockMode = 'Exclusive',
      @LockOwner = 'Transaction',
      @LockTimeout = 15000;

    IF @lockResult < 0
      THROW 50066, 'No se pudo adquirir bloqueo para generar IORD.', 1;

    INSERT INTO @used (IORD)
    SELECT LTRIM(RTRIM(ISNULL(h.IORD, '')))
    FROM dbo.PV_CTR_ORDS h WITH (UPDLOCK, HOLDLOCK)
    WHERE LTRIM(RTRIM(ISNULL(h.IORD, ''))) <> '';

    IF OBJECT_ID('dbo.PV_ORD_CAMBIO_MERMA_TMP', 'U') IS NOT NULL
    BEGIN
      INSERT INTO @used (IORD)
      SELECT LTRIM(RTRIM(ISNULL(t.NVA_IORD, '')))
      FROM dbo.PV_ORD_CAMBIO_MERMA_TMP t WITH (UPDLOCK, HOLDLOCK)
      WHERE LTRIM(RTRIM(ISNULL(t.NVA_IORD, ''))) <> '';
    END;

    SELECT
      @next = ISNULL(MAX(TRY_CONVERT(INT, RIGHT(u.IORD, 4))), 0) + 1
    FROM @used u
    WHERE LEFT(u.IORD, LEN(@prefix)) = @prefix
      AND LEN(u.IORD) = LEN(@prefix) + 4
      AND TRY_CONVERT(INT, RIGHT(u.IORD, 4)) IS NOT NULL;

    IF @next > 9999
      THROW 50067, 'Se alcanzo el maximo consecutivo diario para IORD.', 1;

    SET @IORD_OUT = @prefix + RIGHT(REPLICATE('0', 4) + CAST(@next AS NVARCHAR(10)), 4);

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END

