CREATE OR ALTER PROCEDURE dbo.sp_rec_recepcion_actualizar_datos
  @DOCREC nvarchar(510),
  @TIPO_DOC nvarchar(20)=NULL,
  @FOLIO_DOC nvarchar(100)=NULL,
  @GUIA nvarchar(100)=NULL,
  @PAQUETERIA nvarchar(120)=NULL,
  @OBSERVACIONES nvarchar(1000)=NULL,
  @USR nvarchar(100)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;
  DECLARE @lock int,@resource nvarchar(255)=CONCAT('DAT_REC_DOC_',@DOCREC);
  EXEC @lock=sys.sp_getapplock @Resource=@resource,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=15000;
  IF @lock<0 THROW 51000,'No fue posible bloquear la recepciÃ³n.',1;

  SET @TIPO_DOC=UPPER(NULLIF(LTRIM(RTRIM(ISNULL(@TIPO_DOC,''))),''));
  IF @TIPO_DOC IS NOT NULL AND @TIPO_DOC NOT IN ('FACTURA','NOTA','PENDIENTE','CONSIGNACION')
    THROW 51000,'El tipo de documento no es vÃ¡lido.',1;
  IF @TIPO_DOC IN ('FACTURA','NOTA') AND NULLIF(LTRIM(RTRIM(ISNULL(@FOLIO_DOC,''))),'') IS NULL
    THROW 51000,'Capture el folio de la factura o nota.',1;

  DECLARE @NPED nvarchar(510),@SUC nvarchar(20),@ESTATUS nvarchar(30);
  SELECT @NPED=r.NPED,@SUC=h.SUC,@ESTATUS=r.ESTATUS_REC
  FROM dbo.REC_CTRL_DOC_REC r WITH(UPDLOCK,HOLDLOCK)
  JOIN dbo.REC_CAB_PED h ON h.NPED=r.NPED
  WHERE r.DOCREC=@DOCREC;
  IF @NPED IS NULL THROW 51000,'La recepciÃ³n no existe.',1;
  IF @ESTATUS<>'VALIDADO' THROW 51000,'Solo se pueden editar datos de una recepciÃ³n validada.',1;

  UPDATE dbo.REC_CTRL_DOC_REC
  SET TIPO_DOC=@TIPO_DOC,
      FOLIO_DOC=NULLIF(LTRIM(RTRIM(ISNULL(@FOLIO_DOC,''))),''),
      OBSERVACIONES=NULLIF(LTRIM(RTRIM(ISNULL(@OBSERVACIONES,''))),'')
  WHERE DOCREC=@DOCREC;

  DELETE dbo.REC_GUIA_PED WHERE DOCREC=@DOCREC;
  IF NULLIF(LTRIM(RTRIM(ISNULL(@GUIA,''))),'') IS NOT NULL
    INSERT dbo.REC_GUIA_PED(DOCREC,GUIA,PAQUETERIA,USR)
    VALUES(@DOCREC,LTRIM(RTRIM(@GUIA)),NULLIF(LTRIM(RTRIM(ISNULL(@PAQUETERIA,''))),''),@USR);

  INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
  SELECT IDUSUARIO,'ACTUALIZAR_DATOS_DOCUMENTALES','DAT_REC','REC_CTRL_DOC_REC',@DOCREC,@SUC,
    CONCAT('{"nped":"',STRING_ESCAPE(@NPED,'json'),'"}'),SYSUTCDATETIME()
  FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
  COMMIT;
END;

CREATE OR ALTER PROCEDURE dbo.sp_rec_recepcion_actualizar_costo
  @DOCREC nvarchar(510),@IDREC nvarchar(510),@COSTO money,@USR nvarchar(100)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;
  DECLARE @lock int,@resource nvarchar(255)=CONCAT('DAT_REC_DOC_',@DOCREC);
  EXEC @lock=sys.sp_getapplock @Resource=@resource,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=15000;
  IF @lock<0 THROW 51000,'No fue posible bloquear la recepciÃ³n.',1;
  IF @COSTO IS NULL OR @COSTO<0 THROW 51000,'El costo no es vÃ¡lido.',1;

  DECLARE @NPED nvarchar(510),@SUC nvarchar(20),@ESTATUS nvarchar(30),@IDPED nvarchar(510),@ANTERIOR money;
  SELECT @NPED=r.NPED,@SUC=c.SUC,@ESTATUS=r.ESTATUS_REC
  FROM dbo.REC_CTRL_DOC_REC r WITH(UPDLOCK,HOLDLOCK)
  JOIN dbo.REC_CAB_PED c ON c.NPED=r.NPED WHERE r.DOCREC=@DOCREC;
  IF @NPED IS NULL THROW 51000,'La recepciÃ³n no existe.',1;
  IF @ESTATUS<>'VALIDADO' THROW 51000,'Solo se puede editar el costo de una recepciÃ³n validada.',1;
  SELECT @IDPED=h.IDPED,@ANTERIOR=d.CTO
  FROM dbo.REC_CTO_HIST h WITH(UPDLOCK,HOLDLOCK)
  LEFT JOIN dbo.REC_DET_PED d ON d.IDPED=h.IDPED
  WHERE h.DOCREC=@DOCREC AND h.IDREC=@IDREC;
  IF @IDPED IS NULL THROW 51000,'El artÃ­culo no pertenece a una posiciÃ³n de la O.C.',1;

  UPDATE dbo.REC_DET_PED SET CTO=@COSTO WHERE IDPED=@IDPED AND NPED=@NPED;
  UPDATE dbo.REC_CTO_HIST
  SET CTDVTA=@COSTO*ISNULL(CTD_ACEP,CTD)
  WHERE DOCREC=@DOCREC AND IDREC=@IDREC;
  UPDATE dbo.REC_CTRL_DOC_REC
  SET IMPT=(SELECT SUM(ISNULL(CTDVTA,0)) FROM dbo.REC_CTO_HIST WHERE DOCREC=@DOCREC)
  WHERE DOCREC=@DOCREC;
  UPDATE dbo.REC_CAB_PED
  SET IMPP=(SELECT SUM(ISNULL(CTDPED,0)*ISNULL(CTO,0)) FROM dbo.REC_DET_PED WHERE NPED=@NPED AND ISNULL(BLOQ,0)<>-1)
  WHERE NPED=@NPED;

  INSERT dbo.AUDIT_LOG(IDUSUARIO,ACTION,MODULO,ENTIDAD,ENTIDAD_ID,SUC,METADATA_JSON,FCNR)
  SELECT IDUSUARIO,'ACTUALIZAR_COSTO','DAT_REC','REC_CTO_HIST',@IDREC,@SUC,
    CONCAT('{"docrec":"',STRING_ESCAPE(@DOCREC,'json'),'","anterior":',COALESCE(CONVERT(varchar(50),@ANTERIOR),'null'),',"nuevo":',CONVERT(varchar(50),@COSTO),'}'),SYSUTCDATETIME()
  FROM dbo.USUARIO WHERE UPPER(USERNAME)=UPPER(@USR);
  COMMIT;
END;

CREATE OR ALTER PROCEDURE dbo.sp_rec_recepcion_devolver_sucursal
  @DOCREC nvarchar(510),
  @USR nvarchar(100),
  @MOTIVO nvarchar(1000)
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;
  BEGIN TRANSACTION;

  DECLARE @lock int, @resource nvarchar(255) = CONCAT('DAT_REC_DOC_', @DOCREC);
  EXEC @lock = sys.sp_getapplock
    @Resource = @resource,
    @LockMode = 'Exclusive',
    @LockOwner = 'Transaction',
    @LockTimeout = 15000;
  IF @lock < 0 THROW 51000, 'No fue posible bloquear la recepciÃ³n.', 1;
  IF NULLIF(LTRIM(RTRIM(ISNULL(@MOTIVO, ''))), '') IS NULL
    THROW 51000, 'Capture el motivo de devoluciÃ³n.', 1;

  DECLARE
    @NPED nvarchar(510),
    @SUC nvarchar(20),
    @ESTATUS nvarchar(30),
    @TIPO_REC nvarchar(20),
    @TIPO_DOC nvarchar(20),
    @FOLIO nvarchar(100),
    @OBS nvarchar(1000),
    @USR_REC nvarchar(100),
    @GUIA nvarchar(100),
    @PAQUETERIA nvarchar(120);

  SELECT
    @NPED = r.NPED,
    @SUC = h.SUC,
    @ESTATUS = r.ESTATUS_REC,
    @TIPO_REC = r.TIPO_RECEPCION,
    @TIPO_DOC = r.TIPO_DOC,
    @FOLIO = r.FOLIO_DOC,
    @OBS = r.OBSERVACIONES,
    @USR_REC = r.USR_RECEPCION
  FROM dbo.REC_CTRL_DOC_REC r WITH (UPDLOCK, HOLDLOCK)
  JOIN dbo.REC_CAB_PED h WITH (UPDLOCK, HOLDLOCK) ON h.NPED = r.NPED
  WHERE r.DOCREC = @DOCREC;

  IF @NPED IS NULL THROW 51000, 'La recepciÃ³n no existe.', 1;
  IF @ESTATUS NOT IN ('VALIDADO', 'PENDIENTE_AUTORIZACION', 'RECHAZADO')
    THROW 51000, 'Solo se puede devolver una recepciÃ³n pendiente de revisiÃ³n o rechazada.', 1;
  IF EXISTS (SELECT 1 FROM dbo.DAT_MB51 WHERE DOCP = @DOCREC)
    THROW 51000, 'La recepciÃ³n ya tiene movimientos de inventario.', 1;

  SELECT TOP 1 @GUIA = GUIA, @PAQUETERIA = PAQUETERIA
  FROM dbo.REC_GUIA_PED
  WHERE DOCREC = @DOCREC
  ORDER BY IDGUIA;

  MERGE dbo.REC_BORRADOR_REC WITH (HOLDLOCK) AS target
  USING (SELECT @NPED NPED) source ON source.NPED = target.NPED
  WHEN MATCHED THEN UPDATE SET
    SUC = @SUC,
    USR = COALESCE(NULLIF(@USR_REC, ''), @USR),
    TIPO_RECEPCION = @TIPO_REC,
    TIPO_DOC = @TIPO_DOC,
    FOLIO_DOC = @FOLIO,
    GUIA = @GUIA,
    PAQUETERIA = @PAQUETERIA,
    OBSERVACIONES = @OBS,
    FCNM = dbo.fn_ioe_business_datetime(SYSUTCDATETIME())
  WHEN NOT MATCHED THEN
    INSERT (NPED, SUC, USR, TIPO_RECEPCION, TIPO_DOC, FOLIO_DOC, GUIA, PAQUETERIA, OBSERVACIONES, FCNM)
    VALUES (@NPED, @SUC, COALESCE(NULLIF(@USR_REC, ''), @USR), @TIPO_REC, @TIPO_DOC, @FOLIO, @GUIA, @PAQUETERIA, @OBS, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()));

  DELETE dbo.REC_BORRADOR_REC_DET WHERE NPED = @NPED;
  INSERT dbo.REC_BORRADOR_REC_DET (NPED, IDPED, ART, CTD_REC, CTD_ACEP, ESTATUS)
  SELECT
    @NPED,
    h.IDPED,
    h.ART,
    CASE WHEN @ESTATUS = 'RECHAZADO' THEN 0 ELSE ISNULL(h.CTD, 0) END,
    CASE WHEN @ESTATUS = 'RECHAZADO' THEN 0 ELSE ISNULL(h.CTD_ACEP, h.CTD) END,
    CASE WHEN @ESTATUS = 'RECHAZADO' THEN NULL
      WHEN h.CALIDAD_ESTATUS IN ('APROBADO', 'RECHAZADO', 'NO_APLICA') THEN h.CALIDAD_ESTATUS
      ELSE 'APROBADO' END
  FROM dbo.REC_CTO_HIST h
  WHERE h.DOCREC = @DOCREC AND h.IDPED IS NOT NULL;

  UPDATE dbo.REC_CTRL_DOC_REC
  SET
    ESTATUS_REC = 'DEVUELTO',
    OBSERVACIONES = LEFT(
      CONCAT(
        ISNULL(OBSERVACIONES, ''),
        CASE WHEN NULLIF(OBSERVACIONES, '') IS NULL THEN '' ELSE CHAR(13) + CHAR(10) END,
        'DEVUELTO: ',
        LTRIM(RTRIM(@MOTIVO))
      ),
      1000
    )
  WHERE DOCREC = @DOCREC;

  UPDATE dbo.REC_CAB_PED
  SET ESTATUS = 'PROCESADO', FCNR = NULL
  WHERE NPED = @NPED;

  INSERT dbo.AUDIT_LOG (
    IDUSUARIO, ACTION, MODULO, ENTIDAD, ENTIDAD_ID, SUC, METADATA_JSON, FCNR
  )
  SELECT
    IDUSUARIO,
    'DEVOLVER_A_SUCURSAL',
    'DAT_REC',
    'REC_CTRL_DOC_REC',
    @DOCREC,
    @SUC,
    CONCAT(
      '{"nped":"', STRING_ESCAPE(@NPED, 'json'),
      '","estatusAnterior":"', STRING_ESCAPE(@ESTATUS, 'json'),
      '","motivo":"', STRING_ESCAPE(LTRIM(RTRIM(@MOTIVO)), 'json'), '"}'
    ),
    SYSUTCDATETIME()
  FROM dbo.USUARIO
  WHERE UPPER(USERNAME) = UPPER(@USR);

  COMMIT;
  SELECT @DOCREC DOCREC, @NPED NPED, 'DEVUELTO' ESTATUS_REC;
END;

CREATE OR ALTER PROCEDURE dbo.sp_merma_crear
  @SUC NVARCHAR(50),
  @USER NVARCHAR(100),
  @AREAM INT = NULL,
  @TXT NVARCHAR(200) = NULL
AS
BEGIN
  SET NOCOUNT ON;

  IF LTRIM(RTRIM(ISNULL(@SUC, ''))) = ''
    THROW 59001, 'SUC es requerida.', 1;
  IF LTRIM(RTRIM(ISNULL(@USER, ''))) = ''
    THROW 59002, 'USER es requerido.', 1;

  DECLARE @nextDoc BIGINT;

  SELECT @nextDoc = ISNULL(MAX(TRY_CONVERT(BIGINT, DOCMER)), 20000000) + 1
  FROM dbo.DOC_CTRL_MERMA
  WHERE TRY_CONVERT(BIGINT, DOCMER) IS NOT NULL;

  DECLARE @docmer NVARCHAR(50) = CONVERT(NVARCHAR(50), @nextDoc);

  INSERT INTO dbo.DOC_CTRL_MERMA
    (DOCMER, [USER], FCND, FCNC, ESTATS, ID_ESTATUS, NARTS, TOTAL, SUC, TXT, AREAM)
  VALUES
    (@docmer, @USER, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())), NULL, 'ABIERTO', 1, 0, 0, @SUC, @TXT, @AREAM);

  SELECT DOCMER, SUC, [USER], FCND, FCNC, ESTATS, ID_ESTATUS, NARTS, TOTAL, TXT, AREAM
  FROM dbo.DOC_CTRL_MERMA
  WHERE DOCMER = @docmer;
END;

CREATE OR ALTER PROCEDURE dbo.sp_merma_agregar_articulo
  @DOCMER NVARCHAR(50),
  @ART NVARCHAR(100),
  @CTD FLOAT,
  @MOT_M INT,
  @RESP_M NVARCHAR(150) = NULL,
  @OBS_M NVARCHAR(MAX) = NULL,
  @USER NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON;

  IF LTRIM(RTRIM(ISNULL(@DOCMER, ''))) = ''
    THROW 59010, 'DOCMER es requerido.', 1;
  IF LTRIM(RTRIM(ISNULL(@ART, ''))) = ''
    THROW 59011, 'ART es requerido.', 1;
  IF ISNULL(@CTD, 0) <= 0
    THROW 59012, 'CTD debe ser mayor a 0.', 1;

  DECLARE @docSuc NVARCHAR(50);
  DECLARE @docEst INT;

  SELECT TOP 1
    @docSuc = LTRIM(RTRIM(ISNULL(SUC, ''))),
    @docEst = ISNULL(ID_ESTATUS, CASE
      WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) = 'ABIERTO' THEN 1
      WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) IN ('REVISION', 'REVISAR') THEN 4
      ELSE -1
    END)
  FROM dbo.DOC_CTRL_MERMA
  WHERE DOCMER = @DOCMER;

  IF @docSuc IS NULL
    THROW 59013, 'Documento no existe.', 1;

  IF @docEst NOT IN (1, 4)
    THROW 59014, 'Solo se pueden agregar articulos en ABIERTO o REVISAR.', 1;

  IF NOT EXISTS (SELECT 1 FROM dbo.MOT_MERMA WHERE ID = @MOT_M)
    THROW 59015, 'MOT_M no existe en catalogo de motivos.', 1;

  IF EXISTS (
    SELECT 1
    FROM dbo.DET_ART_MERMA d
    WHERE d.DOCMER = @DOCMER
      AND LTRIM(RTRIM(ISNULL(d.ART, ''))) = LTRIM(RTRIM(ISNULL(@ART, '')))
      AND ISNULL(d.MOT_M, 0) = ISNULL(@MOT_M, 0)
      AND ISNULL(d.BLOQ, 0) <> -1
  )
    THROW 59016, 'No se permite articulo duplicado con el mismo motivo en el mismo documento.', 1;

  IF NOT EXISTS (
    SELECT 1
    FROM dbo.DAT_ART a
    WHERE LTRIM(RTRIM(ISNULL(a.SUC, ''))) = @docSuc
      AND LTRIM(RTRIM(ISNULL(a.ART, ''))) = LTRIM(RTRIM(ISNULL(@ART, '')))
  )
    THROW 59017, 'Articulo no existe para la sucursal del documento.', 1;

  DECLARE @cto DECIMAL(18,4);
  DECLARE @mtv NVARCHAR(510);

  SELECT TOP 1 @cto = TRY_CONVERT(DECIMAL(18,4), ISNULL(a.CTOP, 0))
  FROM dbo.DAT_ART a
  WHERE LTRIM(RTRIM(ISNULL(a.SUC, ''))) = @docSuc
    AND LTRIM(RTRIM(ISNULL(a.ART, ''))) = LTRIM(RTRIM(ISNULL(@ART, '')));

  SELECT TOP 1 @mtv = [DESC]
  FROM dbo.MOT_MERMA
  WHERE ID = @MOT_M;

  DECLARE @idpd NVARCHAR(510) = CONVERT(NVARCHAR(36), NEWID());

  INSERT INTO dbo.DET_ART_MERMA
    (SEL, IDPD, DOCMER, ART, CTD, BLOQ, MTVMER, REV, DOCREV, SUC, CTO, MOT_M, RESP_M, OBS_M)
  VALUES
    (0, @idpd, @DOCMER, @ART, @CTD, 0, @mtv, 0, NULL, @docSuc, ISNULL(@cto, 0), @MOT_M, @RESP_M, @OBS_M);

  UPDATE d
  SET d.NARTS = agg.narts,
      d.TOTAL = agg.total,
      d.FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
  FROM dbo.DOC_CTRL_MERMA d
  CROSS APPLY (
    SELECT
      SUM(CASE WHEN ISNULL(x.BLOQ, 0) = -1 THEN 0 ELSE ISNULL(x.CTD, 0) END) AS narts,
      SUM(CASE WHEN ISNULL(x.BLOQ, 0) = -1 THEN 0 ELSE ISNULL(x.CTD, 0) * ISNULL(x.CTO, 0) END) AS total
    FROM dbo.DET_ART_MERMA x
    WHERE x.DOCMER = d.DOCMER
  ) agg
  WHERE d.DOCMER = @DOCMER;

  SELECT TOP 1 *
  FROM dbo.DET_ART_MERMA
  WHERE IDPD = @idpd;
END;

CREATE OR ALTER PROCEDURE dbo.sp_merma_solicitar_autorizacion
  @DOCMER NVARCHAR(50),
  @USER NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @docEst INT;

  SELECT TOP 1 @docEst = ISNULL(ID_ESTATUS, CASE
      WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) = 'ABIERTO' THEN 1
      WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) IN ('REVISION', 'REVISAR') THEN 4
      ELSE -1
    END)
  FROM dbo.DOC_CTRL_MERMA
  WHERE DOCMER = @DOCMER;

  IF @docEst IS NULL
    THROW 59020, 'Documento no existe.', 1;

  IF @docEst NOT IN (1, 4)
    THROW 59021, 'Solo se puede solicitar autorizacion desde ABIERTO o REVISAR.', 1;

  IF NOT EXISTS (
    SELECT 1
    FROM dbo.DET_ART_MERMA d
    WHERE d.DOCMER = @DOCMER
      AND ISNULL(d.BLOQ, 0) <> -1
  )
    THROW 59022, 'Documento sin articulos activos.', 1;

  IF EXISTS (
    SELECT 1
    FROM dbo.DET_ART_MERMA d
    WHERE d.DOCMER = @DOCMER
      AND ISNULL(d.BLOQ, 0) <> -1
      AND (ISNULL(d.CTD, 0) <= 0 OR d.MOT_M IS NULL)
  )
    THROW 59023, 'Todos los articulos deben tener cantidad > 0 y motivo.', 1;

  IF EXISTS (
    SELECT 1
    FROM dbo.DET_ART_MERMA d
    JOIN dbo.MOT_MERMA m ON m.ID = d.MOT_M
    WHERE d.DOCMER = @DOCMER
      AND ISNULL(d.BLOQ, 0) <> -1
      AND ISNULL(m.REQUIERE_EVIDENCIA, 0) = 1
      AND NOT EXISTS (
        SELECT 1 FROM dbo.MERMA_EVIDENCIA e
        WHERE LTRIM(RTRIM(ISNULL(e.IDPD, ''))) = LTRIM(RTRIM(ISNULL(d.IDPD, '')))
      )
  )
    THROW 59024, 'Existen articulos con motivo que requiere evidencia.', 1;

  UPDATE dbo.DOC_CTRL_MERMA
  SET ESTATS = 'PENDIENTE',
      ID_ESTATUS = 2,
      USER_R = @USER,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
  WHERE DOCMER = @DOCMER;

  SELECT TOP 1 * FROM dbo.DOC_CTRL_MERMA WHERE DOCMER = @DOCMER;
END;

CREATE OR ALTER PROCEDURE dbo.sp_merma_revisar
  @DOCMER NVARCHAR(50),
  @USER NVARCHAR(100),
  @OBS NVARCHAR(MAX)
AS
BEGIN
  SET NOCOUNT ON;

  IF LTRIM(RTRIM(ISNULL(@OBS, ''))) = ''
    THROW 59030, 'Observacion de revision es obligatoria.', 1;

  DECLARE @docEst INT;
  SELECT TOP 1 @docEst = ISNULL(ID_ESTATUS, CASE WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) IN ('PENDIENTE', 'AUTORIZADO') THEN 2 ELSE -1 END)
  FROM dbo.DOC_CTRL_MERMA
  WHERE DOCMER = @DOCMER;

  IF @docEst IS NULL
    THROW 59031, 'Documento no existe.', 1;
  IF @docEst <> 2
    THROW 59032, 'Solo se puede revisar un documento PENDIENTE.', 1;

  UPDATE dbo.DOC_CTRL_MERMA
  SET ESTATS = 'REVISAR',
      ID_ESTATUS = 4,
      USER_R = @USER,
      OBS_REV = @OBS,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
  WHERE DOCMER = @DOCMER;

  SELECT TOP 1 * FROM dbo.DOC_CTRL_MERMA WHERE DOCMER = @DOCMER;
END;

CREATE OR ALTER PROCEDURE dbo.sp_merma_contabilizar
  @DOCMER NVARCHAR(50),
  @USER NVARCHAR(100)
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @docEst INT;
    DECLARE @docSuc NVARCHAR(50);
    DECLARE @docFND DATETIME;

    SELECT TOP 1
      @docEst = ISNULL(ID_ESTATUS, CASE WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) IN ('PENDIENTE', 'AUTORIZADO') THEN 2 ELSE -1 END),
      @docSuc = LTRIM(RTRIM(ISNULL(SUC, ''))),
      @docFND = FCND
    FROM dbo.DOC_CTRL_MERMA WITH (UPDLOCK, HOLDLOCK)
    WHERE DOCMER = @DOCMER;

    IF @docEst IS NULL
      THROW 59040, 'Documento no existe.', 1;

    IF @docEst <> 2
      THROW 59041, 'Solo se puede contabilizar un documento PENDIENTE.', 1;

    IF NOT EXISTS (
      SELECT 1 FROM dbo.DET_ART_MERMA
      WHERE DOCMER = @DOCMER
        AND ISNULL(BLOQ, 0) <> -1
    )
      THROW 59042, 'Documento sin articulos activos.', 1;

    DECLARE @clsm FLOAT;
    SELECT TOP 1 @clsm = CMOV
    FROM dbo.DAT_CMOV
    WHERE UPPER(LTRIM(RTRIM(ISNULL(RELACION, '')))) = 'MERMA'
      AND UPPER(LTRIM(RTRIM(ISNULL(MODULO, '')))) = 'INVENTARIO'
      AND UPPER(LTRIM(RTRIM(ISNULL(TIPO, '')))) = 'CARGO'
    ORDER BY CMOV ASC;

    IF @clsm IS NULL
      SET @clsm = 555;

    DECLARE @docMb51 BIGINT;
    SELECT @docMb51 = TRY_CONVERT(BIGINT, NDOC)
    FROM dbo.DAT_CMOV WITH (UPDLOCK, HOLDLOCK)
    WHERE CMOV = @clsm;

    IF @docMb51 IS NULL SET @docMb51 = 300000000;
    SET @docMb51 = @docMb51 + 1;

    UPDATE dbo.DAT_CMOV
    SET NDOC = @docMb51
    WHERE CMOV = @clsm;

    INSERT INTO dbo.DAT_MB51
      (IDPD, [USER], CLSM, DOCP, ART, CTDA, CTOT, FCND, FCNC, TXT, ALMACEN, VTAESP, SUC)
    SELECT
      CONVERT(NVARCHAR(36), NEWID()),
      @USER,
      @clsm,
      @DOCMER,
      LTRIM(RTRIM(ISNULL(d.ART, ''))),
      -ABS(ISNULL(d.CTD, 0)),
      -ABS(ISNULL(d.CTD, 0)) * ISNULL(TRY_CONVERT(FLOAT, d.CTO), 0),
      ISNULL(@docFND, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))),
      CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
      CONCAT('MERMA DOC ', @DOCMER),
      '001',
      0,
      @docSuc
    FROM dbo.DET_ART_MERMA d
    WHERE d.DOCMER = @DOCMER
      AND ISNULL(d.BLOQ, 0) <> -1;

    UPDATE a
    SET a.STOCK = ISNULL(a.STOCK, 0) - ISNULL(d.CTD, 0)
    FROM dbo.DAT_ART a
    JOIN dbo.DET_ART_MERMA d
      ON LTRIM(RTRIM(ISNULL(a.ART, ''))) = LTRIM(RTRIM(ISNULL(d.ART, '')))
     AND LTRIM(RTRIM(ISNULL(a.SUC, ''))) = @docSuc
    WHERE d.DOCMER = @DOCMER
      AND ISNULL(d.BLOQ, 0) <> -1;

    UPDATE m
    SET m.NARTS = agg.narts,
        m.TOTAL = agg.total,
        m.ESTATS = 'CONTABILIZADO',
        m.ID_ESTATUS = 5,
        m.FCNC = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
        m.USER_A = @USER,
        m.DOC_MB51 = CONVERT(NVARCHAR(50), @docMb51),
        m.FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
    FROM dbo.DOC_CTRL_MERMA m
    CROSS APPLY (
      SELECT
        SUM(CASE WHEN ISNULL(x.BLOQ, 0) = -1 THEN 0 ELSE ISNULL(x.CTD, 0) END) AS narts,
        SUM(CASE WHEN ISNULL(x.BLOQ, 0) = -1 THEN 0 ELSE ISNULL(x.CTD, 0) * ISNULL(x.CTO, 0) END) AS total
      FROM dbo.DET_ART_MERMA x
      WHERE x.DOCMER = m.DOCMER
    ) agg
    WHERE m.DOCMER = @DOCMER;

    DECLARE @negativos INT;
    SELECT @negativos = COUNT(1)
    FROM dbo.DAT_ART a
    JOIN dbo.DET_ART_MERMA d
      ON LTRIM(RTRIM(ISNULL(a.ART, ''))) = LTRIM(RTRIM(ISNULL(d.ART, '')))
     AND LTRIM(RTRIM(ISNULL(a.SUC, ''))) = @docSuc
    WHERE d.DOCMER = @DOCMER
      AND ISNULL(d.BLOQ, 0) <> -1
      AND ISNULL(a.STOCK, 0) < 0;

    COMMIT TRANSACTION;

    SELECT
      DOCMER,
      ESTATS,
      ID_ESTATUS,
      DOC_MB51,
      NARTS,
      TOTAL,
      FCNC,
      ISNULL(@negativos, 0) AS STOCK_NEGATIVO_ITEMS
    FROM dbo.DOC_CTRL_MERMA
    WHERE DOCMER = @DOCMER;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_merma_anular
  @DOCMER NVARCHAR(50),
  @USER NVARCHAR(100),
  @OBS NVARCHAR(MAX)
AS
BEGIN
  SET NOCOUNT ON;

  IF LTRIM(RTRIM(ISNULL(@OBS, ''))) = ''
    THROW 59050, 'Observacion de anulacion es obligatoria.', 1;

  DECLARE @docEst INT;
  SELECT TOP 1 @docEst = ISNULL(ID_ESTATUS, CASE
      WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) = 'ABIERTO' THEN 1
      WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) IN ('PENDIENTE', 'AUTORIZADO') THEN 2
      WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) IN ('REVISAR', 'REVISION') THEN 4
      ELSE -1
    END)
  FROM dbo.DOC_CTRL_MERMA
  WHERE DOCMER = @DOCMER;

  IF @docEst IS NULL
    THROW 59051, 'Documento no existe.', 1;

  IF @docEst NOT IN (1, 2, 4)
    THROW 59052, 'Solo se puede anular documento ABIERTO/PENDIENTE/REVISAR.', 1;

  UPDATE dbo.DOC_CTRL_MERMA
  SET ESTATS = 'ANULADO',
      ID_ESTATUS = 3,
      USER_A = @USER,
      OBS_ANUL = @OBS,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
  WHERE DOCMER = @DOCMER;

  SELECT TOP 1 * FROM dbo.DOC_CTRL_MERMA WHERE DOCMER = @DOCMER;
END;

CREATE OR ALTER PROCEDURE dbo.sp_ps_pago_finalize
  @IDFOL NVARCHAR(255),
  @FORMAS_JSON NVARCHAR(MAX),
  @USER NVARCHAR(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @startedTran BIT = 0;
  DECLARE @idfolNorm NVARCHAR(255) = LTRIM(RTRIM(ISNULL(@IDFOL, '')));
  DECLARE @idfolActual NVARCHAR(255);
  DECLARE @idfolInicial NVARCHAR(255);
  DECLARE @idfolVisibleNuevo NVARCHAR(255);
  DECLARE @folioConsecNuevo INT = NULL;
  DECLARE @traActual NVARCHAR(255);
  DECLARE @traVisibleNuevo NVARCHAR(255);
  DECLARE @origenAut VARCHAR(2);
  DECLARE @tipoVisibleFinal VARCHAR(2);
  DECLARE @folioActualUpper NVARCHAR(255);
  DECLARE @formasJsonNorm NVARCHAR(MAX) = LTRIM(RTRIM(ISNULL(@FORMAS_JSON, '')));
  DECLARE @userNorm NVARCHAR(255) = NULLIF(LTRIM(RTRIM(ISNULL(@USER, ''))), '');
  DECLARE @fechaProceso DATETIME = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()));
  DECLARE @fechaProcesoDate DATE = CONVERT(DATE, @fechaProceso);
  DECLARE @sucDb NVARCHAR(20);
  DECLARE @opvDb NVARCHAR(255);
  DECLARE @clien FLOAT;
  DECLARE @estado NVARCHAR(40);
  DECLARE @serviceType CHAR(2);
  DECLARE @isCashOut BIT = 0;
  DECLARE @hasNonCashForm BIT = 0;
  DECLARE @total DECIMAL(18, 4);
  DECLARE @sumPagos DECIMAL(18, 4);
  DECLARE @cambio DECIMAL(18, 4) = 0;
  DECLARE @cambioPendiente DECIMAL(18, 4) = 0;
  DECLARE @epsilon DECIMAL(18, 6) = 0.0001;
  DECLARE @efectivoCambioAsignado BIT = 0;
  DECLARE @folFormTable NVARCHAR(128) = NULL;
  DECLARE @folFormObjId INT = NULL;
  DECLARE @hasIDF BIT = 0;
  DECLARE @idfIsIdentity BIT = 0;
  DECLARE @hasFCN BIT = 0;
  DECLARE @hasIMPA BIT = 0;
  DECLARE @hasIMPC BIT = 0;
  DECLARE @hasIMPD BIT = 0;
  DECLARE @hasAUT BIT = 0;
  DECLARE @hasESTA BIT = 0;
  DECLARE @hasESTAF BIT = 0;
  DECLARE @sql NVARCHAR(MAX);
  DECLARE @execIdf NVARCHAR(255);
  DECLARE @formaForm NVARCHAR(40);
  DECLARE @formaImpp DECIMAL(18, 4);
  DECLARE @formaAut NVARCHAR(255);
  DECLARE @impc DECIMAL(18, 4); DECLARE @impd DECIMAL(18, 4);
  DECLARE @ctrlObjId INT = NULL;
  DECLARE @ctrlHasCTA BIT = 0;
  DECLARE @ctrlHasCLIENT BIT = 0;
  DECLARE @ctrlHasCMOV BIT = 0;
  DECLARE @ctrlHasCLSD BIT = 0;
  DECLARE @ctrlHasIMPT BIT = 0;
  DECLARE @ctrlHasNDOC BIT = 0;
  DECLARE @ctrlHasIDFOL BIT = 0;
  DECLARE @ctrlHasSUC BIT = 0;
  DECLARE @ctrlHasOPV BIT = 0;
  DECLARE @ctrlHasIDOPV BIT = 0;
  DECLARE @ctrlHasTIPO BIT = 0;
  DECLARE @ctrlHasRTXT BIT = 0;
  DECLARE @ctrlHasFCND BIT = 0;
  DECLARE @ctrlHasFCN BIT = 0;
  DECLARE @ctrlHasFCNR BIT = 0;
  DECLARE @ctrlHasFECHA BIT = 0;
  DECLARE @ctrlClassCol NVARCHAR(10) = NULL;
  DECLARE @datCmovObjId INT = OBJECT_ID('dbo.DAT_CMOV');
  DECLARE @datCmovHasRelacion BIT = 0;
  DECLARE @datCmovHasCmov BIT = 0;
  DECLARE @datCmovHasTipo BIT = 0;
  DECLARE @lineTipps NVARCHAR(10);
  DECLARE @lineOrd NVARCHAR(255);
  DECLARE @lineTotal DECIMAL(18, 4);
  DECLARE @movClass INT;
  DECLARE @cta NVARCHAR(255);
  DECLARE @lineImpt DECIMAL(18, 4);
  DECLARE @lineIdFol NVARCHAR(255);
  DECLARE @rtxt NVARCHAR(255);
  DECLARE @ndoc NVARCHAR(255);
  DECLARE @opvAudit NVARCHAR(255);
  DECLARE @movErr NVARCHAR(255);

  DECLARE @FORMAS TABLE (
    ROW_ID INT IDENTITY(1,1) PRIMARY KEY,
    FORM NVARCHAR(40) NOT NULL,
    IMPP DECIMAL(18,4) NOT NULL,
    AUT NVARCHAR(255) NULL
  );

  DECLARE @LINES TABLE (
    ROW_ID INT IDENTITY(1,1) PRIMARY KEY,
    UPC NVARCHAR(10) NOT NULL,
    ORD NVARCHAR(255) NULL,
    LINE_TOTAL DECIMAL(18,4) NOT NULL
  );

  IF @idfolNorm = ''
    THROW 57120, 'IDFOL es requerido', 1;

  IF @formasJsonNorm = ''
    THROW 57121, 'FORMAS_JSON es requerido', 1;

  INSERT INTO @FORMAS (FORM, IMPP, AUT)
  SELECT
    UPPER(LTRIM(RTRIM(ISNULL(j.FORM, '')))) AS FORM,
    TRY_CONVERT(DECIMAL(18,4), j.IMPP) AS IMPP,
    NULLIF(LTRIM(RTRIM(ISNULL(j.AUT, ''))), '') AS AUT
  FROM OPENJSON(@formasJsonNorm)
  WITH (
    FORM NVARCHAR(40) '$.form',
    IMPP NVARCHAR(64) '$.impp',
    AUT NVARCHAR(255) '$.aut'
  ) j;

  IF NOT EXISTS (SELECT 1 FROM @FORMAS)
    THROW 57122, 'Debe enviar al menos una forma de pago', 1;

  IF EXISTS (
    SELECT 1
    FROM @FORMAS
    WHERE FORM = ''
      OR IMPP IS NULL
      OR IMPP <= 0
  )
    THROW 57123, 'Las formas enviadas no son válidas', 1;

  IF EXISTS (
    SELECT 1
    FROM @FORMAS
    WHERE FORM IN ('TARJETA', 'CHEQUE', 'TRANSFERENCIA', 'DEPOSITO 3RO')
      AND (AUT IS NULL OR AUT = '')
  )
    THROW 57124, 'Las formas no efectivo requieren autorización/referencia', 1;

  SET @hasNonCashForm = CASE WHEN EXISTS (SELECT 1 FROM @FORMAS WHERE FORM <> 'EFECTIVO') THEN 1 ELSE 0 END;

  BEGIN TRY
    IF @@TRANCOUNT = 0
    BEGIN
      SET @startedTran = 1;
      BEGIN TRANSACTION;
    END;

    SELECT TOP 1
      @idfolActual = LTRIM(RTRIM(ISNULL(IDFOL, ''))),
      @idfolInicial = ISNULL(NULLIF(LTRIM(RTRIM(ISNULL(IDFOLINICIAL, ''))), ''), LTRIM(RTRIM(ISNULL(IDFOL, '')))),
      @traActual = LTRIM(RTRIM(ISNULL(TRA, ''))),
      @origenAut = CASE
        WHEN UPPER(LTRIM(RTRIM(ISNULL(ORIGEN_AUT, '')))) IN ('CA', 'VF')
          THEN UPPER(LTRIM(RTRIM(ISNULL(ORIGEN_AUT, ''))))
        WHEN UPPER(LTRIM(RTRIM(ISNULL(AUT, '')))) IN ('DVF', 'VF')
          THEN 'VF'
        ELSE 'CA'
      END,
      @sucDb = LTRIM(RTRIM(ISNULL(SUC, ''))),
      @opvDb = LTRIM(RTRIM(ISNULL(OPV, ''))),
      @clien = TRY_CONVERT(FLOAT, CLIEN),
      @estado = UPPER(LTRIM(RTRIM(ISNULL(ESTA, ''))))
    FROM dbo.PV_CTR_FOL_ASVR WITH (UPDLOCK, HOLDLOCK)
    WHERE IDFOL = @idfolNorm
       OR IDFOLINICIAL = @idfolNorm
    ORDER BY CASE WHEN IDFOL = @idfolNorm THEN 0 ELSE 1 END, FCN DESC, FCNM DESC;

    IF ISNULL(@idfolActual, '') = ''
      THROW 57125, 'El folio PS no existe', 1;

    SET @idfolNorm = @idfolActual;
    IF ISNULL(@idfolInicial, '') = ''
      SET @idfolInicial = @idfolActual;
    SET @tipoVisibleFinal = CASE
      WHEN UPPER(ISNULL(@origenAut, 'CA')) = 'VF'
        OR (UPPER(ISNULL(@origenAut, 'CA')) = 'CA' AND @hasNonCashForm = 1)
        THEN 'VF'
      ELSE 'CA'
    END;
    SET @folioActualUpper = UPPER(@idfolActual);
    SET @idfolVisibleNuevo = @idfolActual;
    SET @traVisibleNuevo = NULLIF(@traActual, '');

    IF CHARINDEX('-' + @tipoVisibleFinal + '-', @folioActualUpper) = 0
    BEGIN
      EXEC dbo.sp_pv_next_visible_folio
        @SUC = @sucDb,
        @TIPO_FOLIO = @tipoVisibleFinal,
        @FECHA = @fechaProcesoDate,
        @IDFOL_OUT = @idfolVisibleNuevo OUTPUT,
        @CONSEC_OUT = @folioConsecNuevo OUTPUT;

      IF ISNULL(LTRIM(RTRIM(@idfolVisibleNuevo)), '') = ''
        THROW 57135, 'No se pudo generar folio visible final para PS', 1;

      SET @traVisibleNuevo = CONVERT(NVARCHAR(255), @folioConsecNuevo);
    END;

    IF @estado = 'PAGADO'
      THROW 57126, 'El folio ya se encuentra en estado PAGADO', 1;

    IF NOT EXISTS (SELECT 1 FROM dbo.PV_TICKET_LOG WHERE IDFOL = @idfolNorm)
      THROW 57127, 'El ticket no contiene renglones', 1;

    IF EXISTS (
      SELECT 1
      FROM dbo.PV_TICKET_LOG
      WHERE IDFOL = @idfolNorm
        AND (LTRIM(RTRIM(ISNULL(ORD, ''))) = '' OR TRY_CONVERT(DECIMAL(18,4), PVTA) IS NULL)
    )
      THROW 57128, 'Todas las líneas del ticket deben tener referencia y PVTA capturado', 1;

    SELECT TOP 1 @serviceType = UPPER(LTRIM(RTRIM(ISNULL(UPC, ''))))
    FROM dbo.PV_TICKET_LOG
    WHERE IDFOL = @idfolNorm;

    IF @serviceType IN ('DG', 'DC')
      SET @isCashOut = 1;

    SELECT @total = ROUND(SUM(
      ISNULL(TRY_CONVERT(DECIMAL(18,4), PVTA), 0) *
      ISNULL(NULLIF(TRY_CONVERT(DECIMAL(18,4), CTD), 0), 1)
    ), 4)
    FROM dbo.PV_TICKET_LOG
    WHERE IDFOL = @idfolNorm;

    IF @total IS NULL OR @total <= 0
      THROW 57129, 'El total del ticket no es válido', 1;

    SELECT @sumPagos = ROUND(SUM(IMPP), 4)
    FROM @FORMAS;

    IF @sumPagos IS NULL OR @sumPagos <= 0
      THROW 57130, 'El total de formas de pago no es válido', 1;

    IF @sumPagos + @epsilon < @total
      THROW 57131, 'El importe de formas no cubre el total del ticket', 1;

    IF @sumPagos > @total + @epsilon
       AND NOT EXISTS (SELECT 1 FROM @FORMAS WHERE FORM = 'EFECTIVO')
      THROW 57132, 'Solo EFECTIVO puede exceder el total para generar cambio', 1;

    IF OBJECT_ID('dbo.PV_CTR_FOL_FORM', 'U') IS NOT NULL
      SET @folFormTable = N'dbo.PV_CTR_FOL_FORM';
    ELSE IF OBJECT_ID('dbo.PV_CTR_FOL_FORM_SVR', 'U') IS NOT NULL
      SET @folFormTable = N'dbo.PV_CTR_FOL_FORM_SVR';
    ELSE
      THROW 57133, 'No existe tabla de formas de pago (PV_CTR_FOL_FORM/PV_CTR_FOL_FORM_SVR)', 1;

    SET @folFormObjId = OBJECT_ID(@folFormTable);

    SELECT
      @hasIDF = MAX(CASE WHEN UPPER(name) = 'IDF' THEN 1 ELSE 0 END),
      @hasFCN = MAX(CASE WHEN UPPER(name) = 'FCN' THEN 1 ELSE 0 END),
      @hasIMPA = MAX(CASE WHEN UPPER(name) = 'IMPA' THEN 1 ELSE 0 END),
      @hasIMPC = MAX(CASE WHEN UPPER(name) = 'IMPC' THEN 1 ELSE 0 END),
      @hasIMPD = MAX(CASE WHEN UPPER(name) = 'IMPD' THEN 1 ELSE 0 END),
      @hasAUT = MAX(CASE WHEN UPPER(name) = 'AUT' THEN 1 ELSE 0 END),
      @hasESTA = MAX(CASE WHEN UPPER(name) = 'ESTA' THEN 1 ELSE 0 END),
      @hasESTAF = MAX(CASE WHEN UPPER(name) = 'ESTAF' THEN 1 ELSE 0 END)
    FROM sys.columns
    WHERE object_id = @folFormObjId;

    IF @hasIDF = 1
      SET @idfIsIdentity = CASE WHEN COLUMNPROPERTY(@folFormObjId, 'IDF', 'IsIdentity') = 1 THEN 1 ELSE 0 END;

    SET @sql = N'DELETE FROM ' + @folFormTable + N' WHERE IDFOL = @pIDFOL;';
    EXEC sys.sp_executesql
      @sql,
      N'@pIDFOL NVARCHAR(255)',
      @pIDFOL = @idfolNorm;

    SET @cambio = CASE WHEN @sumPagos > @total THEN ROUND(@sumPagos - @total, 4) ELSE 0 END;
    SET @cambioPendiente = @cambio;

    DECLARE forma_cursor CURSOR LOCAL FAST_FORWARD FOR
      SELECT FORM, IMPP, AUT
      FROM @FORMAS
      ORDER BY ROW_ID;

    OPEN forma_cursor;
    FETCH NEXT FROM forma_cursor INTO @formaForm, @formaImpp, @formaAut;
    WHILE @@FETCH_STATUS = 0
    BEGIN
      SET @impc = 0;
      IF @cambioPendiente > 0 AND @efectivoCambioAsignado = 0 AND @formaForm = 'EFECTIVO'
      BEGIN
        SET @impc = @cambioPendiente;
        SET @cambioPendiente = 0;
        SET @efectivoCambioAsignado = 1;
      END;

      SET @impd = ROUND(@formaImpp - @impc, 4); SET @execIdf = CONVERT(NVARCHAR(255), NEWID());

      SET @sql = N'INSERT INTO ' + @folFormTable + N' (' +
        CASE WHEN @hasIDF = 1 AND @idfIsIdentity = 0 THEN N'IDF, ' ELSE N'' END +
        N'IDFOL' +
        CASE WHEN @hasFCN = 1 THEN N', FCN' ELSE N'' END +
        N', FORM' +
        CASE WHEN @hasIMPA = 1 THEN N', IMPA' ELSE N'' END +
        N', IMPP' +
        CASE WHEN @hasIMPC = 1 THEN N', IMPC' ELSE N'' END +
        CASE WHEN @hasIMPD = 1 THEN N', IMPD' ELSE N'' END +
        CASE WHEN @hasAUT = 1 THEN N', AUT' ELSE N'' END +
        CASE WHEN @hasESTA = 1 THEN N', ESTA' ELSE N'' END +
        CASE WHEN @hasESTAF = 1 THEN N', ESTAF' ELSE N'' END +
        N') VALUES (' +
        CASE WHEN @hasIDF = 1 AND @idfIsIdentity = 0 THEN N'@pIDF, ' ELSE N'' END +
        N'@pIDFOL' +
        CASE WHEN @hasFCN = 1 THEN N', @pNOW' ELSE N'' END +
        N', @pFORM' +
        CASE WHEN @hasIMPA = 1 THEN N', NULL' ELSE N'' END +
        N', @pIMPP' +
        CASE WHEN @hasIMPC = 1 THEN N', @pIMPC' ELSE N'' END +
        CASE WHEN @hasIMPD = 1 THEN N', @pIMPD' ELSE N'' END +
        CASE WHEN @hasAUT = 1 THEN N', @pAUT' ELSE N'' END +
        CASE WHEN @hasESTA = 1 THEN N', NULL' ELSE N'' END +
        CASE WHEN @hasESTAF = 1 THEN N', NULL' ELSE N'' END +
        N');';

      EXEC sys.sp_executesql
        @sql,
        N'@pIDF NVARCHAR(255), @pIDFOL NVARCHAR(255), @pNOW DATETIME, @pFORM NVARCHAR(40), @pIMPP DECIMAL(18,4), @pIMPC DECIMAL(18,4), @pIMPD DECIMAL(18,4), @pAUT NVARCHAR(255)',
        @pIDF = @execIdf,
        @pIDFOL = @idfolVisibleNuevo,
        @pNOW = @fechaProceso,
        @pFORM = @formaForm,
        @pIMPP = @formaImpp,
        @pIMPC = @impc,
        @pIMPD = @impd,
        @pAUT = @formaAut;

      FETCH NEXT FROM forma_cursor INTO @formaForm, @formaImpp, @formaAut;
    END;
    CLOSE forma_cursor;
    DEALLOCATE forma_cursor;

    SET @ctrlObjId = OBJECT_ID('dbo.DAT_CTRL_CTAS');
    IF @ctrlObjId IS NOT NULL
    BEGIN
      SELECT
        @ctrlHasCTA = MAX(CASE WHEN UPPER(name) = 'CTA' THEN 1 ELSE 0 END),
        @ctrlHasCLIENT = MAX(CASE WHEN UPPER(name) = 'CLIENT' THEN 1 ELSE 0 END),
        @ctrlHasCMOV = MAX(CASE WHEN UPPER(name) = 'CMOV' THEN 1 ELSE 0 END),
        @ctrlHasCLSD = MAX(CASE WHEN UPPER(name) = 'CLSD' THEN 1 ELSE 0 END),
        @ctrlHasIMPT = MAX(CASE WHEN UPPER(name) = 'IMPT' THEN 1 ELSE 0 END),
        @ctrlHasNDOC = MAX(CASE WHEN UPPER(name) = 'NDOC' THEN 1 ELSE 0 END),
        @ctrlHasIDFOL = MAX(CASE WHEN UPPER(name) = 'IDFOL' THEN 1 ELSE 0 END),
        @ctrlHasSUC = MAX(CASE WHEN UPPER(name) = 'SUC' THEN 1 ELSE 0 END),
        @ctrlHasOPV = MAX(CASE WHEN UPPER(name) = 'OPV' THEN 1 ELSE 0 END),
        @ctrlHasIDOPV = MAX(CASE WHEN UPPER(name) = 'IDOPV' THEN 1 ELSE 0 END),
        @ctrlHasTIPO = MAX(CASE WHEN UPPER(name) = 'TIPO' THEN 1 ELSE 0 END),
        @ctrlHasRTXT = MAX(CASE WHEN UPPER(name) = 'RTXT' THEN 1 ELSE 0 END),
        @ctrlHasFCND = MAX(CASE WHEN UPPER(name) = 'FCND' THEN 1 ELSE 0 END),
        @ctrlHasFCN = MAX(CASE WHEN UPPER(name) = 'FCN' THEN 1 ELSE 0 END),
        @ctrlHasFCNR = MAX(CASE WHEN UPPER(name) = 'FCNR' THEN 1 ELSE 0 END),
        @ctrlHasFECHA = MAX(CASE WHEN UPPER(name) = 'FECHA' THEN 1 ELSE 0 END)
      FROM sys.columns
      WHERE object_id = @ctrlObjId;

      SET @ctrlClassCol = CASE
        WHEN @ctrlHasCMOV = 1 THEN 'CMOV'
        WHEN @ctrlHasCLSD = 1 THEN 'CLSD'
        ELSE NULL
      END;

      IF @datCmovObjId IS NOT NULL
      BEGIN
        SELECT
          @datCmovHasRelacion = MAX(CASE WHEN UPPER(name) = 'RELACION' THEN 1 ELSE 0 END),
          @datCmovHasCmov = MAX(CASE WHEN UPPER(name) = 'CMOV' THEN 1 ELSE 0 END),
          @datCmovHasTipo = MAX(CASE WHEN UPPER(name) = 'TIPO' THEN 1 ELSE 0 END)
        FROM sys.columns
        WHERE object_id = @datCmovObjId;
      END

      IF @ctrlHasCTA = 1 AND @ctrlHasCLIENT = 1 AND @ctrlHasIMPT = 1 AND @ctrlHasIDFOL = 1 AND @ctrlClassCol IS NOT NULL
      BEGIN
        INSERT INTO @LINES (UPC, ORD, LINE_TOTAL)
        SELECT
          UPPER(LTRIM(RTRIM(ISNULL(UPC, '')))) AS UPC,
          LTRIM(RTRIM(ISNULL(ORD, ''))) AS ORD,
          ROUND(
            ISNULL(TRY_CONVERT(DECIMAL(18,4), PVTA), 0)
            * ISNULL(NULLIF(TRY_CONVERT(DECIMAL(18,4), CTD), 0), 1),
            4
          ) AS LINE_TOTAL
        FROM dbo.PV_TICKET_LOG
        WHERE IDFOL = @idfolNorm;

        DECLARE line_cursor CURSOR LOCAL FAST_FORWARD FOR
          SELECT UPC, ORD, LINE_TOTAL
          FROM @LINES
          ORDER BY ROW_ID;

        OPEN line_cursor;
        FETCH NEXT FROM line_cursor INTO @lineTipps, @lineOrd, @lineTotal;
        WHILE @@FETCH_STATUS = 0
        BEGIN
          SET @movClass = NULL;
          SET @cta = NULL;
          SET @lineImpt = ABS(ISNULL(@lineTotal, 0));
          SET @lineIdFol = @idfolVisibleNuevo;
          SET @rtxt = 'Abono a cliente ticket ' + @idfolVisibleNuevo;

          IF @datCmovObjId IS NOT NULL
             AND @datCmovHasRelacion = 1
             AND @datCmovHasCmov = 1
          BEGIN
            IF @datCmovHasTipo = 1
            BEGIN
              SELECT TOP 1 @movClass = TRY_CONVERT(INT, CMOV)
              FROM dbo.DAT_CMOV
              WHERE UPPER(LTRIM(RTRIM(ISNULL(RELACION, '')))) = @lineTipps
                AND UPPER(LTRIM(RTRIM(ISNULL(TIPO, '')))) = 'ABONO'
              ORDER BY CMOV;
            END
            ELSE
            BEGIN
              SELECT TOP 1 @movClass = TRY_CONVERT(INT, CMOV)
              FROM dbo.DAT_CMOV
              WHERE UPPER(LTRIM(RTRIM(ISNULL(RELACION, '')))) = @lineTipps
              ORDER BY CMOV;
            END
          END
          ELSE
          BEGIN
            IF @lineTipps = 'DG'
            BEGIN
              IF OBJECT_ID('dbo.DAT_CMOV_C', 'U') IS NOT NULL
                 AND COL_LENGTH('dbo.DAT_CMOV_C', 'RELACION') IS NOT NULL
                 AND COL_LENGTH('dbo.DAT_CMOV_C', 'CMOV') IS NOT NULL
              BEGIN
                SELECT TOP 1 @movClass = TRY_CONVERT(INT, CMOV)
                FROM dbo.DAT_CMOV_C
                WHERE UPPER(LTRIM(RTRIM(ISNULL(RELACION, '')))) = @lineTipps;
              END
            END
            ELSE
            BEGIN
              IF OBJECT_ID('dbo.DAT_CMOV_A', 'U') IS NOT NULL
                 AND COL_LENGTH('dbo.DAT_CMOV_A', 'RELACION') IS NOT NULL
                 AND COL_LENGTH('dbo.DAT_CMOV_A', 'CMOV') IS NOT NULL
              BEGIN
                SELECT TOP 1 @movClass = TRY_CONVERT(INT, CMOV)
                FROM dbo.DAT_CMOV_A
                WHERE UPPER(LTRIM(RTRIM(ISNULL(RELACION, '')))) = @lineTipps;
              END
            END
          END;

          IF @lineTipps = 'DG'
          BEGIN
            SET @lineImpt = -ABS(ISNULL(@lineTotal, 0));
            SET @lineIdFol = @idfolVisibleNuevo;
            SET @rtxt = LTRIM(RTRIM(ISNULL(@lineOrd, ''))) + ' ticket ' + @idfolVisibleNuevo;
          END
          ELSE IF @lineTipps = 'DC'
          BEGIN
            SET @lineImpt = ABS(ISNULL(@lineTotal, 0));
            SET @lineIdFol = @idfolVisibleNuevo;
            SET @rtxt = LTRIM(RTRIM(ISNULL(@lineOrd, ''))) + ' ticket ' + @idfolVisibleNuevo;
          END
          ELSE
          BEGIN
            SET @lineImpt = ABS(ISNULL(@lineTotal, 0));
            SET @lineIdFol = CASE
              WHEN LTRIM(RTRIM(ISNULL(@lineOrd, ''))) = '' THEN @idfolVisibleNuevo
              ELSE @lineOrd
            END;
            SET @rtxt = 'Abono a cliente ticket ' + @idfolVisibleNuevo;
          END;

          IF @movClass IS NULL
          BEGIN
            SET @movErr = N'No se encontró CLSD (CMOV) para RELACION '
              + ISNULL(@lineTipps, N'')
              + N' con TIPO=ABONO.';
            THROW 57134, @movErr, 1;
          END;

          IF OBJECT_ID('dbo.DAT_CAT_CTAS', 'U') IS NOT NULL
             AND COL_LENGTH('dbo.DAT_CAT_CTAS', 'CTA') IS NOT NULL
             AND COL_LENGTH('dbo.DAT_CAT_CTAS', 'RELACION') IS NOT NULL
          BEGIN
            SELECT TOP 1
              @cta = LTRIM(RTRIM(ISNULL(CTA, '')))
            FROM dbo.DAT_CAT_CTAS
            WHERE UPPER(LTRIM(RTRIM(ISNULL(RELACION, '')))) = @lineTipps
              AND (
                COL_LENGTH('dbo.DAT_CAT_CTAS', 'SUC') IS NULL
                OR UPPER(LTRIM(RTRIM(ISNULL(SUC, '')))) = UPPER(ISNULL(@sucDb, ''))
                OR LTRIM(RTRIM(ISNULL(SUC, ''))) = ''
              )
            ORDER BY CASE
              WHEN COL_LENGTH('dbo.DAT_CAT_CTAS', 'SUC') IS NULL THEN 0
              WHEN UPPER(LTRIM(RTRIM(ISNULL(SUC, '')))) = UPPER(ISNULL(@sucDb, '')) THEN 0
              ELSE 1
            END;
          END;

          IF @cta IS NOT NULL AND LTRIM(RTRIM(@cta)) <> ''
          BEGIN
            SET @ndoc = CONCAT(
              'PS',
              CONVERT(VARCHAR(8), @fechaProceso, 112),
              REPLACE(CONVERT(VARCHAR(8), @fechaProceso, 108), ':', ''),
              RIGHT(REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', ''), 6)
            );
            SET @opvAudit = COALESCE(@userNorm, @opvDb);

            SET @sql = N'
              INSERT INTO dbo.DAT_CTRL_CTAS (
                CTA,
                CLIENT,
                ' + @ctrlClassCol + N',
                IMPT' +
                CASE WHEN @ctrlHasNDOC = 1 THEN N', NDOC' ELSE N'' END +
                N', IDFOL' +
                CASE WHEN @ctrlHasSUC = 1 THEN N', SUC' ELSE N'' END +
                CASE WHEN @ctrlHasOPV = 1 THEN N', OPV' ELSE N'' END +
                CASE WHEN @ctrlHasIDOPV = 1 THEN N', IDOPV' ELSE N'' END +
                CASE WHEN @ctrlHasTIPO = 1 THEN N', TIPO' ELSE N'' END +
                CASE WHEN @ctrlHasRTXT = 1 THEN N', RTXT' ELSE N'' END +
                CASE WHEN @ctrlHasFCND = 1 THEN N', FCND' ELSE N'' END +
                CASE WHEN @ctrlHasFCN = 1 THEN N', FCN' ELSE N'' END +
                CASE WHEN @ctrlHasFCNR = 1 THEN N', FCNR' ELSE N'' END +
                CASE WHEN @ctrlHasFECHA = 1 THEN N', FECHA' ELSE N'' END + N'
              )
              VALUES (
                @pCTA,
                @pCLIENT,
                @pCLSD,
                @pIMPT' +
                CASE WHEN @ctrlHasNDOC = 1 THEN N', @pNDOC' ELSE N'' END +
                N', @pIDFOL' +
                CASE WHEN @ctrlHasSUC = 1 THEN N', @pSUC' ELSE N'' END +
                CASE WHEN @ctrlHasOPV = 1 THEN N', @pOPV' ELSE N'' END +
                CASE WHEN @ctrlHasIDOPV = 1 THEN N', @pOPV' ELSE N'' END +
                CASE WHEN @ctrlHasTIPO = 1 THEN N', @pTIPO' ELSE N'' END +
                CASE WHEN @ctrlHasRTXT = 1 THEN N', @pRTXT' ELSE N'' END +
                CASE WHEN @ctrlHasFCND = 1 THEN N', @pNOW' ELSE N'' END +
                CASE WHEN @ctrlHasFCN = 1 THEN N', @pNOW' ELSE N'' END +
                CASE WHEN @ctrlHasFCNR = 1 THEN N', @pNOW' ELSE N'' END +
                CASE WHEN @ctrlHasFECHA = 1 THEN N', @pNOW' ELSE N'' END + N'
              );';

            EXEC sys.sp_executesql
              @sql,
              N'@pCTA NVARCHAR(255), @pCLIENT FLOAT, @pCLSD INT, @pIMPT DECIMAL(18,4), @pNDOC NVARCHAR(255), @pIDFOL NVARCHAR(255), @pSUC NVARCHAR(20), @pOPV NVARCHAR(255), @pTIPO NVARCHAR(10), @pRTXT NVARCHAR(255), @pNOW DATETIME',
              @pCTA = @cta,
              @pCLIENT = @clien,
              @pCLSD = @movClass,
              @pIMPT = @lineImpt,
              @pNDOC = @ndoc,
              @pIDFOL = @lineIdFol,
              @pSUC = @sucDb,
              @pOPV = @opvAudit,
              @pTIPO = @lineTipps,
              @pRTXT = @rtxt,
              @pNOW = @fechaProceso;
          END;

          FETCH NEXT FROM line_cursor INTO @lineTipps, @lineOrd, @lineTotal;
        END;
        CLOSE line_cursor;
        DEALLOCATE line_cursor;
      END;
    END;

    IF UPPER(ISNULL(@idfolVisibleNuevo, '')) <> UPPER(ISNULL(@idfolNorm, ''))
    BEGIN
      UPDATE dbo.PV_TICKET_LOG
      SET IDFOL = @idfolVisibleNuevo
      WHERE IDFOL = @idfolNorm;
    END;

    UPDATE dbo.PV_CTR_FOL_ASVR
    SET
      IDFOL = @idfolVisibleNuevo,
      TRA = COALESCE(NULLIF(@traVisibleNuevo, ''), TRA),
      ESTA = 'PAGADO',
      IMPT = CASE WHEN @isCashOut = 1 THEN (@total * -1) ELSE @total END,
      IMPP = @sumPagos,
      FPGO = 'FINALIZADO',
      FCNM = @fechaProceso,
      OPVM = COALESCE(@userNorm, OPVM),
      IDFOLINICIAL = ISNULL(NULLIF(LTRIM(RTRIM(IDFOLINICIAL)), ''), @idfolInicial),
      ORIGEN_AUT = @tipoVisibleFinal
    WHERE IDFOL = @idfolNorm;

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      COMMIT TRANSACTION;

    SELECT
      @idfolVisibleNuevo AS IDFOL,
      'PAGADO' AS ESTA,
      @total AS TOTAL,
      @sumPagos AS PAGADO,
      @cambio AS CAMBIO;
  END TRY
  BEGIN CATCH
    IF CURSOR_STATUS('local', 'forma_cursor') >= -1
    BEGIN
      CLOSE forma_cursor;
      DEALLOCATE forma_cursor;
    END

    IF CURSOR_STATUS('local', 'line_cursor') >= -1
    BEGIN
      CLOSE line_cursor;
      DEALLOCATE line_cursor;
    END

    IF @startedTran = 1 AND @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE OR ALTER PROCEDURE dbo.sp_merma_auditar
  @DOCMER NVARCHAR(50),
  @USER NVARCHAR(100),
  @OBS_AUDIT NVARCHAR(MAX),
  @CONFIRM_FISICA BIT = 1
AS
BEGIN
  SET NOCOUNT ON;

  IF ISNULL(@CONFIRM_FISICA, 0) = 0
    THROW 59060, 'Debe confirmar revision fisica.', 1;

  DECLARE @docEst INT;
  SELECT TOP 1 @docEst = ISNULL(ID_ESTATUS, CASE
      WHEN UPPER(LTRIM(RTRIM(ISNULL(ESTATS, '')))) IN ('CONTABILIZADO', 'COTABILIZADO', 'COTIBILIZADO', 'PROCESADO') THEN 5
      ELSE -1
    END)
  FROM dbo.DOC_CTRL_MERMA
  WHERE DOCMER = @DOCMER;

  IF @docEst IS NULL
    THROW 59061, 'Documento no existe.', 1;

  IF @docEst <> 5
    THROW 59062, 'Solo se puede auditar documento CONTABILIZADO.', 1;

  UPDATE dbo.DOC_CTRL_MERMA
  SET ESTATS = 'AUDITADO',
      ID_ESTATUS = 6,
      FCNAUD = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
      USER_AUD = @USER,
      OBS_AUDIT = @OBS_AUDIT,
      FCNM = CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME()))
  WHERE DOCMER = @DOCMER;

  SELECT TOP 1 * FROM dbo.DOC_CTRL_MERMA WHERE DOCMER = @DOCMER;
END;

CREATE OR ALTER PROCEDURE dbo.sp_factclientshp_create
(
  @SUC VARCHAR(10),

  @RazonSocialReceptor NVARCHAR(255),
  @RfcReceptor NVARCHAR(255),
  @EmailReceptor NVARCHAR(255),
  @RfcEmisor NVARCHAR(255),
  @UsoCfdi NVARCHAR(255),
  @CodigoPostalReceptor NVARCHAR(255),
  @RegimenFiscalReceptor FLOAT,

  @DOMI NVARCHAR(255) = NULL,
  @NCEL NVARCHAR(255) = NULL,
  @OPTICA NVARCHAR(255) = NULL,

  @IDC_OUT FLOAT OUTPUT
)
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  -- ==========================
  -- Validaciones mínimas
  -- ==========================
  IF ISNULL(LTRIM(RTRIM(@SUC)),'') = ''
    THROW 51001, 'SUC es obligatorio', 1;

  IF ISNULL(LTRIM(RTRIM(@RazonSocialReceptor)),'') = ''
    THROW 51002, 'RazonSocialReceptor es obligatorio', 1;

  IF ISNULL(LTRIM(RTRIM(@RfcReceptor)),'') = ''
    THROW 51003, 'RfcReceptor es obligatorio', 1;

  IF ISNULL(LTRIM(RTRIM(@EmailReceptor)),'') = ''
    THROW 51004, 'EmailReceptor es obligatorio', 1;

  IF ISNULL(LTRIM(RTRIM(@RfcEmisor)),'') = ''
    THROW 51005, 'RfcEmisor es obligatorio', 1;

  IF ISNULL(LTRIM(RTRIM(@UsoCfdi)),'') = ''
    THROW 51006, 'UsoCfdi es obligatorio', 1;

  IF ISNULL(LTRIM(RTRIM(@CodigoPostalReceptor)),'') = ''
    THROW 51007, 'CodigoPostalReceptor es obligatorio', 1;

  IF @RegimenFiscalReceptor IS NULL
    THROW 51008, 'RegimenFiscalReceptor es obligatorio', 1;

  DECLARE @Hoy DATE = CAST(CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())) AS DATE);
  DECLARE @FechaSerie INT = DATEDIFF(DAY,'1899-12-30',@Hoy);
  DECLARE @N INT;

  DECLARE @IDC_DEC DECIMAL(18,0);
  DECLARE @IDC_STR VARCHAR(40);
  DECLARE @SufSUC VARCHAR(2) = RIGHT(@SUC,2);

  BEGIN TRAN;
  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;

  -- ==========================
  -- Secuencia diaria
  -- ==========================
  IF EXISTS (
      SELECT 1
      FROM dbo.FACT_CLIENT_IDC_SEQ WITH (UPDLOCK, HOLDLOCK)
      WHERE SUC = @SUC AND FECHA = @Hoy
  )
  BEGIN
      SELECT @N = NEXT_N
      FROM dbo.FACT_CLIENT_IDC_SEQ WITH (UPDLOCK, HOLDLOCK)
      WHERE SUC = @SUC AND FECHA = @Hoy;

      UPDATE dbo.FACT_CLIENT_IDC_SEQ
      SET NEXT_N = NEXT_N + 1
      WHERE SUC = @SUC AND FECHA = @Hoy;
  END
  ELSE
  BEGIN
      SET @N = 1;

      INSERT INTO dbo.FACT_CLIENT_IDC_SEQ (SUC, FECHA, NEXT_N)
      VALUES (@SUC, @Hoy, 2);
  END

  -- ==========================
  -- Construcción del IDC
  -- ==========================
  SET @IDC_STR = @SufSUC
               + CAST(@FechaSerie AS VARCHAR(10))
               + FORMAT(@N,'0000');

  SET @IDC_DEC = CAST(@IDC_STR AS DECIMAL(18,0));

  -- Seguridad extra por histórico
  WHILE EXISTS (
      SELECT 1
      FROM dbo.FACT_CLIENT_SHP WITH (UPDLOCK, HOLDLOCK)
      WHERE IDC = CONVERT(FLOAT,@IDC_DEC)
  )
  BEGIN
      SET @N = @N + 1;
      SET @IDC_STR = @SufSUC
                   + CAST(@FechaSerie AS VARCHAR(10))
                   + FORMAT(@N,'0000');
      SET @IDC_DEC = CAST(@IDC_STR AS DECIMAL(18,0));
  END

  -- ==========================
  -- INSERT
  -- ==========================
  INSERT INTO dbo.FACT_CLIENT_SHP
  (
    IDC,
    FCNR,
    RazonSocialReceptor,
    DOMI,
    RfcReceptor,
    NCEL,
    EmailReceptor,
    RfcEmisor,
    OPTICA,
    UsoCfdi,
    CodigoPostalReceptor,
    RegimenFiscalReceptor,
    SUC
  )
  VALUES
  (
    CONVERT(FLOAT,@IDC_DEC),
    CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
    @RazonSocialReceptor,
    @DOMI,
    @RfcReceptor,
    @NCEL,
    @EmailReceptor,
    @RfcEmisor,
    @OPTICA,
    @UsoCfdi,
    @CodigoPostalReceptor,
    @RegimenFiscalReceptor,
    @SUC
  );

  SET @IDC_OUT = CONVERT(FLOAT,@IDC_DEC);

  COMMIT;

  SELECT * FROM dbo.FACT_CLIENT_SHP WHERE IDC = @IDC_OUT;
END

CREATE OR ALTER PROCEDURE dbo.sp_sugeridos_crear_oc
  @SUC NVARCHAR(20),
  @NPROV INT,
  @USR NVARCHAR(100),
  @TIPO NVARCHAR(80) = N'NORMAL',
  @SUG BIT = 1,
  @ITEMS_JSON NVARCHAR(MAX)
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @sucNorm NVARCHAR(20) = UPPER(LTRIM(RTRIM(ISNULL(@SUC, N''))));
  DECLARE @usrNorm NVARCHAR(100) = LTRIM(RTRIM(ISNULL(@USR, N'')));
  IF @sucNorm = N'' THROW 51001, 'La sucursal es requerida para crear la orden.', 1;
  IF @NPROV IS NULL THROW 51002, 'El proveedor es requerido para crear la orden.', 1;
  IF @usrNorm = N'' THROW 51003, 'El usuario es requerido para crear la orden.', 1;
  IF ISJSON(@ITEMS_JSON) <> 1 THROW 51004, 'El detalle de articulos no es JSON valido.', 1;

  DECLARE @items TABLE (
    POS INT IDENTITY(1,1) NOT NULL,
    ART NVARCHAR(50) NOT NULL,
    CTO MONEY NOT NULL,
    CTDPED FLOAT NOT NULL,
    UNCOM NVARCHAR(80) NULL
  );

  INSERT INTO @items (ART, CTO, CTDPED, UNCOM)
  SELECT
    LTRIM(RTRIM(JSON_VALUE(value, '$.art'))),
    TRY_CONVERT(MONEY, JSON_VALUE(value, '$.cto')),
    TRY_CONVERT(FLOAT, JSON_VALUE(value, '$.ctdped')),
    NULLIF(LTRIM(RTRIM(JSON_VALUE(value, '$.uncom'))), N'')
  FROM OPENJSON(@ITEMS_JSON)
  WHERE LTRIM(RTRIM(ISNULL(JSON_VALUE(value, '$.art'), N''))) <> N''
    AND TRY_CONVERT(FLOAT, JSON_VALUE(value, '$.ctdped')) > 0
    AND TRY_CONVERT(MONEY, JSON_VALUE(value, '$.cto')) IS NOT NULL;

  DECLARE @NPED NVARCHAR(50);

  BEGIN TRANSACTION;

  EXEC sys.sp_getapplock
    @Resource = 'REC_CAB_PED_NPED',
    @LockMode = 'Exclusive',
    @LockOwner = 'Transaction',
    @LockTimeout = 15000;

  SELECT @NPED = CONVERT(NVARCHAR(50), ISNULL(MAX(TRY_CONVERT(BIGINT, NPED)), 450000000) + 1)
  FROM dbo.REC_CAB_PED WITH (UPDLOCK, HOLDLOCK)
  WHERE TRY_CONVERT(BIGINT, NPED) IS NOT NULL;

  INSERT INTO dbo.REC_CAB_PED (NPED, SUC, TIPO, NPROV, USR, FCNP, FCNC, IMPP, NART, FCNR, ESTATUS, SUG)
  SELECT
    @NPED,
    @sucNorm,
    NULLIF(LTRIM(RTRIM(@TIPO)), N''),
    @NPROV,
    @usrNorm,
    CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())),
    NULL,
    ISNULL(SUM(CTO * CTDPED), 0),
    COUNT(1),
    NULL,
    N'ABIERTO',
    CASE WHEN @SUG = 1 THEN -1 ELSE 0 END
  FROM @items;

  INSERT INTO dbo.REC_DET_PED (BLOQ, RECI, POS, DREC, IDPED, NPED, ART, CTO, CTDPED, UNCOM, CTDREC)
  SELECT
    0,
    0,
    POS,
    NULL,
    CONCAT(POS, N'-', @NPED),
    @NPED,
    ART,
    CTO,
    CTDPED,
    UNCOM,
    NULL
  FROM @items
  ORDER BY POS;

  COMMIT TRANSACTION;

  SELECT @NPED AS NPED;
END;

CREATE OR ALTER PROCEDURE dbo.sp_formmod_list_today
  @OPV nvarchar(255),
  @IDFOL nvarchar(255) = NULL,
  @CLIEN nvarchar(255) = NULL
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @opvNorm nvarchar(255) = UPPER(LTRIM(RTRIM(ISNULL(@OPV, N''))));
  DECLARE @idfolNorm nvarchar(255) = LTRIM(RTRIM(ISNULL(@IDFOL, N'')));
  DECLARE @clienNorm nvarchar(255) = LTRIM(RTRIM(ISNULL(@CLIEN, N'')));

  IF @opvNorm = N''
  BEGIN
    THROW 50001, 'El parametro @OPV es obligatorio.', 1;
  END;

  DECLARE @formAutSelect nvarchar(400) =
    CASE
      WHEN COL_LENGTH('dbo.PV_CTR_FOL_FORM_SVR', 'AUT') IS NULL
        THEN N'CAST(NULL AS nvarchar(255))'
      ELSE N'CAST(F.AUT AS nvarchar(255))'
    END;

  DECLARE @sql nvarchar(max) = N'
    SELECT
      CONVERT(date, A.FCN) AS FCN,
      CAST(A.AUT AS nvarchar(10)) AS AUT_ASVR,
      CAST(A.AUT AS nvarchar(10)) AS AUT,
      CAST(A.IDFOL AS nvarchar(255)) AS IDFOL,
      CAST(A.TRA AS nvarchar(255)) AS TRA,
      CAST(A.OPVM AS nvarchar(255)) AS OPVM,
      CAST(A.SUC AS nvarchar(50)) AS SUC,
      CASE
        WHEN TRY_CONVERT(decimal(19,0), A.CLIEN) IS NOT NULL
          THEN CONVERT(nvarchar(255), CONVERT(decimal(19,0), A.CLIEN))
        ELSE LTRIM(RTRIM(CONVERT(nvarchar(255), A.CLIEN)))
      END AS CLIEN,
      CAST(F.IDF AS nvarchar(255)) AS IDF,
      CAST(F.FORM AS nvarchar(255)) AS FORM,
      CAST(ISNULL(F.IMPD, 0) AS decimal(18, 2)) AS IMPD,
      ' + @formAutSelect + N' AS AUT_FORM
    FROM dbo.PV_CTR_FOL_ASVR AS A WITH (NOLOCK)
    LEFT JOIN dbo.PV_CTR_FOL_FORM_SVR AS F WITH (NOLOCK)
      ON F.IDFOL = A.IDFOL
    WHERE CONVERT(date, A.FCN) = CONVERT(date, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())))
      AND A.AUT IN (N''AD'', N''AP'', N''CR'', N''VF'')
      AND UPPER(LTRIM(RTRIM(ISNULL(A.OPVM, N'''')))) = @opvNorm
  ';

  IF @idfolNorm <> N''
    SET @sql += N' AND CAST(A.IDFOL AS nvarchar(255)) LIKE N''%'' + @idfolNorm + N''%''';

  IF @clienNorm <> N''
    SET @sql += N' AND (
      CASE
        WHEN TRY_CONVERT(decimal(19,0), A.CLIEN) IS NOT NULL
          THEN CONVERT(nvarchar(255), CONVERT(decimal(19,0), A.CLIEN))
        ELSE LTRIM(RTRIM(CONVERT(nvarchar(255), A.CLIEN)))
      END
    ) LIKE N''%'' + @clienNorm + N''%''';

  SET @sql += N' ORDER BY A.FCN DESC, A.IDFOL DESC, F.IDF DESC;';

  EXEC sys.sp_executesql
    @sql,
    N'@opvNorm nvarchar(255), @idfolNorm nvarchar(255), @clienNorm nvarchar(255)',
    @opvNorm = @opvNorm,
    @idfolNorm = @idfolNorm,
    @clienNorm = @clienNorm;
END;

CREATE OR ALTER PROCEDURE dbo.sp_formmod_update
  @OPV nvarchar(255),
  @SupervisorId nvarchar(255),
  @IDF nvarchar(255),
  @NewFORM nvarchar(255),
  @NewAUT nvarchar(255) = NULL,
  @ClearAUT bit = 0
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;

  DECLARE @opvNorm nvarchar(255) = UPPER(LTRIM(RTRIM(ISNULL(@OPV, N''))));
  DECLARE @supervisorNorm nvarchar(255) = LTRIM(RTRIM(ISNULL(@SupervisorId, N'')));
  DECLARE @idfNorm nvarchar(255) = LTRIM(RTRIM(ISNULL(@IDF, N'')));
  DECLARE @newFormNorm nvarchar(255) = UPPER(LTRIM(RTRIM(ISNULL(@NewFORM, N''))));
  DECLARE @newAutNorm nvarchar(255) = LTRIM(RTRIM(ISNULL(@NewAUT, N'')));

  IF @opvNorm = N''
    THROW 50011, 'El parametro @OPV es obligatorio.', 1;

  IF @supervisorNorm = N''
    THROW 50012, 'El parametro @SupervisorId es obligatorio.', 1;

  IF @idfNorm = N''
    THROW 50013, 'El parametro @IDF es obligatorio.', 1;

  IF @newFormNorm = N''
    THROW 50014, 'El parametro @NewFORM es obligatorio.', 1;

  IF COL_LENGTH('dbo.PV_CTR_FOL_FORM_SVR', 'AUT') IS NULL
    THROW 50015, 'La tabla PV_CTR_FOL_FORM_SVR no tiene columna AUT.', 1;

  IF NOT EXISTS (
    SELECT 1
    FROM dbo.VW_PV_FORM_TIPOTRAN_DISTINCT AS V
    WHERE UPPER(LTRIM(RTRIM(ISNULL(V.FORM, N'')))) = @newFormNorm
      AND ISNULL(V.BLOQ, 0) = 0
  )
  BEGIN
    THROW 50016, 'La forma de pago no existe en catalogo permitido o esta bloqueada.', 1;
  END;

  DECLARE @before TABLE (
    FCN date NOT NULL,
    IDFOL nvarchar(255) NOT NULL,
    AUT_ASVR nvarchar(10) NULL,
    TRA nvarchar(255) NULL,
    OPVM nvarchar(255) NULL,
    IDF nvarchar(255) NOT NULL,
    FORM nvarchar(255) NULL,
    IMPD decimal(18, 2) NOT NULL,
    AUT_FORM nvarchar(255) NULL
  );

  BEGIN TRY
    BEGIN TRANSACTION;

    INSERT INTO @before (FCN, IDFOL, AUT_ASVR, TRA, OPVM, IDF, FORM, IMPD, AUT_FORM)
    SELECT TOP (1)
      CONVERT(date, A.FCN) AS FCN,
      CAST(A.IDFOL AS nvarchar(255)) AS IDFOL,
      CAST(A.AUT AS nvarchar(10)) AS AUT_ASVR,
      CAST(A.TRA AS nvarchar(255)) AS TRA,
      CAST(A.OPVM AS nvarchar(255)) AS OPVM,
      CAST(F.IDF AS nvarchar(255)) AS IDF,
      CAST(F.FORM AS nvarchar(255)) AS FORM,
      CAST(ISNULL(F.IMPD, 0) AS decimal(18, 2)) AS IMPD,
      CAST(F.AUT AS nvarchar(255)) AS AUT_FORM
    FROM dbo.PV_CTR_FOL_FORM_SVR AS F WITH (UPDLOCK, HOLDLOCK)
    INNER JOIN dbo.PV_CTR_FOL_ASVR AS A WITH (UPDLOCK, HOLDLOCK)
      ON A.IDFOL = F.IDFOL
    WHERE CAST(F.IDF AS nvarchar(255)) = @idfNorm
      AND CONVERT(date, A.FCN) = CONVERT(date, CONVERT(datetime, dbo.fn_ioe_business_datetime(SYSUTCDATETIME())))
      AND A.AUT IN (N'AD', N'AP', N'CR', N'VF')
      AND UPPER(LTRIM(RTRIM(ISNULL(A.OPVM, N'')))) = @opvNorm;

    IF NOT EXISTS (SELECT 1 FROM @before)
    BEGIN
      THROW 50017, 'No existe detalle IDF para el OPV/logica de dia actual o AUT no permitido.', 1;
    END;

    IF EXISTS (
      SELECT 1
      FROM @before
      WHERE UPPER(LTRIM(RTRIM(ISNULL(FORM, N'')))) = @newFormNorm
    )
    BEGIN
      THROW 50018, 'La forma seleccionada es igual a la actual.', 1;
    END;

    DECLARE @beforeForm nvarchar(255) =
      (SELECT TOP (1) UPPER(LTRIM(RTRIM(ISNULL(FORM, N'')))) FROM @before);
    DECLARE @beforeAut nvarchar(255) =
      (SELECT TOP (1) LTRIM(RTRIM(ISNULL(AUT_FORM, N''))) FROM @before);

    IF @beforeForm = N'EFECTIVO' AND @newFormNorm <> N'EFECTIVO' AND @newAutNorm = N''
    BEGIN
      THROW 50019, 'Debe generar/asignar referencia para cambio de EFECTIVO a forma no efectivo.', 1;
    END;

    DECLARE @hasCloseFlag bit = 0;
    IF COL_LENGTH('dbo.PV_CTR_FOL_ASVR', 'ESTA') IS NOT NULL SET @hasCloseFlag = 1;
    IF COL_LENGTH('dbo.PV_CTR_FOL_ASVR', 'TIMBRADO') IS NOT NULL SET @hasCloseFlag = 1;
    IF COL_LENGTH('dbo.PV_CTR_FOL_ASVR', 'FACTURADO') IS NOT NULL SET @hasCloseFlag = 1;
    IF COL_LENGTH('dbo.PV_CTR_FOL_ASVR', 'CERRADO') IS NOT NULL SET @hasCloseFlag = 1;

    DECLARE @isLockedByStatus bit = 0;
    DECLARE @lockSql nvarchar(max) = N'
      SELECT @isLockedByStatusOut =
        CASE WHEN 1 = 0';

    IF COL_LENGTH('dbo.PV_CTR_FOL_ASVR', 'ESTA') IS NOT NULL
      SET @lockSql += N'
        OR UPPER(LTRIM(RTRIM(ISNULL(CONVERT(nvarchar(255), A.ESTA), '''')))) IN (''FACTURADO'', ''TIMBRADO'', ''CERRADO'', ''TRANSMITIR'')';
    IF COL_LENGTH('dbo.PV_CTR_FOL_ASVR', 'TIMBRADO') IS NOT NULL
      SET @lockSql += N'
        OR ISNULL(CONVERT(int, A.TIMBRADO), 0) <> 0';
    IF COL_LENGTH('dbo.PV_CTR_FOL_ASVR', 'FACTURADO') IS NOT NULL
      SET @lockSql += N'
        OR ISNULL(CONVERT(int, A.FACTURADO), 0) <> 0';
    IF COL_LENGTH('dbo.PV_CTR_FOL_ASVR', 'CERRADO') IS NOT NULL
      SET @lockSql += N'
        OR ISNULL(CONVERT(int, A.CERRADO), 0) <> 0';

    SET @lockSql += N'
        THEN 1
        ELSE 0
      END
      FROM dbo.PV_CTR_FOL_ASVR AS A
      INNER JOIN dbo.PV_CTR_FOL_FORM_SVR AS F
        ON F.IDFOL = A.IDFOL
      WHERE CAST(F.IDF AS nvarchar(255)) = @idfNormIn;';

    EXEC sys.sp_executesql
      @lockSql,
      N'@idfNormIn nvarchar(255), @isLockedByStatusOut bit OUTPUT',
      @idfNormIn = @idfNorm,
      @isLockedByStatusOut = @isLockedByStatus OUTPUT;

    IF @isLockedByStatus = 1
    BEGIN
      THROW 50020, 'El folio ya fue facturado/timbrado/cerrado y no permite cambio de forma.', 1;
    END;

    IF @hasCloseFlag = 0
    BEGIN
      -- TODO: agregar validacion de facturado/timbrado/cerrado segun bandera real del esquema destino.
      -- Placeholder consciente para ambientes legacy sin columnas de estatus final.
      PRINT 'TODO: validar bandera de facturado/timbrado/cerrado en esquema destino.';
    END;

    DECLARE @nextAut nvarchar(255) = NULL;
    IF @newFormNorm = N'EFECTIVO' OR @ClearAUT = 1
      SET @nextAut = NULL;
    ELSE IF @newAutNorm <> N''
      SET @nextAut = @newAutNorm;
    ELSE IF @beforeAut <> N''
      SET @nextAut = @beforeAut;

    UPDATE F
      SET F.FORM = @newFormNorm,
          F.AUT = @nextAut
    FROM dbo.PV_CTR_FOL_FORM_SVR AS F
    INNER JOIN @before AS B
      ON B.IDF = CAST(F.IDF AS nvarchar(255));

    IF @@ROWCOUNT = 0
    BEGIN
      THROW 50021, 'No se pudo actualizar la forma de pago.', 1;
    END;

    DECLARE @updatedAtUtc datetime2(0) = SYSUTCDATETIME();

    SELECT
      B.FCN,
      B.IDFOL,
      B.AUT_ASVR,
      B.TRA,
      B.OPVM,
      B.IDF,
      B.FORM AS BEFORE_FORM,
      B.AUT_FORM AS BEFORE_AUT,
      CAST(F.FORM AS nvarchar(255)) AS AFTER_FORM,
      CAST(F.AUT AS nvarchar(255)) AS AFTER_AUT,
      B.IMPD,
      @supervisorNorm AS SUPERVISOR_ID,
      @updatedAtUtc AS UPDATED_AT_UTC
    FROM @before AS B
    INNER JOIN dbo.PV_CTR_FOL_FORM_SVR AS F
      ON CAST(F.IDF AS nvarchar(255)) = B.IDF;

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0
      ROLLBACK TRANSACTION;
    THROW;
  END CATCH;
END;

CREATE OR ALTER PROCEDURE dbo.sp_dat_mb51_search
  @fecha_doc_desde DATETIME = NULL,
  @fecha_doc_hasta DATETIME = NULL,
  @fecha_cont_desde DATETIME = NULL,
  @fecha_cont_hasta DATETIME = NULL,
  @art NVARCHAR(255) = NULL,
  @docp NVARCHAR(255) = NULL,
  @almacen VARCHAR(255) = NULL,
  @suc VARCHAR(255) = NULL,
  @clsm FLOAT = NULL,
  @vtaesp INT = NULL,
  @user NVARCHAR(255) = NULL,
  @txt NVARCHAR(255) = NULL,
  @arts NVARCHAR(MAX) = NULL,
  @almacenes NVARCHAR(MAX) = NULL,
  @sucs NVARCHAR(MAX) = NULL,
  @clsms NVARCHAR(MAX) = NULL,
  @page INT = 1,
  @limit INT = 50
AS
BEGIN
  SET NOCOUNT ON;

  SELECT
    IDPD,
    [USER],
    CLSM,
    DOCP,
    ART,
    CTDA,
    CTOT,
    CONVERT(varchar(33), FCND, 126) AS FCND,
    CONVERT(varchar(33), FCNC, 126) AS FCNC,
    TXT,
    ALMACEN,
    VTAESP,
    SUC,
    COUNT(1) OVER() AS TOTAL_COUNT
  FROM dbo.DAT_MB51
  WHERE (@fecha_doc_desde IS NULL OR FCND >= @fecha_doc_desde)
    AND (@fecha_doc_hasta IS NULL OR FCND <= @fecha_doc_hasta)
    AND (@fecha_cont_desde IS NULL OR FCNC >= @fecha_cont_desde)
    AND (@fecha_cont_hasta IS NULL OR FCNC <= @fecha_cont_hasta)
    AND (
      (@arts IS NULL AND (@art IS NULL OR ART LIKE '%' + @art + '%'))
      OR (@arts IS NOT NULL AND EXISTS (
        SELECT 1 FROM string_split(@arts, ',') s
        WHERE LTRIM(RTRIM(s.value)) = ART
      ))
    )
    AND (@docp IS NULL OR DOCP LIKE '%' + @docp + '%')
    AND (
      (@almacenes IS NULL AND (@almacen IS NULL OR ALMACEN = @almacen))
      OR (@almacenes IS NOT NULL AND EXISTS (
        SELECT 1 FROM string_split(@almacenes, ',') s
        WHERE LTRIM(RTRIM(s.value)) = ALMACEN
      ))
    )
    AND (
      (@sucs IS NULL AND (@suc IS NULL OR SUC = @suc))
      OR (@sucs IS NOT NULL AND EXISTS (
        SELECT 1 FROM string_split(@sucs, ',') s
        WHERE LTRIM(RTRIM(s.value)) = SUC
      ))
    )
    AND (
      (@clsms IS NULL AND (@clsm IS NULL OR CLSM = @clsm))
      OR (@clsms IS NOT NULL AND EXISTS (
        SELECT 1 FROM string_split(@clsms, ',') s
        WHERE TRY_CAST(LTRIM(RTRIM(s.value)) AS FLOAT) = CLSM
      ))
    )
    AND (@vtaesp IS NULL OR VTAESP = @vtaesp)
    AND (@user IS NULL OR [USER] LIKE '%' + @user + '%')
    AND (@txt IS NULL OR TXT LIKE '%' + @txt + '%')
  ORDER BY FCND DESC
  OFFSET CASE WHEN @page IS NULL OR @limit IS NULL OR @page < 1 OR @limit < 1 THEN 0 ELSE (@page - 1) * @limit END ROWS
  FETCH NEXT CASE WHEN @limit IS NULL OR @limit < 1 THEN 2147483647 ELSE @limit END ROWS ONLY;
END;
